insert into private.study_guides (guide, chunks, sha256) values ('study_guide_lag_bua111', 49, '98f84c208139f5f9aecb1b61907e2cc7580cefbba9c939e9811d81e8180e79d3');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 1, $study_guide${"guide":"study_guide_lag_bua111","code":"LAG-BUA111","courseId":"0d6682a1-b7b0-5109-b86a-2fabbfbea8b4","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"2c52224a-5802-5a5e-b84b-2638dbcb39b0","create":true,"after":{"title":"Principles of Marketing","body":"Every topic is examinable.","outcomes":["Define marketing and the marketing mix elements.","Explain the marketing concepts and how they are practised.","Identify the key forces in the marketing environment.","Explain how consumers and organisations make buying decisions.","Explain the marketing system and the marketing management process.","Design and apply a market segmentation, targeting and positioning approach.","Measure market demand and prepare simple sales forecasts.","Explain the place of digital and social media in modern marketing.","Apply marketing concepts, principles and theories to solve marketing problems."],"assessment":["The exam is objective (CBT), with some theory questions. Expect definitions, lists, counts, classifications and short applications to Nigerian businesses.","A few questions need simple calculations: market potential, market share, forecasts, channel contacts and digital marketing metrics (Topics 6 to 10)."]}},"retire":[],"notes":[{"kind":"note","itemId":"a0a46b7e-747c-5977-8eff-cf3cab6b52d9","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Meaning, Exchange Process and Functions of Marketing","body":"The main definitions of marketing and who gave them; needs, wants and demands; value and satisfaction; exchange, its five conditions, transactions, transfers and relationships; markets; the eight functions of marketing in three groups; utility; the importance of marketing to consumers, firms and society.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"The main definitions of marketing and who gave them; needs, wants and demands; value and satisfaction; exchange, its five conditions, transactions, transfers and relationships; markets; the eight functions of marketing in three groups; utility; the importance of marketing to consumers, firms and society."}],"lessons":[{"number":"1.1","title":"What marketing means","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The ultimate goal of any business is to "},{"text":"identify and satisfy customers","bold":true},{"text":"; that goal is reached only through effective "},{"text":"marketing","bold":true},{"text":" activities. Marketing is not merely selling, and it is not confined to one department: it is an attitude of mind and a business philosophy for the whole organisation."}]},{"text":[{"text":"There is "},{"text":"no single, universally accepted definition","bold":true},{"text":". Learn these:"}]}]},{"type":"table","header":[[{"text":"Defined by"}],[{"text":"Definition (key words)"}]],"rows":[[[{"text":"Stanton (1981)"}],[{"text":"Societal sense:","bold":true},{"text":" any exchange activity intended to satisfy human wants. "},{"text":"Business sense:","bold":true},{"text":" a system of business action designed to plan, price, promote and distribute want-satisfying goods and services to markets"}]],[[{"text":"Kotler (1988)"}],[{"text":"A "},{"text":"social and managerial process","bold":true},{"text":" by which individuals and groups obtain what they need and want through creating and exchanging products and value with others"}]],[[{"text":"Kotler and Armstrong"}],[{"text":"The process by which companies "},{"text":"create value for customers and build strong customer relationships","bold":true},{"text":" in order to "},{"text":"capture value from customers in return","bold":true}]],[[{"text":"Kotler and Keller (shortest)"}],[{"text":"Meeting needs profitably","bold":true}]],[[{"text":"Chartered Institute of Marketing (CIM, UK)"}],[{"text":"The management process responsible for "},{"text":"identifying, anticipating and satisfying customer requirements profitably","bold":true}]],[[{"text":"AMA (current)"}],[{"text":"The activity, set of institutions and processes for "},{"text":"creating, communicating, delivering and exchanging offerings","bold":true},{"text":" that have value for "},{"text":"customers, clients, partners and society at large","bold":true}]],[[{"text":"AMA (1985)"}],[{"text":"The process of planning and executing the conception, pricing, promotion and distribution of ideas, goods and services to create exchanges that satisfy individual and organisational objectives"}]],[[{"text":"AMA (early, 1960)"}],[{"text":"The performance of business activities that "},{"text":"direct the flow of goods and services from producer to consumer or user","bold":true}]],[[{"text":"Working definition"}],[{"text":"All activities aimed at "},{"text":"identifying and satisfying customer needs through beneficial exchanges with target markets","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The working definition requires 4 things: (1) finding out what customers need; (2) developing a product or service to satisfy those needs; (3) positioning it to satisfy the needs; (4) deciding the marketing mix to price, promote and distribute it."}]},{"text":[{"text":"Peter Drucker:","bold":true},{"text":" \"the aim of marketing is to make selling superfluous\", i.e. know the customer so well that the product fits and sells itself."}]},{"text":[{"text":"Definitions fall into "},{"text":"3 groups","bold":true},{"text":": marketing as a "},{"text":"process","bold":true},{"text":"; as a "},{"text":"concept or philosophy","bold":true},{"text":" of business; as an "},{"text":"orientation","bold":true},{"text":"."}]},{"text":[{"text":"Marketing is "},{"text":"both a functional area of management and an overall business philosophy","bold":true},{"text":" which recognises that identifying, satisfying and retaining customers is the key to success. It "},{"text":"focuses the firm's or individual's attention on the needs and wants of the marketplace","bold":true},{"text":"."}]},{"text":[{"text":"Micromark$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 2, $study_guide$eting (micro definition):","bold":true},{"text":" firm-oriented, narrow view: marketing activities from the point of view of the individual organisation (e.g. identifying, anticipating and satisfying needs profitably for the firm)."}]},{"text":[{"text":"Macromarketing (macro definition):","bold":true},{"text":" broad, societal view: exchange activities and exchange systems in society, and how marketing systems relate to the rest of society."}]},{"text":[{"text":"Nonbusiness marketing:","bold":true},{"text":" marketing carried out by "},{"text":"non-profit organisations","bold":true},{"text":"."}]},{"text":[{"text":"What can be marketed:","bold":true},{"text":" goods, services, events, experiences, persons, places, properties, organisations, information and "},{"text":"ideas","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Narrow (traditional) concept:","bold":true},{"text":" physical transfer of goods from producer to consumer; product-oriented, exchange of goods for money. "},{"text":"Broad (modern) concept:","bold":true},{"text":" everything from before production to after-sales service; customer-oriented, earning profit through customer satisfaction."}]},{"text":[{"text":"Weakness of the early AMA (1960) definition:","bold":true},{"text":" it treats marketing as starting "},{"text":"only after production","bold":true},{"text":", ignoring the study of customer needs. Marketing actually "},{"text":"starts before production","bold":true},{"text":" (finding out what customers need) and "},{"text":"continues after the sale","bold":true},{"text":" (customer service, relationship building). So \"marketing begins after production and ends at the sale\" is "},{"text":"false","bold":true},{"text":". Selling and advertising are "},{"text":"only part","bold":true},{"text":" of marketing."}]},{"text":[{"text":"Stanton's \""},{"text":"total system","bold":true},{"text":" of business activities designed to plan, price, promote and distribute want-satisfying products to target markets to achieve organisational objectives\" stresses that marketing is "},{"text":"a set of related activities that work together","bold":true},{"text":", not one activity."}]},{"text":[{"text":"Kotler's \""},{"text":"societal process","bold":true},{"text":" by which individuals and groups obtain what they need and want through creating, offering and freely exchanging products and services of value\" is a "},{"text":"social","bold":true},{"text":" definition. \"Meeting needs profitably\" and the CIM version are "},{"text":"managerial","bold":true},{"text":" definitions."}]},{"text":[{"text":"The 2004 change to the AMA definition moved the emphasis from the 4Ps to "},{"text":"customers and customer relationships","bold":true},{"text":". The current AMA wording, \"creating, communicating, delivering and exchanging offerings with value\", is the modern view that goes beyond a mere sale. The CIM definition is often called the most concise."}]},{"text":[{"text":"The essence of every modern definition: "},{"text":"delivering superior value to customers while balancing profitability","bold":true},{"text":". The scope of marketing covers ideation, value creation and strategic distribution, orchestrating value creation, delivery and customer engagement, not advertising alone. "},{"text":"Market segmentation and research","bold":true},{"text":" need the deepest understanding of consumer insights."}]},{"text":[{"text":"A Lagos State ministry of health jingle urging handwashing to prevent cholera sells nothing, yet it "},{"text":"is","bold":true},{"text":" marketing: marketing applies to ideas and non-profit causes. Commercialised bodies such as NIPOST now also market actively."}]}]}]},{"number":"1.2","title":"Needs, wants, demands, value and satisfaction","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Needs:","bold":true},{"text":" states of "},{"text":"felt deprivation","bold":true},{"text":" (hunger, thirst, the desire to belong). They are a basic part of human make-up; "},{"text":"marketers do not create needs","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physical needs:","bold":true},{"text":" food, clothing, warmth, "},{"text":"safety","bold":true},{"text":"."}]},{"text":[{"text":"Social needs:","bold":true},{"text":" "},{"text":"belonging and affection","bold":true},{"text":"."}]},{"text":[{"text":"Individual needs:","bold":true},{"text":" "},{"text":"knowledge and self-expression","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Wants:","bold":true},{"text":" the form a need takes as it is "},{"text":"shaped by culture and individual personality","bold":true},{"text":"."}]},{"text":[{"text":"Demands:","bold":true},{"text":" wants "},{"text":"backed by buying power","bold":true},{"text":". (The quantity of goods people are willing and able to buy in a given period.)"}]},{"text":[{"text":"Market offering:","bold":true},{"text":" a combination of products, services, information or experiences offered to satisfy a need or want."}]},{"text":[{"text":"Customer perceived value:","bold":true},{"text":" the customer's evaluation of the difference between "},{"text":"all the benefits and all the costs","bold":true},{"text":" of an offering compared with competing offers."}],"blocks":[{"type":"paragraph","text":[{"text":"Customer perceived value = total customer benefit − total customer cost"}]}]},{"text":[{"text":"Customer satisfaction:","bold":true},{"text":" depends on product "},{"text":"performance relative to expectations","bold":true},{"text":":"}]}]},{"type":"table","header":[[{"text":"Performance vs expectations"}],[{"text":"Result"}]],"rows":[[[{"text":"Falls short"}],[{"text":"Dissatisfied"}]],[[{"text":"Matches"}],[{"text":"Satisfied"}]],[[{"text":"Exceeds"}],[{"text":"Highly satisfied (delighted)"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Tunde at UNILAG$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 3, $study_guide$ is hungry ("},{"text":"need","bold":true},{"text":"). He specifically wants jollof rice with chicken ("},{"text":"want","bold":true},{"text":"). With ₦2,000 in his pocket and the willingness to buy, the want becomes a "},{"text":"demand","bold":true},{"text":"."}]},{"text":[{"text":"One need, different wants: a hungry person in Ibadan wants amala and ewedu; one in Enugu wants abacha. Culture shapes the want."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a desire with no money is still only a "},{"text":"want","bold":true},{"text":". Ada earns ₦250,000 a month with no savings or loan access and desires an ₦80 million SUV. ₦80,000,000 ÷ ₦250,000 = 320 months of her "},{"text":"entire","bold":true},{"text":" pay (about 26.7 years, rounded). Her desire is "},{"text":"a want that is not yet a demand","bold":true},{"text":"."}]},{"text":[{"text":"Worked value example: Bisi values the benefits of Phone A at ₦420,000; its total cost is ₦350,000 price + ₦20,000 transport and set-up = ₦370,000, so value = ₦420,000 − ₦370,000 = ₦50,000. Phone B: benefits ₦380,000, cost ₦300,000 + ₦10,000 = ₦310,000, so value = ₦380,000 − ₦310,000 = ₦70,000. She picks "},{"text":"Phone B","bold":true},{"text":", which gives more value even though Phone A has more benefits."}]},{"text":[{"text":"Chika expected her generator to run quietly for ten hours; it is noisy and stops after four. Performance fell short, so she is "},{"text":"dissatisfied","bold":true},{"text":"."}]}]}]},{"number":"1.3","title":"Exchange, transactions, relationships and markets","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"4 ways to obtain a product:","bold":true},{"text":" self-production, coercion, begging, "},{"text":"exchange","bold":true},{"text":". Marketing is based on "},{"text":"exchange","bold":true},{"text":"."}]},{"text":[{"text":"Exchange:","bold":true},{"text":" the act of obtaining a desired object from someone by "},{"text":"offering something in return","bold":true},{"text":". It is the process through which transfer of ownership and rights takes place. "},{"text":"5 conditions:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"There are "},{"text":"at least two parties","bold":true},{"text":"."}]},{"text":[{"text":"Each party has "},{"text":"something that might be of value","bold":true},{"text":" to the other."}]},{"text":[{"text":"Each party is "},{"text":"capable of communication and delivery","bold":true},{"text":"."}]},{"text":[{"text":"Each party is "},{"text":"free to accept or reject","bold":true},{"text":" the offer."}]},{"text":[{"text":"Each party believes it is "},{"text":"appropriate or desirable","bold":true},{"text":" to deal with the other."}]}]}]},{"text":[{"text":"Money is "},{"text":"not","bold":true},{"text":" a condition. Exchange is "},{"text":"value-creating","bold":true},{"text":": it normally leaves "},{"text":"both parties better off","bold":true},{"text":"."}]},{"text":[{"text":"Exchange is a "},{"text":"process","bold":true},{"text":" (parties negotiating towards agreement). When agreement is reached, a "},{"text":"transaction","bold":true},{"text":" takes place."}]},{"text":[{"text":"Transaction:","bold":true},{"text":" a "},{"text":"trade of values between two parties","bold":true},{"text":"; the basic unit of exchange. Elements: (1) at least two things of value; (2) agreed-upon conditions; (3) a time of agreement; (4) a place of agreement. No intermediary is required."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Monetary transaction:","bold":true},{"text":" goods for money. "},{"text":"Barter transaction:","bold":true},{"text":" goods or services for other goods or services."}]}]}]},{"text":[{"text":"Transfer:","bold":true},{"text":" A gives to B but receives "},{"text":"nothing tangible in return","bold":true},{"text":" (gifts, donations, subsidies)."}]},{"text":[{"text":"Relationship marketing:","bold":true},{"text":" building, maintaining and enhancing "},{"text":"long-term, mutually satisfying relationships","bold":true},{"text":" with customers, rather than single sales (transaction marketing)."}]},{"text":[{"text":"Market:","bold":true},{"text":" the set of "},{"text":"all actual and potential buyers","bold":true},{"text":" of a product. (Traditionally also a physical place where buyers and sellers meet to exchange.)"}]},{"text":[{"text":"Marketer:","bold":true},{"text":" one who seeks a response (attention, purchase, vote, donation) from another party, the "},{"text":"prospect","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Robbers who take a traveller's phone and leave him some cash have not made an exchange: he was "},{"text":"not free to reject","bold":true},{"text":" the offer (coercion)."}]},{"text":[{"text":"A Kano tomato farmer and a Lagos restaurant owner who do not know of each other, with no way to send goods, lack condition 3, "},{"text":"communication and delivery","bold":true},{"text":"."}]},{"text":[{"text":"Benue farmer gives ten tubers of yam for a bag of fertiliser: "},{"text":"barter","bold":true},{"text":". Mrs Okafor pays ₦75,000 at Mile 12 for a bag of rice: "},{"text":"monetary transaction","bold":true},{"text":". A company donates food to flood victims in Kogi State: "},{"text":"transfer","bold":true},{"text":"."}]},{"text":[{"text":"Evolution of marketing (6 stages):","bold":true},{"text":" (1) "},{"text":"self-sufficient","bold":true},{"text":" stage (people produced what they consumed); (2) "},{"text":"barter","bold":true},{"text":" stage (goods for goods, before money); (3) "},{"text":"marketing system","bold":true},{"text":" stage (a fixed place for exchange, to save travelling); (4) "},{"text":"monetary","bold":true},{"text":" stage (currency, first metal, solved barter's problems); (5) "},{"text":"town marketing","bold":true},{"text":" (transport, communication and industry grew); (6) "},{"text":"internati$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 4, $study_guide$onal marketing","bold":true},{"text":" (worldwide trade, supported by bodies such as GATT, now the WTO, UNCTAD and ITC)."}]},{"text":[{"text":"Relationship marketing builds the long-term customer base that keeps firms like MTN and GTBank growing in a dynamic economy."}]}]}]},{"number":"1.4","title":"Functions of marketing and utility","mustKnow":[{"type":"paragraph","text":[{"text":"The traditional classification groups "},{"text":"8 functions","bold":true},{"text":" into "},{"text":"3","bold":true},{"text":":"}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Functions"}]],"rows":[[[{"text":"Exchange functions"}],[{"text":"1. Buying 2. Selling"}]],[[{"text":"Physical supply (physical distribution) functions"}],[{"text":"3. Transportation 4. Storage"}]],[[{"text":"Facilitating functions"}],[{"text":"5. Financing 6. Risk bearing 7. Standardisation and grading 8. Market information"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Buying:","bold":true},{"text":" deciding what to buy, choosing suppliers and placing orders. "},{"text":"Selling:","bold":true},{"text":" finding buyers and persuading them to buy; transfers ownership."}]},{"text":[{"text":"Transportation:","bold":true},{"text":" moving goods from where they are produced to where they are wanted. "},{"text":"Storage:","bold":true},{"text":" holding goods from when they are produced until they are wanted."}]},{"text":[{"text":"Financing:","bold":true},{"text":" providing funds or credit to carry out marketing. "},{"text":"Risk bearing:","bold":true},{"text":" carrying the risk of loss (damage, theft, price falls), often through insurance. "},{"text":"Standardisation and grading:","bold":true},{"text":" setting standards and sorting products into classes by quality and size. "},{"text":"Market information:","bold":true},{"text":" gathering and analysing information on customers, competitors and the market (marketing research)."}]},{"text":[{"text":"Utility","bold":true},{"text":" (want-satisfying power) created:"}]}]},{"type":"table","header":[[{"text":"Utility"}],[{"text":"Created by"}]],"rows":[[[{"text":"Form"}],[{"text":"Production","bold":true},{"text":" (marketing guides it through product planning and development)"}]],[[{"text":"Place"}],[{"text":"Transportation"}]],[[{"text":"Time"}],[{"text":"Storage"}]],[[{"text":"Possession"}],[{"text":"Exchange (selling, credit and instalment terms)"}]],[[{"text":"Information"}],[{"text":"Research and promotion"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Kebbi miller buys paddy at harvest and sells in the lean season: "},{"text":"storage","bold":true},{"text":" (time utility). Trucks moving tomatoes from Kano to Lagos: "},{"text":"transportation","bold":true},{"text":" (place utility)."}]},{"text":[{"text":"Ondo cocoa sorted into Grade I and Grade II before export: "},{"text":"standardisation and grading","bold":true},{"text":". Lagos importer buying marine insurance: "},{"text":"risk bearing","bold":true},{"text":". Distributor letting supermarkets pay in 30 days: "},{"text":"financing","bold":true},{"text":". A noodles maker surveying Abuja shoppers and tracking rivals' prices: "},{"text":"market information","bold":true},{"text":". Supermarket choosing soap brands and placing orders: "},{"text":"buying","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" transportation is a "},{"text":"physical supply","bold":true},{"text":" function, not facilitating. Financing and risk bearing are facilitating, not exchange functions."}]},{"text":[{"text":"An Ikeja shop letting customers take home a ₦450,000 sofa today and pay monthly creates "},{"text":"possession utility","bold":true},{"text":". Form utility is the one mainly created by production, not marketing."}]}]}]},{"number":"1.5","title":"Importance of marketing","mustKnow":[{"type":"paragraph","text":[{"text":"The basic role of marketing is to "},{"text":"enhance the growth of economies and the standard of living of individuals","bold":true},{"text":". Marketing has been called \"the creation and delivery of a standard of living to society\"."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To consumers (4):","bold":true},{"text":" customer satisfaction; selection facility (wider choice); product information; higher standard of living."}]},{"text":[{"text":"To the firm (4):","bold":true},{"text":" revenue generation (for survival and growth, by attracting and keeping customers); information for planning and decision-making; mass distribution; increase in goodwill (loyal, long-term customers)."}]},{"text":[{"text":"To society and the economy (5):","bold":true},{"text":" employment generation; poverty eradication; rise in standard of living; creation of utility; optimum utilisation of resources."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Jobs come from buying, selling, retailing, transport, advertising, warehousing and distribution. Good distribution systems for raw materials and finished goods speed up growth in developing countries."}]},{"text":[{"text":"Marketing "},{"text":"bridges the gap between consumer needs and available solutions","bold":true},{"text":", and creates societal value by aligning offerings with consumer needs and social welfare."}]},{"text":[{"text":"Marketing does "},{"text":"not","bold":true},{"text":" guarantee a monopoly, remove all business risk, end the need for production planning, or fix one price everywhere."}]},{"text":[{"text":"Firms such as Cadbury Nigeria and Nestlé Nigeria have stepped up marketing; formerly non-profit bodies such as NIPOST, once commercialised, now market to earn profit."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"No single definition; know Stanton, Kotler, Kotler and Armstrong, CIM, AMA and \"meeting needs profitably\"."}]},{"text":[{"text":"Micromarketing = firm view; macromarketing = societal view; nonbusiness mar$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 5, $study_guide$keting = non-profits."}]},{"text":[{"text":"Needs (physical, social, individual) are not created by marketers; wants are shaped by culture; demands are wants plus buying power."}]},{"text":[{"text":"Perceived value = total benefits − total costs; satisfaction = performance vs expectations."}]},{"text":[{"text":"Exchange: 5 conditions, money not one; transaction = trade of values (barter or monetary); transfer = nothing tangible back."}]},{"text":[{"text":"Market = all actual and potential buyers; marketer seeks a response from a prospect."}]},{"text":[{"text":"8 functions: exchange (buying, selling), physical supply (transportation, storage), facilitating (financing, risk bearing, standardisation and grading, market information)."}]},{"text":[{"text":"Form utility comes mainly from production; marketing adds place, time, possession, information."}]},{"text":[{"text":"Marketing benefits consumers, firms and society; its basic role is economic growth and a higher standard of living."}]}]}],"theory":{"itemId":"332e0367-626a-5b48-8fc3-ecc4d2116468","question":[{"type":"paragraph","text":[{"text":"Classify each activity into its marketing function and group: (i) a warehouse holds yam until the lean season; (ii) a bank gives a distributor a 60-day trade loan; (iii) a trader negotiates and hands over goods to a buyer; (iv) eggs are sorted by size into crates."}]}]},"practice":[{"topic":"Meaning, Exchange Process and Functions of Marketing","named":false}]}},{"kind":"note","itemId":"2a99914d-dc35-5d15-872e-bb9950ba0689","sourceKey":"guide-topic:2","position":2,"payload":{"title":"Marketing Management","body":"The definitions of marketing management and why it is called demand management; the eight demand states and the marketing task that matches each; the marketing management process (analysis, planning, implementation, control); the marketing plan, marketing control and the marketing audit; appraising the marketing effort; the importance of marketing management.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The definitions of marketing management and why it is called demand management; the eight demand states and the marketing task that matches each; the marketing management process (analysis, planning, implementation, control); the marketing plan, marketing control and the marketing audit; appraising the marketing effort; the importance of marketing management."}],"lessons":[{"number":"2.1","title":"Meaning of marketing management","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing management (Kotler and Keller):","bold":true},{"text":" the art and science of choosing target markets and "},{"text":"getting, keeping and growing customers","bold":true},{"text":" through creating, delivering and communicating superior customer value."}]},{"text":[{"text":"Marketing management (Kotler and Armstrong):","bold":true},{"text":" the art and science of choosing target markets and "},{"text":"building profitable relationships","bold":true},{"text":" with them."}]},{"text":[{"text":"Process definition:","bold":true},{"text":" the process of planning and executing the conception, pricing, promotion and distribution of ideas, goods and services "},{"text":"to create exchanges that satisfy individual and organisational objectives","bold":true},{"text":". Note the four elements inside it: conception (product), pricing (price), promotion (promotion), distribution (place)."}]},{"text":[{"text":"Demand management:","bold":true},{"text":" marketing management is described as demand management because the marketing manager's task is to "},{"text":"influence the level, timing and composition of demand","bold":true},{"text":" so that the firm meets its objectives. It is not only about pushing demand up."}]},{"text":[{"text":"Two basic questions","bold":true},{"text":" every marketing manager must answer:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"\"What customers will we serve?\" The answer is the "},{"text":"target market","bold":true},{"text":"."}]},{"text":[{"text":"\"How can we serve these customers best?\" The answer is the "},{"text":"value proposition","bold":true},{"text":": the set of benefits or values the firm promises to deliver to satisfy customer needs."}]}]}]},{"text":[{"text":"Art and science:","bold":true},{"text":" it uses systematic research and analysis (science) as well as creativity and judgement (art)."}]},{"text":[{"text":"Scope:","bold":true},{"text":" relevant to "},{"text":"both profit-seeking businesses and non-profit organisations","bold":true},{"text":", to goods and services, small and large firms, local and export markets."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Read the definitions carefully in the exam. If a gap follows \"choosing target markets and ____ through creating, delivering and communicating superior customer value\", the answer is \"getting, keeping and growing customers\". If the stem says \"choosing target markets and building ____ with them\", the answer is \"profitable relationships\"."}]},{"text":[{"text":"In the process definition, the purpose is "},{"text":"to create exchanges that satisfy individual and organisational objectives","bold":true},{"text":". It is not about reducing government control, hiring more staff or manufacturing at the lowest cost."}]},{"text":[{"text":"Trap on demand management: \"always push demand up to the highest possible level\" is wrong. Sometimes the manager must reduce demand (demarketing) or shift it in time (synchromarketing). \"Leave demand to market forces\" and \"fix national prices\" are also wrong."}]},{"text":[{"text":"Example: MTN deciding to serve students (target market) with cheap night data bundles and fast campus coverage (value proposition) has answered both questions."}]},{"text":[{"text":"Non-profit use: NAFDAC campaigns against fake drugs, a church growing its membership or a state immunisation drive a$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 6, $study_guide$ll use marketing management."}]}]}]},{"number":"2.2","title":"Demand states and the types of marketing management","mustKnow":[{"type":"paragraph","text":[{"text":"A firm can face any of "},{"text":"eight demand states","bold":true},{"text":". Each has its own marketing task, and the task gives its name to a "},{"text":"type of marketing management","bold":true},{"text":"."}]},{"type":"table","header":[[{"text":"Demand state"}],[{"text":"What it means"}],[{"text":"Marketing task (type)"}]],"rows":[[[{"text":"1. Negative demand"}],[{"text":"A large part of the market dislikes the product and may even pay to avoid it"}],[{"text":"Conversional marketing","bold":true},{"text":": find out why people dislike it and change their attitude"}]],[[{"text":"2. No demand"}],[{"text":"Target consumers are unaware of, or uninterested in, the product"}],[{"text":"Stimulational marketing","bold":true},{"text":": create awareness and interest; link the product to a need"}]],[[{"text":"3. Latent demand"}],[{"text":"Many consumers share a strong need that no existing product satisfies"}],[{"text":"Developmental marketing","bold":true},{"text":": measure the potential market and develop products that satisfy the unmet need"}]],[[{"text":"4. Falling (faltering, declining) demand"}],[{"text":"Demand for a product is dropping"}],[{"text":"Remarketing","bold":true},{"text":": revive demand by re-targeting, changing the product or the communication"}]],[[{"text":"5. Irregular demand"}],[{"text":"Demand varies by season, day or even hour, causing idle or overworked capacity"}],[{"text":"Synchromarketing","bold":true},{"text":": match the timing of demand to supply through flexible pricing, promotion and incentives"}]],[[{"text":"6. Full demand"}],[{"text":"The firm is satisfied with its current volume of business"}],[{"text":"Maintenance marketing","bold":true},{"text":": keep demand at that level despite changing preferences and rising competition"}]],[[{"text":"7. Overfull demand"}],[{"text":"Demand is higher than the firm can or wants to handle"}],[{"text":"Demarketing","bold":true},{"text":": reduce demand temporarily or permanently, e.g. raise prices, cut promotion and service"}]],[[{"text":"8. Unwholesome demand"}],[{"text":"Demand for products considered harmful (hard drugs, cigarettes, illegal guns)"}],[{"text":"Countermarketing","bold":true},{"text":": try to destroy the demand entirely"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Demarketing vs countermarketing:","bold":true},{"text":" demarketing "},{"text":"reduces","bold":true},{"text":" demand for an "},{"text":"acceptable","bold":true},{"text":" product; countermarketing tries to "},{"text":"destroy","bold":true},{"text":" demand for a "},{"text":"harmful","bold":true},{"text":" product."}]},{"text":[{"text":"Not demand states:","bold":true},{"text":" elastic, inelastic, derived, joint demand. These are economics or business-buying terms, not the eight demand states."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory chain (state, then task): Negative, Convert; No demand, Stimulate; Latent, Develop; Falling, Remarket; Irregular, Synchronise; Full, Maintain; Overfull, Demarket; Unwholesome, Counter."}]},{"text":[{"text":"Negative demand / conversional:","bold":true},{"text":" parents in a rural community avoid free immunisation because they fear side effects. The task is to learn the reason (fear) and change the attitude, e.g. through trusted community and religious leaders."}]},{"text":[{"text":"No demand / stimulational:","bold":true},{"text":" farmers who have never heard of a solar-powered irrigation pump show no interest. The task is to create awareness: demonstrations, free trials, extension workers."}]},{"text":[{"text":"Latent demand / developmental:","bold":true},{"text":" Lagos commuters want a fast, safe, affordable way to beat traffic that no service satisfies. The firm that measures this need and builds a fitting service (as the Lagos rail lines and ride-hailing firms tried) is doing developmental marketing."}]},{"text":[{"text":"Falling demand / remarketing:","bold":true},{"text":" a once-popular malt drink sees sales fall for three years; the company changes the packaging, adds a new flavour and targets new age groups. That is remarketing."}]},{"text":[{"text":"Irregular demand / synchromarketing:","bold":true},{"text":" a Lekki cinema is packed on Friday and Saturday nights but empty on weekday afternoons, so it sells half-price weekday tickets. Calabar hotels are full in December (carnival season) but empty the rest of the year: that state is "},{"text":"irregular demand","bold":true},{"text":", not overfull or latent."}]},{"text":[{"text":"Full demand / maintenance:","bold":true},{"text":" a market leader such as Indomie keeps quality steady, keeps distribution wide and keeps advertising to hold its position."}]},{"text":[{"text":"Overfull demand / demarketing:","bold":true},{"text":" in a severe dry season a state water corporation asks residents to cut water use and charges more for very high use. The product (water) is good; the firm simply cannot meet all the demand."}]},{"text":[{"text":"Unwholesome demand / countermarketing:","bold":true},{"text":" a national agency (for example the NDLEA) runs school campaigns on the dangers of hard drugs to stop young people wanting them at all."}]},{"text":[{"text":"Trap: in a \"NOT correctly matched\" question, look for a swap such as \"Irregular demand: remarketing\". Irregular goes with synchromarketing; remarketing goes with falling demand."}]},{"text":[{"text":"Trap: conversional marketing is about "},{"text":"changing a negative attitude","bold":true},{"text":", while stimulational marketing is about "},{"text":"creating awareness among people who have never heard of the product","bold":true},{"text":". Reviving falling sales is remarketing; shifting demand between busy and quiet periods is synchromarketing."}]}]}]},{"number":"2.3$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 7, $study_guide$","title":"The marketing management process: analysis and planning","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The marketing management process (4 stages, in order):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Marketing analysis","bold":true}]},{"text":[{"text":"Marketing planning","bold":true}]},{"text":[{"text":"Marketing implementation","bold":true}]},{"text":[{"text":"Marketing control","bold":true}]}]}]},{"text":[{"text":"The same process is also written as: (1) analysing marketing opportunities, (2) selecting (researching and choosing) target markets, (3) developing the marketing mix (designing strategy and the 4Ps programme), (4) managing the marketing effort, which itself means "},{"text":"planning, implementation and control","bold":true},{"text":". Both versions start with analysis and end with control."}]},{"text":[{"text":"Marketing analysis:","bold":true},{"text":" the "},{"text":"first","bold":true},{"text":" stage; a complete study of the company's situation: customers, competitors, the economy and the wider environment, and the firm's own strengths and weaknesses."}]},{"text":[{"text":"SWOT analysis:","bold":true},{"text":" the main tool of marketing analysis."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Strengths and weaknesses:","bold":true},{"text":" "},{"text":"internal","bold":true},{"text":" capabilities and limitations within the firm."}]},{"text":[{"text":"Opportunities and threats:","bold":true},{"text":" "},{"text":"external","bold":true},{"text":" factors the firm may exploit (opportunities) or must guard against (threats)."}]}]}]},{"text":[{"text":"Marketing planning:","bold":true},{"text":" the process by which "},{"text":"marketing plans are developed for products","bold":true},{"text":" (brands, product lines). It decides marketing objectives and strategies and prepares the marketing plan."}]},{"text":[{"text":"Sections of a marketing plan (8):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Executive summary"}]},{"text":[{"text":"Current marketing situation"}]},{"text":[{"text":"Threats and opportunities analysis (with strengths and weaknesses)"}]},{"text":[{"text":"Objectives and issues"}]},{"text":[{"text":"Marketing strategy"}]},{"text":[{"text":"Action programmes"}]},{"text":[{"text":"Budgets"}]},{"text":[{"text":"Controls"}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Do not confuse the levels of planning. "},{"text":"Strategic planning","bold":true},{"text":" is company-wide and long-term: it sets the mission, objectives and business portfolio of the whole firm. "},{"text":"Marketing planning","bold":true},{"text":" works inside it and produces plans for each product, brand or market. Short-term and medium-term planning describe time spans, not the process of producing product plans."}]},{"text":[{"text":"SWOT example: a Surulere bakery hears that a well-funded rival will soon open nearby selling cheaper bread. That rival is outside the bakery, so it is a "},{"text":"threat","bold":true},{"text":". The bakery's loyal customers would be a strength; its old oven a weakness; a new estate opening next door an opportunity."}]},{"text":[{"text":"Analysis example: before next year's plan, a telecom firm studies its customers, competitors and the economy and lists its strengths and weaknesses. That is "},{"text":"marketing analysis","bold":true},{"text":", the first stage."}]},{"text":[{"text":"Planning example: a drinks company decides it will launch a new juice in Abuja, aiming for 10% market share, positioned as a healthy school-lunch drink. Deciding the objective and strategy is planning."}]},{"text":[{"text":"A marketing plan never contains things like each employee's personal tax records; that is not a marketing matter."}]}]}]},{"number":"2.4","title":"Implementation, control and the marketing audit","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing implementation:","bold":true},{"text":" the process that "},{"text":"turns marketing strategies and plans into marketing actions","bold":true},{"text":" in order to accomplish marketing objectives."}]},{"text":[{"text":"Planning vs implementation:","bold":true},{"text":" planning addresses the "},{"text":"what","bold":true},{"text":" and "},{"text":"why","bold":true},{"text":" of marketing activities; implementation addresses the "},{"text":"who, where, when and how","bold":true},{"text":"."}]},{"text":[{"text":"A brilliant marketing strategy counts for little if the company fails to implement it properly. Results do not follow automatically from a written plan."}]},{"text":[{"text":"Marketing control:","bold":true},{"text":" measuring and evaluating the results of marketing strategies and plans and "},{"text":"taking corrective action","bold":true},{"text":" to ensure that objectives are achieved."}]},{"text":[{"text":"The control process (4 steps, in order):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Set goals","bold":true},{"text":" (what the firm wants to achieve)"}]},{"text":[{"text":"Measure performance","bold":true},{"text":" in the market"}]},{"text":[{"text":"Evaluate the causes","bold":true},{"text":" of any gap between expected and actual performance"}]},{"text":[{"text":"Take corrective action","bold":true},{"text":" to close the gap (this may mean changing the action programmes or even the goals)"}]}]}]},{"text":[{"text":"Operating control:","bold":true},{"text":" checks ongoing performance "},{"text":"against the annual plan","bold":true},{"text":" and takes corrective action when needed (sales, market share, costs)."}]},{"text":[{"text":"Strategic control:","bold":true},{"text":" checks whether the company's "},{"text":"basic strategies still fit its opportunities","bold":true},{"text":" in a changing environment."}]},{"text":[{"text":"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 8, $study_guide$Four types of marketing control:","bold":true},{"text":" annual-plan control, profitability control, efficiency control, strategic control."}]},{"text":[{"text":"Marketing audit:","bold":true},{"text":" a "},{"text":"comprehensive, systematic, independent and periodic","bold":true},{"text":" examination of a company's environment, objectives, strategies and activities to determine problem areas and opportunities and to recommend a plan of action. It is the main tool of strategic control."}]},{"text":[{"text":"Formula (control variance):","bold":true},{"text":" Variance = Target - Actual; Variance % = (Target - Actual) / Target x 100; Achievement % = Actual / Target x 100."}]}]},{"type":"paragraph","text":[{"text":"Appraising the marketing effort","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing effort:","bold":true},{"text":" the total resources a firm commits to its marketing mix to stimulate demand for its product. Appraisal checks how well the marketing mix was implemented."}]},{"text":[{"text":"2 ways to appraise:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Subjective evaluation:","bold":true},{"text":" based on rules of thumb and experience, not a set standard; inaccurate and biased, so not advisable."}]},{"text":[{"text":"Objective evaluation:","bold":true},{"text":" uses the scientific (systematic) approach, grouped into 3 processes: problem identification, modelling (representing a real-life situation), implementation."}]}]}]},{"text":[{"text":"6 steps in objective appraisal:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Set the standard"}]},{"text":[{"text":"Collect information on performance in each marketing-mix area"}]},{"text":[{"text":"Collate the performance information"}]},{"text":[{"text":"Analyse the collated information"}]},{"text":[{"text":"Compare the results with the standard"}]},{"text":[{"text":"Take corrective action if needed"}]}]}]},{"text":[{"text":"Effective objective appraisal needs an efficient "},{"text":"marketing information system","bold":true},{"text":" giving authentic, adequate and timely feedback from all marketing-mix components."}]},{"text":[{"text":"2 appraisal strategies:","bold":true},{"text":" periodic marketing effort appraisal ("},{"text":"PMEA","bold":true},{"text":") and continuous marketing effort appraisal ("},{"text":"CMEA","bold":true},{"text":")."}]},{"text":[{"text":"2 difficulties in appraisal:","bold":true},{"text":" it is hard to isolate and measure the impact of environmental forces; it is hard to measure intangible aspects such as consumer satisfaction, attitude and brand image."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Implementation example: a drinks company has approved its plan to launch a juice in Abuja. The team now assigns staff, books the launch venue, schedules radio adverts and arranges delivery to retailers. That is "},{"text":"implementation","bold":true},{"text":" (who, where, when, how)."}]},{"text":[{"text":"Control example: halfway through the year, a paint company's sales manager finds northern sales well below target (measure), discovers the cause is weak distributor support (evaluate), and adds distributor incentives (correct). That is "},{"text":"control","bold":true},{"text":"."}]},{"text":[{"text":"Worked computation: a paint company's northern target for the half-year is ₦60,000,000; actual sales are ₦51,000,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Variance = ₦60,000,000 - ₦51,000,000 = ₦9,000,000 shortfall."}]},{"text":[{"text":"Variance % = 9,000,000 / 60,000,000 x 100 = 15%."}]},{"text":[{"text":"Achievement % = 51,000,000 / 60,000,000 x 100 = 85%."}]},{"text":[{"text":"The manager now finds the cause of the 15% gap and corrects it."}]}]}]},{"text":[{"text":"Trap: the order of control is goals, measure, evaluate, correct. Any option starting with \"measure\" or \"take corrective action\" is wrong."}]},{"text":[{"text":"Trap: operating control is about this year's plan; strategic control is about whether the whole strategy still fits. A marketing audit is not a SWOT analysis (SWOT is one part of analysis), not a sales forecast and not the marketing plan itself."}]},{"text":[{"text":"Objective appraisal steps mirror the control steps: standard first, corrective action last."}]}]}]},{"number":"2.5","title":"Importance of marketing management","mustKnow":[{"type":"paragraph","text":[{"text":"To the organisation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Coordinates product, price, promotion and distribution decisions towards the firm's objectives."}]},{"text":[{"text":"Helps the firm match its offerings to market demand."}]},{"text":[{"text":"Guides decisions on target markets and the marketing mix."}]},{"text":[{"text":"Helps the firm identify and respond to changes in customer needs and the environment."}]},{"text":[{"text":"Generates revenue and profit and supports growth and survival."}]},{"text":[{"text":"Builds customer satisfaction, loyalty and long-term relationships."}]},{"text":[{"text":"Provides information for planning and decision-making."}]},{"text":[{"text":"Helps the firm meet competition."}]}]},{"type":"paragraph","text":[{"text":"To society and the economy:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Helps direct scarce resources towards the goods and services people want."}]},{"text":[{"text":"Raises the standard of living by making a wide variety of products available."}]},{"text":[{"text":"Creates employment in selling, advertising, distribution and research."}]},{"text":[{"text":"Supports economic growth by matching production with consumption."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing management does "},{"text":"not","bold":true},{"text":" guarantee that a firm will neve$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 9, $study_guide$r make a loss, that rivals will leave the market or that all firms will charge the same price. It does not remove the need for finance or production departments, nor for consumer protection laws such as the Federal Competition and Consumer Protection Act 2018 enforced by the FCCPC."}]},{"text":[{"text":"It does not reduce product variety or let a firm ignore customer needs; those options describe the opposite of good marketing management."}]},{"text":[{"text":"Example: Dangote Cement uses research on housing demand to plan where to build plants and depots, so resources flow to where cement is needed. That is resource direction (a benefit to society) and matching supply to demand (a benefit to the firm)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing management: the art and science of choosing target markets and getting, keeping and growing customers through superior customer value."}]},{"text":[{"text":"It is demand management: influencing the level, timing and composition of demand."}]},{"text":[{"text":"Two questions: whom to serve (target market) and how best to serve them (value proposition)."}]},{"text":[{"text":"Eight states and tasks: negative-conversional, no-stimulational, latent-developmental, falling-remarketing, irregular-synchromarketing, full-maintenance, overfull-demarketing, unwholesome-countermarketing."}]},{"text":[{"text":"Demarketing reduces demand for a good product; countermarketing destroys demand for a harmful one."}]},{"text":[{"text":"Process: analysis, planning, implementation, control."}]},{"text":[{"text":"SWOT: strengths and weaknesses internal; opportunities and threats external."}]},{"text":[{"text":"Planning is what and why; implementation is who, where, when and how."}]},{"text":[{"text":"Control: set goals, measure, evaluate causes, correct. Marketing audit: comprehensive, systematic, independent, periodic."}]},{"text":[{"text":"Marketing management serves profit and non-profit organisations alike."}]}]}],"theory":{"itemId":"66f699b8-e513-5bcb-ac28-6a033edfb3ae","question":[{"type":"paragraph","text":[{"text":"A Lagos ferry operator's target for the first quarter was ₦12,000,000 in fares, but actual fares were ₦9,600,000. Boats are full at rush hours but nearly empty at midday. (a) Compute the shortfall and the achievement rate. (b) Name the demand state and the matching marketing task, and say which stage of the marketing management process the computation belongs to."}]}]},"practice":[{"topic":"Marketing Management","named":false}]}},{"kind":"note","itemId":"786335a6-6560-586f-b91b-955c4f65ac61","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Marketing Concepts and Market Orientation","body":"What a marketing concept (philosophy) is; the five competing concepts in order (production, product, selling, marketing, societal) plus holistic/relationship marketing; each concept's core assumption, focus, strengths and dangers; the selling versus marketing contrast; and market orientation with its three behavioural components and two decision criteria.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"What a marketing concept (philosophy) is; the five competing concepts in order (production, product, selling, marketing, societal) plus holistic/relationship marketing; each concept's core assumption, focus, strengths and dangers; the selling versus marketing contrast; and market orientation with its three behavioural components and two decision criteria."}],"lessons":[{"number":"3.1","title":"Meaning of a marketing concept and the order of evolution","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing concept (broad sense) / marketing management philosophy:","bold":true},{"text":" the guiding idea about what should drive a firm's marketing activities, and how much weight to give the interests of the "},{"text":"organisation","bold":true},{"text":", "},{"text":"customers","bold":true},{"text":" and "},{"text":"society","bold":true},{"text":". It is a business philosophy and an attitude of mind that the whole organisation must adopt, not just the marketing department."}]},{"text":[{"text":"5 major competing concepts","bold":true},{"text":" of marketing activities in organisations:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Production concept"}]},{"text":[{"text":"Product concept"}]},{"text":[{"text":"Selling (sales) concept"}]},{"text":[{"text":"Marketing concept"}]},{"text":[{"text":"Societal marketing concept"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Newer thinking adds the "},{"text":"holistic marketing concept","bold":true},{"text":" (with relationship marketing inside it)."}]},{"text":[{"text":"Order of development:","bold":true},{"text":" production → selling → marketing → societal marketing. (The product concept is usually left out of this four-step sequence.)"}]},{"text":[{"text":"Direction of the shift:","bold":true},{"text":" from product-centric efficiency towards "},{"text":"customer-centric value creation","bold":true},{"text":", with an increasing emphasis on customer "},{"text":"and","bold":true},{"text":" societal needs."}]}]},{"type":"table","header":[[{"text":"Concept"}],[{"text":"Consumers will favour..."}],[{"text":"So the firm should..."}]],"rows":[[[{"text":"Production"}],[{"text":"products widely available and low in price"}],[{"text":"improve production and distribution efficiency"}]],[[{"text":"Product"}],[{"text":"products of the highest quality, performance, features"}],[{"text":"keep improving the product"}]],[[{"text":"Selling"}],[{"text":"not buy enough unless persuaded"}],[{"text":"sell and promote aggressively"}]],[[{"text":"Marketing"}],[{"text":"products that meet their needs better than rivals'"}],[{"text":"find needs, then satisfy them"}]],[[{"text":"Societal marketing"}],[{"text":"the above, done in a way that protects long-run welfare"}],[{"text":"balance profit, wants and society's intere$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 10, $study_guide$sts"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Inside-out:","bold":true},{"text":" starts from the factory and the firm's existing products (production, product, selling)."}]},{"text":[{"text":"Outside-in:","bold":true},{"text":" starts from the market and customer needs, then coordinates the firm to satisfy them (marketing, societal)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"You will also meet the older split between the "},{"text":"traditional concept","bold":true},{"text":" of marketing (narrow, product oriented: the physical transfer of goods for money) and the "},{"text":"modern concept","bold":true},{"text":" (broad, customer oriented: earning profit through customer satisfaction). The traditional view lines up with the production, product and selling concepts; the modern view with the marketing and societal concepts."}]},{"text":[{"text":"Never put the marketing concept before the selling concept: firms turned to customer needs only after aggressive selling stopped working. Later concepts did not wipe out earlier ones; many Nigerian firms still think in production or selling terms today."}]}]}]},{"number":"3.2","title":"The production and product concepts","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Production concept:","bold":true},{"text":" consumers will buy (favour) products that are "},{"text":"widely available","bold":true},{"text":" and "},{"text":"low in price","bold":true},{"text":". Management should concentrate on "},{"text":"high production efficiency","bold":true},{"text":" and "},{"text":"widespread distribution","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"earliest","bold":true},{"text":" philosophy; it describes business in the "},{"text":"late 1800s","bold":true},{"text":" and early industrial era."}]},{"text":[{"text":"Emerged in response to "},{"text":"industrial advancements enabling mass production","bold":true},{"text":", when "},{"text":"demand for goods was greater than supply","bold":true},{"text":"."}]},{"text":[{"text":"Primary objective: "},{"text":"maximising output and distribution efficiency","bold":true},{"text":"; firms succeeded through "},{"text":"economies of scale and broad distribution","bold":true},{"text":"."}]},{"text":[{"text":"Still useful when (1) "},{"text":"demand exceeds supply","bold":true},{"text":", or (2) the product's "},{"text":"cost is too high","bold":true},{"text":" and must be brought down."}]},{"text":[{"text":"Its assumption is challenged when consumers "},{"text":"prioritise quality and differentiation over price","bold":true},{"text":"."}]},{"text":[{"text":"Main danger:","bold":true},{"text":" the firm becomes so focused on its own operations and efficiency that it "},{"text":"loses sight of satisfying customers' needs","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Product concept:","bold":true},{"text":" consumers will buy (favour) products of the "},{"text":"highest quality","bold":true},{"text":", most "},{"text":"performance","bold":true},{"text":" and most "},{"text":"innovative features","bold":true},{"text":". Management should make continuous product improvements."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Based on the "},{"text":"\"technology-push\"","bold":true},{"text":" model of innovation: products designed by engineers and scientists for consumers to use."}]},{"text":[{"text":"Trap: \"build a better mousetrap and customers will beat a path to your door\", while ignoring what customers actually want."}]},{"text":[{"text":"Leads to "},{"text":"marketing myopia","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Marketing myopia","bold":true},{"text":" (Theodore Levitt, 1960): an undue concentration on the "},{"text":"product","bold":true},{"text":" rather than on the "},{"text":"customer need or benefit","bold":true},{"text":" it provides."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Production example:","bold":true},{"text":" a Kano noodle maker facing demand far above supply adds production lines, cuts unit costs and spreads distribution so more homes can afford a ₦250 pack. That is the production concept. Dangote Cement pushing scale and low cost per bag uses the same logic."}]},{"text":[{"text":"Hyundai (cars) and Goldstar, Sharp and Sanyo (electronics) succeeded with low-cost production abroad. So the production concept \"has a place\" today, but focusing on production while ignoring customers is as faulty as focusing on customers while ignoring production efficiency."}]},{"text":[{"text":"Product example:","bold":true},{"text":" a Lagos electronics firm keeps adding ports, a torch and a radio to its power bank because managers believe buyers always choose the most advanced model, but never asks what buyers need. That is the product concept. The slogan \"good thinking, good product\" in a car advertisement in Nigeria reflected the same product orientation."}]},{"text":[{"text":"Myopia examples:","bold":true},{"text":" railway managers thought users wanted "},{"text":"trains","bold":true},{"text":" rather than "},{"text":"transportation","bold":true},{"text":" and missed the threat from airlines, buses, trucks and cars. Slide-rule makers thought engineers wanted slide rules rather than "},{"text":"calculating capacity","bold":true},{"text":" and lost to pocket calculators. Such firms are \"looking into a mirror when they should be looking out of the window\"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"widely available and low in price\" = production; \"highest quality\" = product. Options often swap these two."}]}]}]},{"number":"3.3","title":"The selling concept and the marketing concept","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Selling (sales) concept:","bold":true},{"text":" consumers will not buy enough of the firm's products unless it undertakes a$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 11, $study_guide$ "},{"text":"large-scale selling and promotion effort","bold":true},{"text":". Put another way: the firm "},{"text":"produces what it wants","bold":true},{"text":" and then makes great efforts to "},{"text":"convince consumers","bold":true},{"text":" to buy."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Became dominant mainly because of "},{"text":"overproduction","bold":true},{"text":" and the need to "},{"text":"clear inventory","bold":true},{"text":"; it thrives where consumers need convincing because of "},{"text":"surplus goods","bold":true},{"text":" (supply exceeds demand)."}]},{"text":[{"text":"Gained traction when firms needed to "},{"text":"overcome consumer resistance through persuasion","bold":true},{"text":"."}]},{"text":[{"text":"Goes hand in hand with "},{"text":"high-pressure selling","bold":true},{"text":"; the "},{"text":"\"sales-push\"","bold":true},{"text":" model, pushing unwanted products through the channel."}]},{"text":[{"text":"Typically practised with "},{"text":"unsought goods","bold":true},{"text":" (goods buyers do not normally think of buying, such as insurance or burial plots)."}]},{"text":[{"text":"Risky assumption:","bold":true},{"text":" customers coaxed into buying will like the product, or if not, will forget their disappointment and buy again."}]},{"text":[{"text":"Major limitation:","bold":true},{"text":" focuses on "},{"text":"short-term sales","bold":true},{"text":" over long-term customer loyalty; aims at making the sale, not building relationships."}]}]}]},{"text":[{"text":"Marketing concept:","bold":true},{"text":" achieving organisational goals depends on "},{"text":"knowing the needs and wants of target markets","bold":true},{"text":" and "},{"text":"delivering the desired satisfactions better than competitors","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Basic form: the identification and satisfaction of customers' needs and wants. "},{"text":"Broadened form:","bold":true},{"text":" doing so "},{"text":"more effectively and efficiently than competitors","bold":true},{"text":"."}]},{"text":[{"text":"Origin: Drucker (1954), McKitterick (1958) and Levitt (1960); all agree the purpose of business is to "},{"text":"create a satisfied customer","bold":true},{"text":"."}]},{"text":[{"text":"Emerged as a response to "},{"text":"heightened competition and evolving consumer expectations","bold":true},{"text":"."}]},{"text":[{"text":"Hinges on "},{"text":"aligning offerings with customer needs and desires","bold":true},{"text":"; success = "},{"text":"delivering what customers value, profitably","bold":true},{"text":"; customer satisfaction drives profitability."}]},{"text":[{"text":"Slogans: "},{"text":"\"sense and respond\"","bold":true},{"text":", not \"make and sell\"; find the "},{"text":"right products for your customers","bold":true},{"text":", not the right customers for your products."}]},{"text":[{"text":"4 pillars:","bold":true},{"text":" (1) target market, (2) customer needs, (3) integrated marketing, (4) profitability."}]},{"text":[{"text":"Integrated marketing:","bold":true},{"text":" all the firm's departments and marketing activities work together to serve the customer's interests."}]}]}]}]},{"type":"table","header":[[],[{"text":"Starting point"}],[{"text":"Focus"}],[{"text":"Means"}],[{"text":"Ends"}]],"rows":[[[{"text":"Selling concept"}],[{"text":"Factory"}],[{"text":"Existing products"}],[{"text":"Selling and promoting"}],[{"text":"Profits through sales volume"}]],[[{"text":"Marketing concept"}],[{"text":"Market"}],[{"text":"Customer needs"}],[{"text":"Integrated marketing"}],[{"text":"Profits through customer satisfaction"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Levitt's contrast:","bold":true},{"text":" \"Selling focuses on the needs of the "},{"text":"seller","bold":true},{"text":"; marketing on the needs of the "},{"text":"buyer","bold":true},{"text":".\" Selling is preoccupied with converting the product into cash; marketing with satisfying the customer through the product and everything associated with creating, delivering and consuming it."}]},{"text":[{"text":"Bell and Emory's 3 elements of the marketing concept:","bold":true},{"text":" (1) "},{"text":"customer orientation","bold":true},{"text":", (2) "},{"text":"integrated effort","bold":true},{"text":", (3) "},{"text":"profit direction","bold":true},{"text":" (profit, not sales volume)."}]},{"text":[{"text":"Barksdale and Darden's 2 notions:","bold":true},{"text":" (1) the consumer is the focal point of all business activity; (2) "},{"text":"profit, rather than sales volume","bold":true},{"text":", is the criterion for evaluating marketing activities."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Selling example:","bold":true},{"text":" an Abuja insurer recruits a big team of agents to pitch people in markets and offices because few people seek out life insurance. Selling concept. As a long-term strategy it is weak: it may help meet short-term sales targets or survive hard times, but it fails against rivals who serve customers with products they really want."}]},{"text":[{"text":"Marketing example:","bold":true},{"text":" a restaurant near the University of Ibadan surveys students, learns they want affordable, healthy meals delivered fast, and designs its menu, prices and delivery around that, aiming to profit from repeat customers. Marketing concept."}]},{"text":[{"text":"Customer-driven vs customer-driving marketing:","bold":true},{"text":" customer-driven marketing finds out what customers want now and serves it. "},{"text":"Customer-driving marketing","bold":true},{"text":" studies customers so closely that it anticipates "},{"text":"latent needs","bold":true},{"text":" they have not yet expressed and creates products before they ask (think of how mobile money apps such as OPay and Moniepoint met needs many traders had never voiced)."}]},{"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 12, $study_guide$text":[{"text":"Customer orientation does not rule out stimulating needs or using aggressive selling for goods created for customers."}]},{"text":[{"text":"Criticisms of the marketing concept:","bold":true},{"text":" it shifted attention from long-term product development and quality to short-term advertising, selling and promotion; implementing it has caused organisational stress, excessive costs and high product-failure rates; and relations between business, the public and government deteriorated ("},{"text":"consumerism","bold":true},{"text":"). Most failures are blamed on "},{"text":"implementation","bold":true},{"text":", not on the concept itself. Today it is often called "},{"text":"customer-centricity","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the selling concept starts at the "},{"text":"factory","bold":true},{"text":", not the market; the marketing concept's means is "},{"text":"integrated marketing","bold":true},{"text":", not selling and promoting. \"Mass production\" is never one of the four pillars."}]}]}]},{"number":"3.4","title":"The societal and holistic marketing concepts","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Societal marketing concept:","bold":true},{"text":" the organisation's task is to determine the needs, wants and interests of customers and to satisfy them "},{"text":"more effectively and efficiently than competitors","bold":true},{"text":", in a way that "},{"text":"preserves or enhances the welfare of the consumer and society","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Evolved from "},{"text":"criticisms of the marketing concept","bold":true},{"text":", chiefly that it ignores "},{"text":"long-run societal welfare","bold":true},{"text":" and overlooks conflicts between consumers' "},{"text":"short-run wants","bold":true},{"text":" and "},{"text":"long-run welfare","bold":true},{"text":"."}]},{"text":[{"text":"Gained prominence through growing concern over "},{"text":"sustainability and ethics","bold":true},{"text":"."}]},{"text":[{"text":"It "},{"text":"integrates ethical considerations and societal welfare","bold":true},{"text":" into the marketing concept."}]},{"text":[{"text":"3 considerations to balance:","bold":true},{"text":" (1) "},{"text":"company profit","bold":true},{"text":", (2) "},{"text":"consumer satisfaction (wants)","bold":true},{"text":", (3) "},{"text":"interests of society (the public)","bold":true},{"text":". In the four-way version: consumers' wants, the company's requirements, consumers' long-run interests, society's long-run interests."}]},{"text":[{"text":"It does "},{"text":"not","bold":true},{"text":" ask the firm to give up profit."}]}]}]},{"text":[{"text":"Holistic marketing concept:","bold":true},{"text":" \"everything matters\" in marketing, so a broad, integrated perspective is needed in developing, designing and carrying out marketing programmes. "},{"text":"4 components:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Relationship marketing:","bold":true},{"text":" building mutually satisfying long-term relationships with customers, suppliers, distributors and other partners to earn and keep their business."}]},{"text":[{"text":"Integrated marketing:","bold":true},{"text":" all marketing activities and departments combined to create, communicate and deliver value."}]},{"text":[{"text":"Internal marketing:","bold":true},{"text":" hiring, training and motivating able employees who want to serve customers well."}]},{"text":[{"text":"Performance marketing","bold":true},{"text":" (earlier called "},{"text":"socially responsible marketing","bold":true},{"text":"): understanding the financial and non-financial returns to the business and society, including ethical, legal and environmental effects."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Societal example:","bold":true},{"text":" a Nigerian soft-drink maker cuts sugar, moves to recyclable bottles and funds clearing of drains blocked by plastic, while still aiming to satisfy customers and earn a profit. Societal marketing concept."}]},{"text":[{"text":"Short-run wants vs long-run welfare:","bold":true},{"text":" a Port Harcourt fast-food chain sells cheap, tasty fried meals customers love; a critic says it satisfies short-run wants but ignores long-run health (obesity). That critic reasons from the "},{"text":"societal","bold":true},{"text":" concept. The pure marketing concept would see no problem, because customers are satisfied."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"It requires the firm to give up profit for social welfare\" is "},{"text":"false","bold":true},{"text":"; societal marketing balances profit with welfare."}]},{"text":[{"text":"\"Production marketing\" and \"mass marketing\" are "},{"text":"not","bold":true},{"text":" components of holistic marketing."}]},{"text":[{"text":"Internal marketing: a GTBank or MTN service promise means nothing unless staff are trained and motivated to keep it."}]}]}]},{"number":"3.5","title":"Market orientation and its components","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market orientation:","bold":true},{"text":" the organisation-wide putting into practice of the marketing concept. The firm "},{"text":"continuously gathers information about customers and competitors","bold":true},{"text":" and "},{"text":"coordinates all departments","bold":true},{"text":" to create "},{"text":"superior customer value","bold":true},{"text":"."}]},{"text":[{"text":"Marketing concept vs market orientation:","bold":true},{"text":" the marketing concept is the "},{"text":"philosophy","bold":true},{"text":"; market orientation is the "},{"text":"set of behaviours that puts it into practice","bold":true},{"text":"."}]},{"text":[{"text":"3 behavioural components","bold":true},{"text":" (Narver and Slater):"}]}]},{"type":"list","orde$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 13, $study_guide$red":true,"start":1,"items":[{"text":[{"text":"Customer orientation:","bold":true},{"text":" understanding target buyers well enough to create superior value for them continuously."}]},{"text":[{"text":"Competitor orientation:","bold":true},{"text":" understanding the short-term strengths and weaknesses and long-term capabilities and strategies of "},{"text":"current and potential","bold":true},{"text":" competitors."}]},{"text":[{"text":"Inter-functional coordination:","bold":true},{"text":" the coordinated use of the company's resources "},{"text":"across all departments","bold":true},{"text":" to create superior value for target customers."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"2 decision criteria:","bold":true},{"text":" (1) "},{"text":"long-term focus","bold":true},{"text":", (2) "},{"text":"profitability","bold":true},{"text":"."}]},{"text":[{"text":"Information-processing view","bold":true},{"text":" (Kohli and Jaworski): market orientation is the organisation-wide (1) "},{"text":"generation","bold":true},{"text":" of market intelligence, (2) "},{"text":"dissemination","bold":true},{"text":" of that intelligence across departments, and (3) organisation-wide "},{"text":"responsiveness","bold":true},{"text":" to it."}]},{"text":[{"text":"Market-oriented definition of the business:","bold":true},{"text":" define the business by the customer need it serves, not by the product it makes."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Customer orientation:","bold":true},{"text":" a Lagos fintech holds monthly focus groups with Balogun Market traders, tracks every complaint and redesigns its app around what users need. Other signs: measuring satisfaction regularly, researching target customers' needs, following up after sales."}]},{"text":[{"text":"Competitor orientation:","bold":true},{"text":" a Nigerian paint firm's managers meet weekly to review rivals' price changes and launches, and to assess a foreign firm planning to enter. Studying a rival's "},{"text":"cost structure","bold":true},{"text":" is competitor orientation, so it is the activity "},{"text":"least","bold":true},{"text":" associated with customer orientation."}]},{"text":[{"text":"Inter-functional coordination:","bold":true},{"text":" at an Aba shoe company, production, finance, R&D and sales staff share customer feedback and jointly plan a new school-shoe range."}]},{"text":[{"text":"\"Production orientation\" and \"selling orientation\" are "},{"text":"not","bold":true},{"text":" components of market orientation."}]},{"text":[{"text":"Business definitions:","bold":true},{"text":" a bank that says it is in the business of \"helping Nigerians move and keep money safely and cheaply\" (not \"operating bank branches\") has a "},{"text":"market-oriented","bold":true},{"text":" definition. \"We run bank branches\" or \"we make trains\" is "},{"text":"product-oriented","bold":true},{"text":" and invites myopia."}]},{"text":[{"text":"Market orientation does "},{"text":"not","bold":true},{"text":" replace customers with competitors as the main focus; it watches both."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A marketing concept is the guiding philosophy that weighs the interests of the firm, customers and society."}]},{"text":[{"text":"Five concepts: production, product, selling, marketing, societal; order of evolution production → selling → marketing → societal."}]},{"text":[{"text":"Production = available and cheap; demand > supply; efficiency and distribution; danger is forgetting customers."}]},{"text":[{"text":"Product = highest quality and features; technology-push; leads to marketing myopia (product, not need)."}]},{"text":[{"text":"Selling = consumers must be persuaded; overproduction, unsought goods; factory, existing products, selling and promoting, profit through volume."}]},{"text":[{"text":"Marketing = market, customer needs, integrated marketing, profit through satisfaction; \"sense and respond\"; four pillars."}]},{"text":[{"text":"Societal = marketing concept plus consumer and society welfare; balance profit, wants and public interest; profit is not given up."}]},{"text":[{"text":"Holistic = relationship, integrated, internal and performance (socially responsible) marketing."}]},{"text":[{"text":"Market orientation puts the marketing concept into practice: customer orientation, competitor orientation, inter-functional coordination; long-term focus and profitability."}]}]}],"theory":{"itemId":"fb555ddc-45af-569f-a0c9-b63d7a28d44a","question":[{"type":"paragraph","text":[{"text":"Distinguish the selling concept from the marketing concept, and state the three behavioural components of market orientation."}]}]},"practice":[{"topic":"Marketing Concepts and Market Orientation","named":false}]}},{"kind":"note","itemId":"def16f0a-7f1d-5c21-8a02-43088dcc5f77","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Marketing Environment","body":"The meaning of the marketing environment and its five features; internal versus external, micro versus macro; every micro force (company, suppliers, intermediaries, customers, competitors, publics) with its sub-types; the six macro forces and their factors; PESTLE, SWOT and environmental scanning; why studying the environment matters; strategic windows and megamarketing.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"The meaning of the marketing environment and its five features; internal versus external, micro versus macro; every micro force (company, suppliers, intermediaries, customers, competitors, publics) with its sub-types; the six macro forces and their factors; PESTLE, SWOT and environmental scanning; why studying the environment matters; strategic windows and megamarketing."}],"lessons":[{"number":"4.1","title":"Meaning, types and features of the marketing environment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing environment:","bol$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 14, $study_guide$d":true},{"text":" all the internal and external factors that directly or indirectly influence an organisation's decisions on its marketing activities. Put more simply: the factors and forces that influence the marketing function of an organisation. It is the mix of forces that affect a firm's ability to build relationships with and serve its customers."}]},{"text":[{"text":"Internal environment:","bold":true},{"text":" the internal forces and factors that influence the marketing function. Internal factors are "},{"text":"within the organisation's control","bold":true},{"text":" (e.g. its own strengths, weaknesses and competencies)."}]},{"text":[{"text":"External environment:","bold":true},{"text":" the external forces and factors that influence the marketing function. External factors are "},{"text":"not within its control","bold":true},{"text":" (e.g. government, technology, economy, society, competitors)."}]},{"text":[{"text":"The environment is usually divided into "},{"text":"2 main types:","bold":true},{"text":" the "},{"text":"micro environment","bold":true},{"text":" and the "},{"text":"macro environment","bold":true},{"text":"."}]}]},{"type":"table","header":[[],[{"text":"Micro environment"}],[{"text":"Macro environment"}]],"rows":[[[{"text":"Other names"}],[{"text":"Task environment; immediate environment"}],[{"text":"Broad environment"}]],[[{"text":"Meaning"}],[{"text":"Forces closely linked to the firm that "},{"text":"directly","bold":true},{"text":" affect its activities"}],[{"text":"Larger societal forces, "},{"text":"beyond the firm's control","bold":true},{"text":", that affect it (and all actors in its immediate environment) to a significant extent and are subject to constant change"}]],[[{"text":"Members"}],[{"text":"Company, suppliers, marketing intermediaries, customers, competitors, publics"}],[{"text":"Demographic, economic, natural, technological, political-legal, socio-cultural"}]]]},{"type":"paragraph","text":[{"text":"5 features of the marketing environment:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Specific and general forces:","bold":true},{"text":" specific forces "},{"text":"directly","bold":true},{"text":" affect the organisation (e.g. customers, investors); general forces affect it "},{"text":"indirectly","bold":true},{"text":" (e.g. social, political, legal, technological factors)."}]},{"text":[{"text":"Complexity:","bold":true},{"text":" the environment contains many factors, conditions and influences, and their "},{"text":"interaction","bold":true},{"text":" makes it complex."}]},{"text":[{"text":"Vibrancy:","bold":true},{"text":" the environment is "},{"text":"dynamic","bold":true},{"text":"; it does not stay stable but "},{"text":"changes over time","bold":true},{"text":". Marketers can control some forces but never all."}]},{"text":[{"text":"Uncertainty:","bold":true},{"text":" market forces are "},{"text":"unpredictable","bold":true},{"text":"; some changes are hard to predict (e.g. tastes in clothes)."}]},{"text":[{"text":"Relativity:","bold":true},{"text":" explains why "},{"text":"demand differs","bold":true},{"text":" from country to country, region to region or culture to culture."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Stability\" is "},{"text":"not","bold":true},{"text":" a feature; the environment is the opposite of stable. That is exactly why it demands "},{"text":"constant monitoring","bold":true},{"text":": so the firm can adapt to unpredictable shifts in external and internal conditions, rather than keep static strategies."}]},{"text":[{"text":"Uncertainty","bold":true},{"text":" example: a Lagos fashion house sells out an ankara style one month and cannot move it the next. A fashion may last a few days or a few years."}]},{"text":[{"text":"Relativity","bold":true},{"text":" example: aso-oke caps are always in demand in south-west Nigeria because they are traditional dress, yet demand abroad may be almost zero."}]},{"text":[{"text":"Vibrancy","bold":true},{"text":" sounds like \"lively\"; in the exam it means "},{"text":"dynamic, always changing","bold":true},{"text":". Do not confuse it with complexity (many interacting factors)."}]},{"text":[{"text":"A complete environmental analysis must cover "},{"text":"both micro","bold":true},{"text":" (e.g. suppliers) "},{"text":"and macro","bold":true},{"text":" (e.g. economic trends) forces, not customers or competitors alone."}]},{"text":[{"text":"Marketers monitor the environment to predict changes, because changes create "},{"text":"threats and opportunities","bold":true},{"text":", and plans are modified to match."}]}]}]},{"number":"4.2","title":"The internal environment and the supply side of the micro environment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internal environment (the company):","bold":true},{"text":" the firm's own departments (top management, finance, research and development (R&D), purchasing, operations/production, personnel/HR, accounting) whose relationships affect marketing decisions. Marketing plans need "},{"text":"top management approval","bold":true},{"text":" before they are implemented."}]},{"text":[{"text":"4 organic business functions:","bold":true},{"text":" marketing, personnel, production, finance."}]},{"text":[{"text":"Five Ms","bold":true},{"text":" of the internal environment: "},{"text":"Men, Money, Machinery, Materials, Markets.","bold":true},{"text":" Internal forces are "},{"text":"controllable","bold":true},{"text":" and can be adjusted to external change."}]},{"text":[{"text":"The micro environment has a "},{"text":"supply side","bold":true},{"text":" (suppliers, marketing intermediaries, competitors) and a "},{"text":"demand side","bold":true},{"text":" (customers)."}]},{"text":[{"text":"Suppliers:","bold":true},{"text":" other firms and individuals that provide the resources (raw materials and other inputs) a company needs to produce its$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 15, $study_guide$ goods and services."}]},{"text":[{"text":"Make-or-buy decision:","bold":true},{"text":" the purchasing department's decision on which resources to make itself and which to buy from outside. "},{"text":"3 options:","bold":true},{"text":" (i) make everything and assemble or process it; (ii) buy everything and confine the firm to assembly; (iii) make the complicated parts and buy the less complicated ones."}]},{"text":[{"text":"Marketing intermediaries:","bold":true},{"text":" independent businesses that perform the activities needed to move products from manufacturers to ultimate consumers; they link the firm with customers by "},{"text":"promoting, selling and distributing","bold":true},{"text":" its products. They include wholesalers, retailers, agents and distributors."}]}]},{"type":"paragraph","text":[{"text":"4 types of marketing intermediaries:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Resellers:","bold":true},{"text":" buy from the firm and sell to customers (wholesalers, retailers)."}]},{"text":[{"text":"Distribution centres:","bold":true},{"text":" store goods (e.g. a warehouse)."}]},{"text":[{"text":"Marketing agencies:","bold":true},{"text":" promote the products by making customers aware of their benefits (e.g. an advertising agency)."}]},{"text":[{"text":"Financial intermediaries:","bold":true},{"text":" finance or insure business transactions (banks, credit organisations, insurance companies)."}]}]},{"type":"paragraph","text":[{"text":"5 utilities created by intermediaries (middlemen):","bold":true}]},{"type":"table","header":[[{"text":"Utility"}],[{"text":"How it is created"}]],"rows":[[[{"text":"Place"}],[{"text":"Stocking","bold":true},{"text":" products where customers are located"}]],[[{"text":"Time"}],[{"text":"Opening "},{"text":"long hours","bold":true},{"text":" so customers buy at their convenience"}]],[[{"text":"Quantity"}],[{"text":"Making products available in "},{"text":"quantities customers can afford","bold":true}]],[[{"text":"Assortment"}],[{"text":"Gathering different products at one point","bold":true},{"text":" so customers buy them on one shopping trip"}]],[[{"text":"Possession"}],[{"text":"Transferring","bold":true},{"text":" products to customers through successful transactions"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Suppliers affect "},{"text":"profit","bold":true},{"text":", because the price of raw materials determines the final price. Firms monitor suppliers regularly for "},{"text":"supply shortages","bold":true},{"text":" and "},{"text":"input price changes","bold":true},{"text":", and check reliability, delivery, stock availability, credit facilities and servicing."}]},{"text":[{"text":"Worked example (supplier force):","bold":true},{"text":" a Lagos bakery pays ₦60,000 for a bag of flour. Its miller raises the price by 30%. Increase = 30% × ₦60,000 = ₦18,000. New price = ₦60,000 + ₦18,000 = ₦78,000 a bag. The bakery raises the price of its bread. The force at work is the "},{"text":"supplier","bold":true},{"text":"."}]},{"text":[{"text":"Car assemblers buy windscreens, tyres, headlamps and steel sheet from many suppliers; those suppliers in turn have their own suppliers. Firms also buy specialist marketing services (advertising, consulting, market research) from outside."}]},{"text":[{"text":"Intermediary examples: a Kano warehouse company storing a beverage maker's cartons = "},{"text":"distribution centre","bold":true},{"text":"; an Ikeja agency making radio jingles and billboards = "},{"text":"marketing agency","bold":true},{"text":"; a bank financing a distributor's stock = "},{"text":"financial intermediary","bold":true},{"text":". A raw-material supplier is "},{"text":"not","bold":true},{"text":" an intermediary."}]},{"text":[{"text":"Trap: in the supply chain the firm collaborates most closely with "},{"text":"suppliers and intermediaries","bold":true},{"text":"."}]},{"text":[{"text":"Some lists call agencies, research firms, banks, insurers, transport companies and brokers the firm's "},{"text":"partners","bold":true},{"text":": separate entities doing business with it."}]},{"text":[{"text":"Channels change slowly but constantly, like the hour hand of a watch; the firm must manage and satisfy its intermediaries."}]}]}]},{"number":"4.3","title":"Customers, competitors and publics (the rest of the micro environment)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Customers:","bold":true},{"text":" those who buy the organisation's products for final consumption; their "},{"text":"satisfaction is the organisation's main goal","bold":true},{"text":". They form the "},{"text":"demand side","bold":true},{"text":" of the micro environment. Firms do R&D to analyse customer needs and make products to match."}]}]},{"type":"paragraph","text":[{"text":"5 types of customer markets:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Consumer markets:","bold":true},{"text":" individuals and households buying for personal consumption."}]},{"text":[{"text":"Industrial (business) markets:","bold":true},{"text":" organisations buying goods and services to produce other products and services, for profit or other objectives."}]},{"text":[{"text":"Reseller markets:","bold":true},{"text":" organisations buying goods and services to resell at a profit."}]},{"text":[{"text":"Government and nonprofit markets:","bold":true},{"text":" agencies buying to produce public services or to transfer goods to those who need them."}]},{"text":[{"text":"International markets:","bold":true},{"text":" buyers abroad (foreign consumers, producers, resellers, governments)."}]}]},{"type":"paragraph","text":[{"text":"4 types of organisational buyers:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Industrial buyers:","bold":true},{"text":" procure products or services for use in manufacturing other products or for $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 16, $study_guide$operating their own businesses."}]},{"text":[{"text":"Resellers:","bold":true},{"text":" intermediaries that buy products in order to resell them."}]},{"text":[{"text":"Government agencies:","bold":true},{"text":" Federal, State and local government units that procure products and services to perform their social functions."}]},{"text":[{"text":"Institutional buyers:","bold":true},{"text":" buy for organisations that render services, such as museums, hospitals, schools and churches."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Business-to-business (B2B) marketers:","bold":true},{"text":" marketers who sell to business organisations rather than to individual consumers (B2C)."}]},{"text":[{"text":"Competition:","bold":true},{"text":" a situation in which various organisations offer similar products and try to gain market share by adopting different marketing strategies. Competitors push a firm to "},{"text":"differentiate","bold":true},{"text":" its product to maintain its position in the market."}]},{"text":[{"text":"Intratype competition:","bold":true},{"text":" between organisations that engage in the "},{"text":"same basic activity","bold":true},{"text":"."}]},{"text":[{"text":"Intertype competition:","bold":true},{"text":" between "},{"text":"different types","bold":true},{"text":" of organisations."}]},{"text":[{"text":"Public:","bold":true},{"text":" any group that has an actual or potential interest in, or impact on, an organisation's ability to achieve its objectives (serve its customers)."}]}]},{"type":"paragraph","text":[{"text":"7 publics:","bold":true},{"text":" financial (banks, investors), media (newspapers, radio, TV, blogs), government, citizen-action (consumer and environmental groups), local (community), general public, internal (employees, managers, board)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"market segments\" is "},{"text":"not","bold":true},{"text":" a type of customer market; \"individual buyers\" are "},{"text":"not","bold":true},{"text":" organisational buyers (they are consumers)."}]},{"text":[{"text":"Intratype examples: Coca-Cola's bottler against Seven-Up Bottling Company for soft-drink buyers; First Bank, UBA, Zenith and GTBank against each other for savings and loans. Intertype examples: finance houses or fintech apps against banks for savings customers."}]},{"text":[{"text":"Competitors","bold":true},{"text":" are the micro force that most directly challenges a firm's strategy (rivals' pricing and innovation tactics), and "},{"text":"competitor pricing and positioning","bold":true},{"text":" is the external factor that most directly affects a firm's own pricing."}]},{"text":[{"text":"Media public example: newspapers, radio stations and online blogs writing about a Lagos bank. Financial public: the bank's shareholders and lenders."}]}]}]},{"number":"4.4","title":"The macro environment","mustKnow":[{"type":"paragraph","text":[{"text":"6 macro forces:","bold":true},{"text":" demographic, economic, natural (physical), technological, political-legal, socio-cultural. Suppliers, intermediaries, customers, competitors and the company are "},{"text":"micro","bold":true},{"text":", never macro. Some lists add the "},{"text":"international situation","bold":true},{"text":"."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Demographic:","bold":true},{"text":" the scientific study of human population by age, gender, education, occupation, income, location, size, density, race, marriage and death rates (the "},{"text":"demographic variables","bold":true},{"text":"). Also covers the rising role of women. It explains variation in tastes and buying patterns. Prices are "},{"text":"not","bold":true},{"text":" demographic."}]},{"text":[{"text":"Economic:","bold":true},{"text":" affects the firm's "},{"text":"cost structure","bold":true},{"text":" and customers' "},{"text":"purchasing power","bold":true},{"text":". Purchasing power depends on "},{"text":"current income, prices of products, savings and availability of credit","bold":true},{"text":". Factors:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Inflation:","bold":true},{"text":" affects demand (higher petrol prices lead to a fall in demand for cars)."}]},{"text":[{"text":"Interest rates:","bold":true},{"text":" determine borrowing; higher rates may make firms cut important activities."}]},{"text":[{"text":"Unemployment:","bold":true},{"text":" a no-income state that reduces purchasing power."}]},{"text":[{"text":"Customer income:","bold":true},{"text":" changes spending patterns (e.g. on food and clothing)."}]},{"text":[{"text":"Monetary policy:","bold":true},{"text":" stabilises the economy by controlling "},{"text":"interest rates and money supply","bold":true},{"text":". "},{"text":"Fiscal policy:","bold":true},{"text":" government "},{"text":"spending","bold":true},{"text":", financed by revenue from "},{"text":"taxes","bold":true},{"text":"."}]},{"text":[{"text":"Others: economic growth (GDP, GNP), exchange rates, employment level, raw-material scarcity, energy costs, import duties, balance of trade, income distribution, savings, subsidies. Ethnic structure is "},{"text":"not","bold":true},{"text":" economic."}]}]}]},{"text":[{"text":"Natural (physical):","bold":true},{"text":" natural resources used as raw materials, plus natural conditions. Factors: "},{"text":"natural resources","bold":true},{"text":" (depletion leads some firms to "},{"text":"de-marketing","bold":true},{"text":"), "},{"text":"weather","bold":true},{"text":", "},{"text":"pollution","bold":true},{"text":" (air, water, noise). Also climate, floods, extreme heat, natural disasters, access to water."}]},{"text":[{"text":"Technological:","bold":true},{"text":" a rapidly changing force creating new opportunities and threats. "},{"text":"3 trends:","bold":true},{"text":" "},{"text":"pace of technological change","bold":true},{"text":" (fa$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 17, $study_guide$st change makes products obsolete quickly, so firms modify products often); "},{"text":"research and development","bold":true},{"text":" (raises growth opportunities); "},{"text":"increased regulation","bold":true},{"text":" (government guidelines that ban unsafe products, which marketers must know and obey)."}]},{"text":[{"text":"Political and legal:","bold":true},{"text":" legal bodies and government agencies that influence and limit organisations and individuals, plus laws, policies and pressure groups. "},{"text":"2 kinds of law:","bold":true},{"text":" "},{"text":"anti-pollution laws","bold":true},{"text":" (affect production) and "},{"text":"customer (consumer) legislation","bold":true},{"text":" (protects customers' interests)."}]},{"text":[{"text":"Socio-cultural:","bold":true},{"text":" society's basic "},{"text":"values, attitudes, perceptions and behaviour","bold":true},{"text":", lifestyles, beliefs and culture. It shapes what people buy, which brand, and when."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Demographic:","bold":true},{"text":" a telecoms firm sees that a very large share of Nigerians are under 30 and launches cheap student data bundles. Nigeria's large population makes it one of the biggest single markets in Africa."}]},{"text":[{"text":"Economic:","bold":true},{"text":" during a recession, watch economic conditions affecting purchasing power. Nigeria shows developing-economy traits: low incomes, low literacy and technology know-how, high unemployment, inadequate roads, power and telecoms. A weak naira raises the cost of imported raw materials, causing "},{"text":"low capacity utilisation","bold":true},{"text":". Poor infrastructure is a threat (traffic, higher costs) but also an opportunity for firms supplying it."}]},{"text":[{"text":"Worked example (interest rates):","bold":true},{"text":" a Nnewi auto-parts maker owes ₦50,000,000. At 20% a year, interest = 0.20 × ₦50,000,000 = ₦10,000,000. At 28%, interest = 0.28 × ₦50,000,000 = ₦14,000,000. Extra yearly cost = ₦4,000,000, so it postpones expansion. In Nigeria, monetary policy is set by the "},{"text":"Central Bank of Nigeria","bold":true},{"text":" (e.g. its policy rate); raising VAT to spend more on roads is "},{"text":"fiscal","bold":true},{"text":" policy."}]},{"text":[{"text":"Natural:","bold":true},{"text":" harmattan raises sales of body lotion, lip balm and petroleum jelly; the rainy season raises umbrella sales; hot months raise fans and cold drinks. Plastic waste blocking Lagos drains pushes supermarkets towards paper bags. "},{"text":"De-marketing:","bold":true},{"text":" a petroleum marketer urging the public to use less of its own fuel."}]},{"text":[{"text":"Technology:","bold":true},{"text":" smartphones and instant transfers let a Yaba vendor sell on Instagram and take transfers instead of cash. Technology can be a constraint when equipment is lacking; firms that ignore it struggle to survive. In Nigeria, drugs and foods must be registered with "},{"text":"NAFDAC","bold":true},{"text":", and product standards are set by the "},{"text":"Standards Organisation of Nigeria (SON)","bold":true},{"text":"."}]},{"text":[{"text":"Political-legal (Nigeria):","bold":true},{"text":" the "},{"text":"Federal Competition and Consumer Protection Act 2018","bold":true},{"text":" (enforced by the "},{"text":"FCCPC","bold":true},{"text":") protects consumers; "},{"text":"ARCON","bold":true},{"text":" (formerly APCON) regulates advertising; "},{"text":"NESREA","bold":true},{"text":" enforces environmental standards; tobacco packs must carry a health warning. Lagos State banned styrofoam food packs, forcing eateries to switch packaging. Government also "},{"text":"facilitates","bold":true},{"text":": tax incentives for growth industries, development-bank loans, research institutes such as FIIRO. Political stability attracts business; instability hurts the economy."}]},{"text":[{"text":"Socio-cultural:","bold":true},{"text":" with husbands and wives both working full-time, families have less time to shop, so supermarkets and malls with everything under one roof grow. Nigerian values include respect for age and extended-family responsibility; Yoruba, Hausa and Igbo "},{"text":"sub-cultures","bold":true},{"text":" can be treated as segments. Values also cover attitudes to health and nutrition, materialism, self-expression, product safety and ecology."}]},{"text":[{"text":"International situation:","bold":true},{"text":" easier shipping and communication widen markets, but trade barriers (quotas, duties) and different economies, cultures and politics add risk."}]}]}]},{"number":"4.5","title":"PESTLE, SWOT, environmental scanning and why the environment matters","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PESTLE:","bold":true},{"text":" a checklist for the macro environment: "},{"text":"P","bold":true},{"text":"olitical, "},{"text":"E","bold":true},{"text":"conomic, "},{"text":"S","bold":true},{"text":"ocial, "},{"text":"T","bold":true},{"text":"echnological, "},{"text":"L","bold":true},{"text":"egal, "},{"text":"E","bold":true},{"text":"nvironmental (natural). PEST is the shorter version."}]},{"text":[{"text":"SWOT:","bold":true},{"text":" "},{"text":"S","bold":true},{"text":"trengths and "},{"text":"W","bold":true},{"text":"eaknesses (internal, controllable); "},{"text":"O","bold":true},{"text":"pportunities and "},{"text":"T","bold":true},{"text":"hreats (external)."}]},{"text":[{"text":"Environmental scanning:","bold":true},{"text":" the systematic process of gathering and monitoring information about a company's external events and relationships, to detect trends, opportunities and threats early enough to respond and to help top management decide its future course."}]},{"text":[{"text":"3 phases of scanning:","bold":true},{"text":" data gathering; environmental interpretation (analysis); strategy formulation."}]},{"text":[{"text":"Sources:","bold":true}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 18, $study_guide$,{"text":" company reports, industry reports, magazines, newspapers, government reports, marketing-intelligence reports, personal networking (e.g. trade fairs)."}]},{"text":[{"text":"Controllable variables:","bold":true},{"text":" the internal factors and the marketing mix (the firm's own "},{"text":"product, price, place, promotion","bold":true},{"text":"). "},{"text":"Uncontrollable:","bold":true},{"text":" macro forces such as inflation, population growth and competitors' decisions."}]},{"text":[{"text":"Strategic window:","bold":true},{"text":" a short period in which a company must adjust its strategic marketing approach to new market realities, or quit the market if it fails to adjust. "},{"text":"4 changes create it:","bold":true},{"text":" new primary demand (growth in the overall market); new technology; market redefinition through competitive activity; changes in distribution channels."}]},{"text":[{"text":"Megamarketing:","bold":true},{"text":" the use of "},{"text":"power and public relations","bold":true},{"text":" (also lobbying and lawsuits) to penetrate "},{"text":"blocked or protected markets","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"3 importances of studying the marketing environment:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identification of opportunities","bold":true},{"text":" (e.g. exploiting customer preference with discounts)."}]},{"text":[{"text":"Identification of threats","bold":true},{"text":" (warning signals before it is too late)."}]},{"text":[{"text":"Managing changes","bold":true},{"text":" (adapting to survive in the long run)."}]}]},{"type":"paragraph","text":[{"text":"Environmental analysis also helps the marketer to:","bold":true},{"text":" know the changes; gain quality information for strategy; understand market needs and modify products; handle government-legal-regulatory policies; allocate resources and diversify; identify threats (new competitors, price wars, rival products); identify opportunities (new markets, mergers, joint ventures, alliances, a vacuum left by an exiting competitor); identify weaknesses (low-quality goods, lack of marketing expertise, no unique products) and turn them into strengths; identify and exploit strengths. It also aids planning, understanding customers and competitors, and "},{"text":"first-mover advantage","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Threat: a juice maker hears a foreign multinational is entering and prepares price cuts and heavy promotion. Opportunity: a rival paint brand exits and a local maker wins its retailers. Weakness: an Ibadan cosmetics firm finds poor packaging and no marketing expertise."}]},{"text":[{"text":"\"Eliminating all competition\" is "},{"text":"never","bold":true},{"text":" a benefit of environmental study."}]},{"text":[{"text":"Environmental analysis comes first in the situation analysis, so that "},{"text":"positioning","bold":true},{"text":" (target-market choice) and the "},{"text":"marketing mix","bold":true},{"text":" can be adjusted. Example: more working mothers make day-care a more attractive segment."}]},{"text":[{"text":"Megamarketing is not guaranteed: it is costly, decided by top management and uncertain. Do not confuse it with "},{"text":"demarketing","bold":true},{"text":" (reducing demand) or "},{"text":"synchromarketing","bold":true},{"text":" (smoothing irregular demand)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing environment = all internal and external factors that directly or indirectly influence marketing decisions; internal is controllable, external is not."}]},{"text":[{"text":"5 features: specific and general forces, complexity, vibrancy (dynamic), uncertainty (unpredictable), relativity (demand differs by place)."}]},{"text":[{"text":"Micro (immediate, direct): company, suppliers, intermediaries, customers, competitors, publics; supply side vs demand side (customers)."}]},{"text":[{"text":"4 intermediaries: resellers, distribution centres, marketing agencies, financial intermediaries; 5 utilities: place, time, quantity, assortment, possession."}]},{"text":[{"text":"5 customer markets; 4 organisational buyers (industrial, resellers, government, institutional); intratype vs intertype competition; make-or-buy."}]},{"text":[{"text":"Macro (broad, uncontrollable): demographic, economic, natural, technological, political-legal, socio-cultural."}]},{"text":[{"text":"Purchasing power = income, prices, savings, credit; monetary = interest rates and money supply; fiscal = spending and taxes."}]},{"text":[{"text":"PESTLE, SWOT, scanning (3 phases); importance: opportunities, threats, managing change."}]},{"text":[{"text":"Strategic window = short time to adjust or quit; megamarketing = power and PR to enter blocked markets."}]}]}],"theory":{"itemId":"5b9e7ccf-c51f-5566-a2aa-618ec4cf7099","question":[{"type":"paragraph","text":[{"text":"Distinguish the micro environment from the macro environment and give three forces in each."}]}]},"practice":[{"topic":"Marketing Environment","named":false}]}},{"kind":"note","itemId":"409cb076-fc9e-55ab-a382-4058d9adb132","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Consumer and Organisational Buying Behaviour","body":"The meaning of buying behaviour; the six stages of the consumer buying decision process and cognitive dissonance; involvement, perceived risk and the types of buying behaviour; the three categories of factors (personal, psychological, social) and everything inside each; family buying roles and reference groups; organisational markets, the buying centre, the three buy classes and the buy phases.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The meaning of buying behaviour; the six stages of the consumer buying decision process and cognitive dissonance; involvement, perceived risk and the types of buying behaviour; the three $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 19, $study_guide$categories of factors (personal, psychological, social) and everything inside each; family buying roles and reference groups; organisational markets, the buying centre, the three buy classes and the buy phases."}],"lessons":[{"number":"5.1","title":"Meaning of buying behaviour and the buying decision process","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Buying behaviour:","bold":true},{"text":" the decisions and actions of people involved in buying and using products."}]},{"text":[{"text":"Consumer buying behaviour:","bold":true},{"text":" the buying behaviour of the "},{"text":"ultimate (final) consumer","bold":true},{"text":", who buys for personal or household use."}]},{"text":[{"text":"Consumer behaviour as a field","bold":true},{"text":" is multidisciplinary: it covers the "},{"text":"psychological, social and cultural influences","bold":true},{"text":" on purchase decisions."}]},{"text":[{"text":"Why study it:","bold":true},{"text":" studying what, where, when and how people buy lets marketers "},{"text":"predict how buyers are likely to respond to marketing stimuli","bold":true},{"text":" and build a marketing mix that gives customers satisfaction (utility)."}]}]},{"type":"paragraph","text":[{"text":"The 6 stages of the consumer buying decision process (complex decision):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Problem recognition","bold":true},{"text":" (need awareness): the buyer becomes aware of a "},{"text":"gap between a desired state and an actual state","bold":true},{"text":". Always the "},{"text":"first","bold":true},{"text":" step."}]},{"text":[{"text":"Information search:","bold":true},{"text":" "},{"text":"internal","bold":true},{"text":" (the buyer's own memory of past purchases) and "},{"text":"external","bold":true},{"text":" (word of mouth from friends and relatives, marketer-controlled sources such as adverts and salespeople, comparison shopping, public sources such as consumer reports). The result is a short list of alternatives called the "},{"text":"evoked set","bold":true},{"text":" (consideration set)."}]},{"text":[{"text":"Evaluation of alternatives:","bold":true},{"text":" the buyer sets "},{"text":"criteria","bold":true},{"text":" (wanted and unwanted features), then "},{"text":"ranks or weights","bold":true},{"text":" the options, or goes back to search."}]},{"text":[{"text":"Purchase decision:","bold":true},{"text":" choosing the alternative: product, package, store, method of payment."}]},{"text":[{"text":"Purchase:","bold":true},{"text":" the actual buying. It "},{"text":"can differ","bold":true},{"text":" from the decision (time gap, out of stock)."}]},{"text":[{"text":"Post-purchase evaluation:","bold":true},{"text":" outcome is "},{"text":"satisfaction or dissatisfaction","bold":true},{"text":". Always the "},{"text":"last","bold":true},{"text":" step."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Cognitive dissonance:","bold":true},{"text":" doubt felt by a buyer, "},{"text":"after","bold":true},{"text":" a purchase, about whether the right choice was made. Reduced by "},{"text":"warranties, after-sales communication","bold":true},{"text":", and channels for customers to contact the firm."}]},{"text":[{"text":"A shorter "},{"text":"four-step","bold":true},{"text":" version of the complex process: (1) problem recognition, (2) information search and brand evaluation, (3) product choice and purchase, (4) post-purchase evaluation (satisfaction or dissatisfaction). First and last steps are the same in both versions."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory hook: "},{"text":"Problem, Search, Evaluate, Decide, Buy, Review","bold":true},{"text":". Traps swap \"purchase decision\" and \"purchase\", or put evaluation before search."}]},{"text":[{"text":"Marketers can trigger problem recognition.","bold":true},{"text":" Tunde had not thought about sneakers until a billboard for a new design made him notice his old pair was worn out."}]},{"text":[{"text":"Internal versus external search:","bold":true},{"text":" Amaka recalling how last year's hair dryer performed is "},{"text":"internal","bold":true},{"text":" search. Asking friends, reading Jumia reviews or touring Computer Village is "},{"text":"external","bold":true},{"text":"; memory is "},{"text":"never","bold":true},{"text":" external."}]},{"text":[{"text":"Evoked set:","bold":true},{"text":" a student who ends up seriously considering only Tecno, Infinix and Samsung has those three as the evoked set. Marketers influence evaluation by \"framing\" alternatives (stressing the criteria their brand wins on)."}]},{"text":[{"text":"Decision versus purchase:","bold":true},{"text":" Funmi chose one phone brand, found it out of stock, and bought another."}]},{"text":[{"text":"Not every process ends in a purchase","bold":true},{"text":", and only complex (extensive) decisions pass through all six stages."}]},{"text":[{"text":"Dissonance:","bold":true},{"text":" a new-car buyer who fears the rival model was better is reassured by the dealer's warranty, thank-you call and helpline. Removing contact channels makes dissonance "},{"text":"worse","bold":true},{"text":"."}]}]}]},{"number":"5.2","title":"Involvement, perceived risk and types of buying behaviour","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Level of involvement:","bold":true},{"text":" the "},{"text":"importance and intensity of interest","bold":true},{"text":" in a product in a particular situation. It "},{"text":"determines the type of buying behaviour","bold":true},{"text":"."}]},{"text":[{"text":"High-involvement purchases:","bold":true},{"text":" purchases that are "},{"text":"important","bold":true},{"text":" to the consumer: high-priced, risky or publicly visible goods (a Honda motorbike, a car, a house)."}]},{"text":[{"text":"Low-involvement purchases:","bold":true},{"text":" made when consumer$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 20, $study_guide$s do "},{"text":"not","bold":true},{"text":" consider the product important or risky enough to give it much thought and deliberation."}]},{"text":[{"text":"As perceived risk rises, involvement "},{"text":"increases","bold":true},{"text":"."}]},{"text":[{"text":"Types of perceived risk:","bold":true},{"text":" "},{"text":"personal","bold":true},{"text":", "},{"text":"social","bold":true},{"text":" (fear of what others will think), "},{"text":"economic","bold":true},{"text":" (losing money). Extensive (expensive, unfamiliar) purchases also carry high "},{"text":"performance","bold":true},{"text":" and "},{"text":"psychological","bold":true},{"text":" risk."}]}]},{"type":"paragraph","text":[{"text":"4 types of consumer buying behaviour:","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Involvement"}],[{"text":"Features"}],[{"text":"Examples"}]],"rows":[[[{"text":"1. "},{"text":"Routine response","bold":true},{"text":" (programmed) behaviour"}],[{"text":"Low"}],[{"text":"Frequent, low-cost, little search or effort, almost automatic"}],[{"text":"Soft drinks, snacks, milk, Indomie"}]],[[{"text":"2. "},{"text":"Limited decision making","bold":true}],[{"text":"Moderate"}],[{"text":"Occasional purchase; familiar product category but "},{"text":"unfamiliar brand","bold":true},{"text":"; moderate search time"}],[{"text":"A new brand of jeans"}]],[[{"text":"3. "},{"text":"Extensive decision making","bold":true},{"text":" (complex, high involvement)"}],[{"text":"High"}],[{"text":"Unfamiliar, expensive, bought rarely, high perceived risk, a lot of search; passes through all 6 stages"}],[{"text":"Cars, homes, computers, education"}]],[[{"text":"4. "},{"text":"Impulse buying","bold":true}],[{"text":"Low"}],[{"text":"No conscious planning","bold":true},{"text":"; a sudden urge to buy"}],[{"text":"Chocolate at the fuel-station counter"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Complex decision making","bold":true},{"text":" (= extensive) is a high-involvement purchase that requires a great deal of thought."}]},{"text":[{"text":"Inertia:","bold":true},{"text":" repeatedly buying the same brand mainly because it "},{"text":"saves effort","bold":true},{"text":", not because of strong commitment. "},{"text":"Brand loyalty","bold":true},{"text":" is repeat buying "},{"text":"with","bold":true},{"text":" strong commitment."}]}]},{"type":"paragraph","text":[{"text":"Kotler's 4 types (involvement plus differences between brands):","bold":true}]},{"type":"table","header":[[],[{"text":"High involvement"}],[{"text":"Low involvement"}]],"rows":[[[{"text":"Significant differences between brands","bold":true}],[{"text":"Complex buying behaviour"}],[{"text":"Variety-seeking buying behaviour"}]],[[{"text":"Few differences between brands","bold":true}],[{"text":"Dissonance-reducing buying behaviour"}],[{"text":"Habitual buying behaviour"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited:","bold":true},{"text":" Bola buys clothes often but asks friends before trying a jeans brand she has never used. "},{"text":"Extensive:","bold":true},{"text":" a couple buying their first house consult friends, relatives and estate agents for weeks. "},{"text":"Impulse:","bold":true},{"text":" Ngozi stops for fuel and buys an unplanned chocolate bar. \"Frequent purchase of low-cost items\" is "},{"text":"routine response","bold":true},{"text":", never extensive."}]},{"text":[{"text":"Risk examples:","bold":true},{"text":" Chioma avoids a cheap-looking dress because classmates may laugh at her: "},{"text":"social risk","bold":true},{"text":". Emeka hesitates over a ₦2,500,000 used car because he could lose a lot of money if it is faulty: "},{"text":"economic risk","bold":true},{"text":"."}]},{"text":[{"text":"The same product can trigger different behaviour.","bold":true},{"text":" Dinner out is extensive for someone who rarely eats out and limited for a regular; an anniversary dinner gets more thought than a casual one."}]},{"text":[{"text":"Kotler's grid:","bold":true},{"text":" complex = a laptop; dissonance-reducing = floor tiles (costly, brands look alike, so the buyer later seeks reassurance); habitual = salt (often inertia); variety-seeking = biscuits (switching for change, not dissatisfaction)."}]},{"text":[{"text":"Impulse buying","bold":true},{"text":" is driven mainly by "},{"text":"motivation tied to immediate gratification","bold":true},{"text":", a psychological factor. About 60% of purchases are unplanned, so sweets sit at the checkout."}]}]}]},{"number":"5.3","title":"Factors influencing consumer behaviour and psychological factors","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"3 categories of factors","bold":true},{"text":" affecting the consumer buying decision process: "},{"text":"personal, psychological and social","bold":true},{"text":". Kotler splits "},{"text":"cultural","bold":true},{"text":" out of social, giving "},{"text":"4","bold":true},{"text":": cultural, social, personal, psychological."}]}]},{"type":"table","header":[[{"text":"Category"}],[{"text":"What it covers"}]],"rows":[[[{"text":"Personal","bold":true},{"text":" influences"}],[{"text":"The "},{"text":"personal characteristics","bold":true},{"text":" of the consumer: age and life-cycle stage, occupation, economic situation, demographics (sex, race), lifestyle, who in the family decides"}]],[[{"text":"Psychological","bold":true},{"text":" influences"}],[{"text":"Motives (motivation), "},{"text":"perception, learning (ability and knowledge), attitudes","bold":true},{"text":", personality and self-concept"}]],[[{"text":"Social","bold":true},{"text":" influences"}],[{"text":"Roles and family, "},{"text":"reference groups","bold":true},{"text":", social class, "},{"text":"culture and subculture","bold":true}]]]},{"type":"paragraph","text":[{"text":"Psychological factors:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Motive:","bol$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 21, $study_guide$d":true},{"text":" an "},{"text":"internal energising force","bold":true},{"text":" that directs a person's activities towards satisfying a need or achieving a goal. Behaviour is usually driven by several motives at once."}]},{"text":[{"text":"Maslow's hierarchy of needs (5 levels, lowest to highest):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physiological","bold":true},{"text":" (food, water, shelter)"}]},{"text":[{"text":"Safety","bold":true},{"text":" (security, protection)"}]},{"text":[{"text":"Love and belonging","bold":true},{"text":" (social acceptance, affection)"}]},{"text":[{"text":"Esteem","bold":true},{"text":" (status, recognition, respect)"}]},{"text":[{"text":"Self-actualisation","bold":true},{"text":" (reaching one's full potential)"}]}]}]},{"text":[{"text":"Perception:","bold":true},{"text":" the process of "},{"text":"selecting, organising and interpreting","bold":true},{"text":" information inputs received through the senses (sight, taste, hearing, smell, touch) to produce meaning."}]},{"text":[{"text":"3 selective processes","bold":true},{"text":" of perception:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Selective exposure:","bold":true},{"text":" choosing which inputs reach awareness (we notice what meets current needs, or a sharp change such as a big price cut)."}]},{"text":[{"text":"Selective distortion:","bold":true},{"text":" changing or twisting information that conflicts with what we already believe."}]},{"text":[{"text":"Selective retention:","bold":true},{"text":" remembering information that supports our beliefs and forgetting what does not."}]}]}]},{"text":[{"text":"Learning:","bold":true},{"text":" a "},{"text":"relatively permanent change in behaviour","bold":true},{"text":" that results from the consequences of past behaviour and experience."}]},{"text":[{"text":"Knowledge:","bold":true},{"text":" familiarity with or expertise in a product. Buyers with little knowledge or experience tend to "},{"text":"use price as an indicator of quality","bold":true},{"text":"."}]},{"text":[{"text":"Attitude:","bold":true},{"text":" a person's "},{"text":"knowledge and positive or negative feelings","bold":true},{"text":" about an object or activity (tangible or intangible, living or not). Attitudes are "},{"text":"learned","bold":true},{"text":" through experience and interaction, and they shape perception."}]},{"text":[{"text":"Personality:","bold":true},{"text":" all the "},{"text":"internal traits and behaviours","bold":true},{"text":" that make a person unique, arising from "},{"text":"heredity and experience","bold":true},{"text":". Traits: workaholism, compulsiveness, self-confidence, friendliness, adaptability, ambitiousness, dogmatism, authoritarianism, introversion, extroversion, aggressiveness."}]},{"text":[{"text":"Self-concept","bold":true},{"text":" is also known as "},{"text":"self-image","bold":true},{"text":": the way a person sees himself or herself. People buy brands that match that image."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Maslow in action:","bold":true},{"text":" a newly promoted bank manager buys a designer watch so colleagues admire his status: "},{"text":"esteem","bold":true},{"text":". A nutritional drink was marketed to fitness and energy-conscious buyers (belonging or esteem level), but research showed low-income inner-city buyers used it as a "},{"text":"meal substitute","bold":true},{"text":": "},{"text":"physiological","bold":true},{"text":". Motives are often subconscious and hard to measure. Order trap: safety comes "},{"text":"before","bold":true},{"text":" love and belonging; esteem comes "},{"text":"after","bold":true},{"text":" it."}]},{"text":[{"text":"Selective exposure:","bold":true},{"text":" of about 1,500 adverts Kemi sees daily, she notices the one announcing a big price cut on the laptop she needs. "},{"text":"Selective distortion:","bold":true},{"text":" an MTN advert compares its data plans with a rival's, and viewers who favour the rival remember it as the rival's advert. This is the danger of comparative adverts. "},{"text":"Selective retention:","bold":true},{"text":" Seyi remembers praise for his favourite boot brand and forgets last week's bad review."}]},{"text":[{"text":"\"Selective motivation\" is "},{"text":"not","bold":true},{"text":" a selective process; there are only three (exposure, distortion, retention)."}]},{"text":[{"text":"Learning:","bold":true},{"text":" to change behaviour, give new product information and experience, e.g. "},{"text":"free samples","bold":true},{"text":". "},{"text":"Price as quality cue:","bold":true},{"text":" buyers new to non-alcoholic beer picked the dearest six-pack."}]},{"text":[{"text":"Attitudes:","bold":true},{"text":" a favourable attitude does "},{"text":"not","bold":true},{"text":" always mean the person intends to buy or is able to buy. A student may love the newest iPhone yet be unable to afford it. "},{"text":"Social class is not a personality trait","bold":true},{"text":"; it is a social factor."}]}]}]},{"number":"5.4","title":"Personal and social factors","mustKnow":[{"type":"paragraph","text":[{"text":"Family life cycle stages","bold":true},{"text":" (part of the personal factor \"life-cycle stage\"):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Bachelor stage (young, single)"}]},{"text":[{"text":"Newly married, no children"}]},{"text":[{"text":"Full nest I (youngest child under 6)"}]},{"text":[{"text":"Full nest II (youngest child 6 or over)"}]},{"text":[{"text":"Full nest III (older couple, dependent children)"}]},{"text":[{"text":"Empty nest I:","bold":true},{"text":" older married, no children at home, head "},{"text":"still working","bold":true}]},{"text":[{"text":"Empty nest II:","bold":true},{"text":" older married, no children at home, head "},{"text":"retired","bold":true}]},{"text":[{"text":"Solitary s$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 22, $study_guide$urvivor, in the labour force"}]},{"text":[{"text":"Solitary survivor, retired"}]}]},{"type":"paragraph","text":[{"text":"The "},{"text":"modernised","bold":true},{"text":" family life cycle adds divorced and childless households."}]},{"type":"paragraph","text":[{"text":"Family decision-making roles:","bold":true}]},{"type":"table","header":[[{"text":"Role"}],[{"text":"What the person does"}]],"rows":[[[{"text":"Initiator","bold":true}],[{"text":"Recognises the problem and "},{"text":"begins","bold":true},{"text":" the decision-making process"}]],[[{"text":"Influencer","bold":true}],[{"text":"Exerts "},{"text":"personal influence","bold":true},{"text":" on the decision"}]],[[{"text":"Information gatherer","bold":true}],[{"text":"Seeks information","bold":true},{"text":" about available products and their characteristics"}]],[[{"text":"Decision maker","bold":true},{"text":" (decider)"}],[{"text":"Makes the "},{"text":"final decision","bold":true}]],[[{"text":"Purchaser","bold":true},{"text":" (buyer)"}],[{"text":"Actually buys the product"}]],[[{"text":"User","bold":true}],[{"text":"Consumes or uses the product"}]]]},{"type":"paragraph","text":[{"text":"Kotler's general "},{"text":"buying roles","bold":true},{"text":" (5): initiator, influencer, decider, buyer, user."}]},{"type":"paragraph","text":[{"text":"Reference group:","bold":true},{"text":" a group whose values, attitudes or behaviour a person adopts and uses as a guide (family, friends, associations, civic and professional bodies). It can influence positively or negatively."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3 types:","bold":true},{"text":" "},{"text":"membership","bold":true},{"text":" group (you belong to it), "},{"text":"aspiration","bold":true},{"text":" group (you want to belong to it), "},{"text":"disassociative","bold":true},{"text":" group (you do not want to belong to it)."}]},{"text":[{"text":"The "},{"text":"family","bold":true},{"text":" is the most important "},{"text":"primary","bold":true},{"text":" reference group."}]},{"text":[{"text":"3 kinds of influence","bold":true},{"text":" a reference group exerts:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Informational influence:","bold":true},{"text":" it is a source of "},{"text":"believable information","bold":true},{"text":" about brands and companies."}]},{"text":[{"text":"Comparative influence:","bold":true},{"text":" it gives members something to "},{"text":"compare","bold":true},{"text":" their beliefs, attitudes and behaviour "},{"text":"against","bold":true},{"text":"."}]},{"text":[{"text":"Normative influence:","bold":true},{"text":" it persuades members to "},{"text":"conform to its norms","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Affinity marketing:","bold":true},{"text":" marketing aimed at members of a reference group, with the group endorsing the product to its members (e.g. a credit card endorsed by an alumni association)."}]},{"text":[{"text":"A group's influence depends on the person's "},{"text":"susceptibility","bold":true},{"text":" and "},{"text":"strength of involvement","bold":true},{"text":" with the group."}]}]},{"type":"paragraph","text":[{"text":"Social class:","bold":true},{"text":" an "},{"text":"open","bold":true},{"text":" group of people with "},{"text":"similar social rank","bold":true},{"text":", based on occupation, education, income, wealth, race, ethnicity and possessions. It shapes the type, quality and quantity of products bought."}]},{"type":"paragraph","text":[{"text":"Culture:","bold":true},{"text":" the values, ideas and attitudes accepted by a "},{"text":"homogeneous","bold":true},{"text":" group of people and "},{"text":"passed down from one generation to the next","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Subculture:","bold":true},{"text":" a sub-group within a culture with its own "},{"text":"distinguishing modes of behaviour","bold":true},{"text":", based on geographic region or human characteristics such as age and ethnic background. In Nigeria: "},{"text":"Yoruba, Hausa and Igbo","bold":true},{"text":" subcultures, among others."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps: \"age and life-cycle stage\" is "},{"text":"personal","bold":true},{"text":"; \"social status\", \"peer influence\" and \"cultural heritage\" are "},{"text":"social","bold":true},{"text":". \"Head still working\" = "},{"text":"Empty nest I","bold":true},{"text":"; \"head retired\" = "},{"text":"Empty nest II","bold":true},{"text":"."}]},{"text":[{"text":"Family roles at home:","bold":true},{"text":" a child says the family needs a new television (initiator); the mother compares prices online at Slot and Jumia (information gatherer); the eldest son argues for a smart TV (influencer); the father decides (decision maker); the mother pays at the shop (purchaser); everyone watches (users). In dual-income homes children influence more purchases."}]},{"text":[{"text":"Reference groups:","bold":true},{"text":" Kunle, a 200L accounting student, copies the suits and briefcases of a professional accounting body he hopes to join: an "},{"text":"aspiration group","bold":true},{"text":". A friend's honest phone review: informational influence. Classmates who mock anyone not wearing a certain sneaker brand: normative influence. Reference group endorsements are a "},{"text":"social","bold":true},{"text":" factor shaping brand loyalty among young adults."}]},{"text":[{"text":"Social class:","bold":true},{"text":" upper-middle-class buyers lean towards brands like Mercedes; lower-class shoppers tend to shop near home and do little information search. Stores project class images (a Lekki boutique versus a Balogun stall). \"Open\" means people can move between classes."}]},{"text":[{"text":"Culture in Nigeria:","bold":true},{"text":" respect for age and duty to the extended family shape buying. Culture also decides which adverts are accepta$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 23, $study_guide$ble: drinking beer in the open is normal in Lagos but may be frowned upon in parts of the North. Wise firms treat subcultures as separate market segments."}]},{"text":[{"text":"Family, reference groups and social class are all social influences operating "},{"text":"inside","bold":true},{"text":" a wider culture. So \"culture, subculture and reference groups\" are correctly called social influences in the three-category scheme."}]}]}]},{"number":"5.5","title":"Organisational markets and organisational buying behaviour","mustKnow":[{"type":"paragraph","text":[{"text":"Kotler's 5 customer markets:","bold":true},{"text":" "},{"text":"consumer","bold":true},{"text":" (individuals and households buying for personal use) plus four "},{"text":"organisational","bold":true},{"text":" markets:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Industrial (producer):","bold":true},{"text":" buy to produce other goods and services for profit or other objectives."}]},{"text":[{"text":"Reseller:","bold":true},{"text":" buy goods and services "},{"text":"in order to resell them at a profit","bold":true},{"text":" (wholesalers, retailers)."}]},{"text":[{"text":"Government and non-profit:","bold":true},{"text":" buy to produce public services or pass goods to those who need them."}]},{"text":[{"text":"International:","bold":true},{"text":" buyers abroad (consumers, producers, resellers, governments)."}]}]},{"type":"paragraph","text":[{"text":"Organisational versus consumer markets:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Fewer but larger buyers.","bold":true}]},{"text":[{"text":"Geographically concentrated","bold":true},{"text":"; consumer markets comprise many thousands of scattered consumers."}]},{"text":[{"text":"Derived demand:","bold":true},{"text":" comes from the demand for consumer goods."}]},{"text":[{"text":"Demand is fairly "},{"text":"inelastic","bold":true},{"text":" and "},{"text":"fluctuates","bold":true},{"text":" more."}]},{"text":[{"text":"More "},{"text":"formal","bold":true},{"text":" buying by "},{"text":"trained, professional","bold":true},{"text":" buyers, with "},{"text":"many people","bold":true},{"text":" involved."}]},{"text":[{"text":"Close buyer-seller relationships","bold":true},{"text":"; direct buying, reciprocity, leasing."}]},{"text":[{"text":"Industrial products are "},{"text":"more technical and complex","bold":true},{"text":" than consumer products."}]}]},{"type":"paragraph","text":[{"text":"Buying centre:","bold":true},{"text":" the "},{"text":"decision-making unit","bold":true},{"text":" of a buying organisation: all the individuals and groups who participate in its purchasing decision process."}]},{"type":"table","header":[[{"text":"Buying centre role"}],[{"text":"What they do"}]],"rows":[[[{"text":"Users","bold":true}],[{"text":"Will "},{"text":"use","bold":true},{"text":" the product or service"}]],[[{"text":"Influencers","bold":true}],[{"text":"Provide "},{"text":"information","bold":true},{"text":" that influences the decision (often technical staff who draw up specifications)"}]],[[{"text":"Buyers","bold":true}],[{"text":"Have "},{"text":"formal authority","bold":true},{"text":" to select the supplier and arrange the terms of purchase"}]],[[{"text":"Deciders","bold":true}],[{"text":"Make the "},{"text":"final decision","bold":true}]],[[{"text":"Approvers","bold":true}],[{"text":"Authorise","bold":true},{"text":" the actions proposed by deciders or buyers"}]],[[{"text":"Gatekeepers","bold":true}],[{"text":"Control the flow of information","bold":true},{"text":" into the organisation (and access to members)"}]]]},{"type":"paragraph","text":[{"text":"Kotler adds "},{"text":"initiators","bold":true},{"text":" (those who first request the purchase). \"Promoter\" is "},{"text":"not","bold":true},{"text":" a buying centre role."}]},{"type":"paragraph","text":[{"text":"Buy classes:","bold":true},{"text":" organisational buying situations are divided into "},{"text":"3 classes","bold":true},{"text":", called "},{"text":"buy classes","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Straight rebuy:","bold":true},{"text":" a routine reorder; the company has "},{"text":"extensive experience","bold":true},{"text":", the process is simple and routine, nothing changes."}]},{"text":[{"text":"Modified rebuy:","bold":true},{"text":" a "},{"text":"recurring purchase that is less routine","bold":true},{"text":"; the buyer changes specifications, prices, terms or suppliers."}]},{"text":[{"text":"New task:","bold":true},{"text":" buying something "},{"text":"for the first time","bold":true},{"text":"; requires the buyer to undertake a new purchasing task, with the most information search and the most people involved."}]}]},{"type":"paragraph","text":[{"text":"\"Limited decision making\" is a "},{"text":"consumer","bold":true},{"text":" behaviour type, "},{"text":"not","bold":true},{"text":" a buy class."}]},{"type":"paragraph","text":[{"text":"Buy phases:","bold":true},{"text":" the stages of the organisational buying decision process (Kotler's 8):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Problem recognition:","bold":true},{"text":" someone in the company recognises an "},{"text":"unmet need","bold":true},{"text":" that can be met by acquiring a good or service"}]},{"text":[{"text":"General need description"}]},{"text":[{"text":"Product specification"}]},{"text":[{"text":"Supplier search"}]},{"text":[{"text":"Proposal solicitation"}]},{"text":[{"text":"Supplier selection"}]},{"text":[{"text":"Order-routine specification"}]},{"text":[{"text":"Performance review"}]}]},{"type":"paragraph","text":[{"text":"4 major influences on organisational buying:","bold":true},{"text":" "},{"text":"environmental","bold":true},{"text":" (economy, technology, politics, competition), "},{"text":"organisational","bold":true},{"text":" (objectives, policies, procedure$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 24, $study_guide$s, structure), "},{"text":"interpersonal","bold":true},{"text":" (the "},{"text":"buying centre","bold":true},{"text":"), "},{"text":"individual","bold":true},{"text":" (each buyer's age, education, position, personality, attitude to risk). Market segmentation is "},{"text":"not","bold":true},{"text":" one."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Derived demand:","bold":true},{"text":" when more households build houses, demand for cement rises, so a cement maker's demand for "},{"text":"limestone","bold":true},{"text":" rises."}]},{"text":[{"text":"Buying centre in action:","bold":true},{"text":" at an oil-servicing firm in Port Harcourt, the manager's secretary decides which sales representatives see him and which brochures reach his desk: "},{"text":"gatekeeper","bold":true},{"text":". At a bottling company, operators who will run a new filling machine every day: "},{"text":"users","bold":true},{"text":". Engineers who write crane specifications but do not place the order: "},{"text":"influencers","bold":true},{"text":". A purchasing officer with formal authority to pick the supplier and negotiate terms: "},{"text":"buyer","bold":true},{"text":". A ₦15,000,000 generator recommended by the purchasing team cannot go ahead until the managing director signs: "},{"text":"approver","bold":true},{"text":"."}]},{"text":[{"text":"Buy classes in action:","bold":true},{"text":" a Lagos school reorders the same A4 paper from the same supplier every month with no changes: "},{"text":"straight rebuy","bold":true},{"text":". A hotel changes the fabric specification for bed sheets and invites two new suppliers to quote alongside its current one: "},{"text":"modified rebuy","bold":true},{"text":". A Kano textile company buys a solar power system for the first time after gathering a great deal of information: "},{"text":"new task","bold":true},{"text":"."}]},{"text":[{"text":"Performance review","bold":true},{"text":" is the "},{"text":"last","bold":true},{"text":" buy phase: the firm checks how well the chosen supplier performed."}]},{"text":[{"text":"Do not confuse the "},{"text":"family roles","bold":true},{"text":" (initiator, influencer, information gatherer, decision maker, purchaser, user) with the "},{"text":"buying centre roles","bold":true},{"text":" (users, influencers, buyers, deciders, approvers, gatekeepers)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"6 stages: problem recognition, information search (internal, external; evoked set), evaluation of alternatives, purchase decision, purchase, post-purchase evaluation. Cognitive dissonance = post-purchase doubt, cut by warranties and after-sales contact."}]},{"text":[{"text":"Involvement = importance and intensity of interest; higher risk means higher involvement. Risks: personal, social, economic."}]},{"text":[{"text":"4 types: routine response, limited, extensive (complex), impulse. Inertia = repeat buying to save effort."}]},{"text":[{"text":"3 factor categories: personal (age, life-cycle stage, occupation, income), psychological (motives, perception, learning, attitudes, personality), social (family, reference groups, social class, culture, subculture). Kotler adds cultural as a fourth."}]},{"text":[{"text":"Maslow: physiological, safety, love and belonging, esteem, self-actualisation. Perception: selective exposure, distortion, retention."}]},{"text":[{"text":"Reference groups: membership, aspiration, disassociative; influence is informational, comparative, normative. Family is the most important primary reference group."}]},{"text":[{"text":"Buying centre: users, influencers, buyers, deciders, approvers, gatekeepers. 3 buy classes: straight rebuy, modified rebuy, new task. Process stages = buy phases, starting with problem recognition."}]}]}],"theory":{"itemId":"72cecbbf-ccbc-54ba-b26e-59ad73fff229","question":[{"type":"paragraph","text":[{"text":"A Lagos bakery that has always bought flour from one miller decides to test a new flour blend and asks two other millers to quote. Name the buy class, and explain how it differs from the other two buy classes."}]}]},"practice":[{"topic":"Consumer and Organisational Buying Behaviour","named":false}]}},{"kind":"note","itemId":"40d1a9f8-f5b1-5c8c-940e-c76e047c1f38","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Marketing Mix and Product Life Cycle","body":"The meaning and importance of the marketing mix; the 4Ps (McCarthy, 1960s), the 7Ps of services and the 4Cs (1990s); product levels, classes, branding and packaging; pricing objectives, methods and strategies (skimming, penetration); distribution strategies and channels; the promotion tools; people, process, physical evidence and the features of services; the product life cycle stages, their features and strategies; market share.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"The meaning and importance of the marketing mix; the 4Ps (McCarthy, 1960s), the 7Ps of services and the 4Cs (1990s); product levels, classes, branding and packaging; pricing objectives, methods and strategies (skimming, penetration); distribution strategies and channels; the promotion tools; people, process, physical evidence and the features of services; the product life cycle stages, their features and strategies; market share."}],"lessons":[{"number":"6.1","title":"Meaning and importance of the marketing mix","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing mix (simple meaning):","bold":true},{"text":" putting the "},{"text":"right product","bold":true},{"text":", or a combination of products, in the "},{"text":"right place","bold":true},{"text":", at the "},{"text":"right time","bold":true},{"text":" and at the "},{"text":"right price","bold":true},{"text":". The difficult part is doing it well: you must know every aspect of your business plan."}]},{"text":[{"text":"Marketing mix (formal):","bold":true},{"text":" the set of "},{"text":"controlla$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 25, $study_guide$ble marketing tools","bold":true},{"text":" a firm "},{"text":"blends","bold":true},{"text":" to produce the response it wants in its "},{"text":"target market","bold":true},{"text":". It is the set of actions a firm uses to build and market its offering."}]},{"text":[{"text":"It is a programme of marketing elements designed for a specific product in response to the marketing forces (consumer behaviour, competitors, government) that affect it. The mix is "},{"text":"controllable","bold":true},{"text":"; the environment is "},{"text":"uncontrollable","bold":true},{"text":"."}]},{"text":[{"text":"Three frameworks:","bold":true}]}]},{"type":"table","header":[[{"text":"Framework"}],[{"text":"Elements"}],[{"text":"Origin"}]],"rows":[[[{"text":"4Ps","bold":true},{"text":" (marketing mix)"}],[{"text":"Product, Price, Place, Promotion"}],[{"text":"E. Jerome McCarthy","bold":true},{"text":", "},{"text":"1960s","bold":true}]],[[{"text":"7Ps","bold":true},{"text":" (services marketing mix)"}],[{"text":"4Ps + "},{"text":"People, Process, Physical evidence","bold":true}],[{"text":"Extension of the 4Ps, used mostly for services"}]],[[{"text":"4Cs","bold":true},{"text":" (customer's view)"}],[{"text":"Customer solution (wants and needs), Cost, "},{"text":"Convenience","bold":true},{"text":", Communication"}],[{"text":"Developed in the "},{"text":"1990s","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"4Ps to 4Cs:","bold":true},{"text":" product → customer solution; price → customer cost; "},{"text":"place → convenience","bold":true},{"text":"; promotion → communication."}]}]},{"type":"paragraph","text":[{"text":"8 points of importance of the marketing mix.","bold":true},{"text":" It:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Clarifies what the offering gives customers."}]},{"text":[{"text":"Helps plan a successful product offering."}]},{"text":[{"text":"Helps plan, develop and execute effective strategies."}]},{"text":[{"text":"Helps leverage strengths and avoid unnecessary costs."}]},{"text":[{"text":"Helps the firm be proactive about risks."}]},{"text":[{"text":"Shows whether the offering suits customers."}]},{"text":[{"text":"Identifies customer requirements."}]},{"text":[{"text":"Shows when and how to promote."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Purpose:","bold":true},{"text":" to combine the controllable tools to respond to the target market, "},{"text":"balancing customer value with organisational goals","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Using the mix:","bold":true},{"text":" all 7Ps "},{"text":"work together","bold":true},{"text":", and they also affect "},{"text":"segmentation, targeting and positioning","bold":true},{"text":" decisions. Never plan one element alone, and the mix is not fixed: it changes over the product's life."}]},{"text":[{"text":"Traps: \"4 Cs model\", \"4 Es\" and \"4 Ms\" are not the name of the marketing mix; the mix is the "},{"text":"4 Ps framework","bold":true},{"text":". People is "},{"text":"not","bold":true},{"text":" one of McCarthy's original 4Ps, and "},{"text":"positioning","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" one of the 7Ps. The 4Ps were created by McCarthy, not Kotler, Porter or Drucker."}]},{"text":[{"text":"Example: Indomie gets the mix right with a product children like (product), a low pack price (price), presence in every kiosk (place) and catchy TV and school campaigns (promotion)."}]}]}]},{"number":"6.2","title":"Product: levels, classes, branding and packaging","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Product:","bold":true},{"text":" anything that can be offered to a market for "},{"text":"attention, acquisition, use or consumption","bold":true},{"text":" that might satisfy a want or need. It is a "},{"text":"bundle of tangible and intangible benefits","bold":true},{"text":": a good (shoes) or a service (hotel, airline) that solves a customer need. A mix "},{"text":"always begins with a product","bold":true},{"text":" to sell."}]},{"text":[{"text":"Product decisions:","bold":true},{"text":" designing offerings that meet customer expectations: "},{"text":"features, quality, design, branding, packaging, labelling, support services","bold":true},{"text":" and planning across the product's "},{"text":"life cycle","bold":true},{"text":"."}]},{"text":[{"text":"Key questions:","bold":true},{"text":" What does the client want from the product? How, where and why does the client use it? Is it better than competitors'?"}]}]},{"type":"paragraph","text":[{"text":"3 product levels:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Core customer value (core benefit):","bold":true},{"text":" what the buyer is "},{"text":"really","bold":true},{"text":" buying, the problem solved."}]},{"text":[{"text":"Actual product:","bold":true},{"text":" "},{"text":"brand name, features, design, quality level and packaging","bold":true},{"text":"."}]},{"text":[{"text":"Augmented product:","bold":true},{"text":" extra services and benefits: "},{"text":"delivery, installation, warranty, after-sales service, credit","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"4 classes of consumer products:","bold":true}]},{"type":"table","header":[[{"text":"Class"}],[{"text":"How it is bought"}],[{"text":"Examples"}]],"rows":[[[{"text":"Convenience","bold":true}],[{"text":"Frequently, immediately, little comparison or effort"}],[{"text":"Bread, sachet water, toothpaste"}]],[[{"text":"Shopping","bold":true}],[{"text":"Less often; buyer "},{"text":"compares","bold":true},{"text":" quality, price, style"}],[{"text":"Furniture, clothes, phones"}]],[[{"text":"Specialty","bold":true}],[{"text":"Strong brand preference; buyer makes a "},{"text":"special effort","bold":true},{"text":", will not accept substitutes"}],[{"text":"A particular luxury $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 26, $study_guide$watch or car"}]],[[{"text":"Unsought","bold":true}],[{"text":"Buyer does not know of it or does not normally think of buying it until a need arises"}],[{"text":"Life insurance, funeral services, blood donation"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Industrial (business) products:","bold":true},{"text":" materials and parts, capital items, supplies and services."}]},{"text":[{"text":"Brand:","bold":true},{"text":" a name, term, sign, symbol or design (or a combination) that identifies one seller's product and differentiates it from competitors. A "},{"text":"trademark","bold":true},{"text":" is a legally protected brand. "},{"text":"Sub-branding","bold":true},{"text":" creates a separate but related brand for a new segment without diluting the parent brand."}]},{"text":[{"text":"Packaging:","bold":true},{"text":" designing and producing the container or wrapper. Functions: "},{"text":"contain and protect, inform (label), promote, give convenience","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example of levels: a trader pays ₦850,000 for a generator in Ibadan. Keeping his shop running during power cuts is the "},{"text":"core benefit","bold":true},{"text":"; the brand, the kVA rating, design and the box are the "},{"text":"actual product","bold":true},{"text":"; free delivery, installation and a two-year warranty are the "},{"text":"augmented product","bold":true},{"text":"."}]},{"text":[{"text":"Convenience products include "},{"text":"staples","bold":true},{"text":" (bread), "},{"text":"impulse","bold":true},{"text":" goods (sweets at the till) and "},{"text":"emergency","bold":true},{"text":" goods (umbrellas in a downpour)."}]},{"text":[{"text":"A collector in Abuja who travels to Lagos for the only authorised dealer of one watch brand treats it as a "},{"text":"specialty","bold":true},{"text":" product. The same watch could be a shopping product for someone comparing several brands: classification depends on "},{"text":"how the buyer buys","bold":true},{"text":"."}]},{"text":[{"text":"Product mix:","bold":true},{"text":" all the product lines a firm sells (Dangote sells cement, sugar and salt lines). Do not confuse it with the marketing mix."}]},{"text":[{"text":"Branding and packaging also count as "},{"text":"physical evidence","bold":true},{"text":" (Lesson 6.5). In Nigeria, food and drug labels carry a "},{"text":"NAFDAC","bold":true},{"text":" registration number. Tamper-proof packaging was one firm response to consumer fears and legal pressure."}]}]}]},{"number":"6.3","title":"Price: objectives, methods and strategies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Price:","bold":true},{"text":" the amount customers pay for a product. "},{"text":"Price is the only element that produces revenue","bold":true},{"text":"; the others mainly represent costs. It determines "},{"text":"profit","bold":true},{"text":", and changing it affects the whole strategy, sales and demand."}]},{"text":[{"text":"3 things price is set against:","bold":true},{"text":" "},{"text":"production cost","bold":true},{"text":", "},{"text":"competitors' price ranges","bold":true},{"text":", "},{"text":"customers' perceived value","bold":true},{"text":". Pricing must balance "},{"text":"customer perceived value and competitive positioning","bold":true},{"text":"."}]},{"text":[{"text":"Price signals quality:","bold":true},{"text":" buyers often judge a higher-priced product as better quality."}]}]},{"type":"paragraph","text":[{"text":"Pricing objectives:","bold":true},{"text":" survival; current profit maximisation; market-share leadership; product-quality leadership; target return on investment; meeting or matching competition."}]},{"type":"paragraph","text":[{"text":"Pricing methods:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cost-based (cost-plus / mark-up):","bold":true},{"text":" add a standard mark-up to unit cost."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unit cost = variable cost + (fixed cost ÷ unit sales)"}]},{"text":[{"text":"Mark-up on cost: price = unit cost × (1 + mark-up)"}]},{"text":[{"text":"Mark-up on selling price: price = unit cost ÷ (1 − desired return on sales)"}]},{"text":[{"text":"Break-even volume = fixed cost ÷ (price − variable cost)"}]}]}]},{"text":[{"text":"Value-based:","bold":true},{"text":" price set on buyers' perceived value."}]},{"text":[{"text":"Competition-based (going-rate / competitive parity):","bold":true},{"text":" price in line with competitors' prices."}]}]},{"type":"paragraph","text":[{"text":"Pricing strategies:","bold":true}]},{"type":"table","header":[[{"text":"Strategy"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Price skimming","bold":true}],[{"text":"High price at launch to earn "},{"text":"high margins on innovative products","bold":true},{"text":" in the early period, then lower step by step"}]],[[{"text":"Penetration pricing","bold":true}],[{"text":"Low entry price","bold":true},{"text":" to win a "},{"text":"large market share rapidly","bold":true}]],[[{"text":"Competitive pricing","bold":true}],[{"text":"Prices "},{"text":"in line with competitors","bold":true}]],[[{"text":"Psychological pricing","bold":true}],[{"text":"₦999 instead of ₦1,000"}]],[[{"text":"Prestige (premium) pricing","bold":true}],[{"text":"Deliberately high price to signal status"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked cost-plus example.","bold":true},{"text":" Variable cost ₦400 per unit, fixed cost ₦2,000,000, expected sales 50,000 units."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unit cost = 400 + (2,000,000 ÷ 50,000) = 400 + 40 = "},{"text":"₦440","bold":true},{"text":"."}]},{"text":[{"text":"25% mark-up on cost: 440 × 1.25 = "},{"text":"₦550","bold":true},{"text":"."}]},{"text":[{"text":"20% return on selling price: 440 ÷ (1 − 0.20$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 27, $study_guide$) = 440 ÷ 0.80 = "},{"text":"₦550","bold":true},{"text":"."}]},{"text":[{"text":"Break-even at ₦550: 2,000,000 ÷ (550 − 400) = 13,333.3, so "},{"text":"13,334 units","bold":true},{"text":" (rounded up to whole units)."}]}]}]},{"text":[{"text":"Skimming:","bold":true},{"text":" a phone launched in Lagos at ₦1,200,000 for buyers who want the newest model, then cut step by step. "},{"text":"Penetration:","bold":true},{"text":" a new mobile network entering with call rates far below established networks, to win many subscribers quickly."}]},{"text":[{"text":"Why a newcomer cannot charge very high prices:","bold":true},{"text":" the brand is only starting out, so customers do not yet "},{"text":"recognise or trust","bold":true},{"text":" it; trust comes with time. Skimming suits a genuinely innovative product with buyers willing to pay, not an unknown brand of an ordinary product."}]},{"text":[{"text":"Perceived quality:","bold":true},{"text":" a shopper who assumes a ₦28,000 perfume is better than a ₦3,500 one without trying either shows that price "},{"text":"shapes perceived quality","bold":true},{"text":". Inexperienced buyers lean on price most."}]},{"text":[{"text":"Traps: penetration is a "},{"text":"pricing","bold":true},{"text":" strategy, not a distribution strategy. Skimming does "},{"text":"not","bold":true},{"text":" aim at mass-market penetration, and cost-plus ignores demand and competition."}]}]}]},{"number":"6.4","title":"Place and promotion","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Place:","bold":true},{"text":" the "},{"text":"position and distribution","bold":true},{"text":" of the product so it is "},{"text":"accessible to the target audience","bold":true},{"text":": the right location at the right time (a shop, an online store, mail order, an easy-to-navigate website). It covers "},{"text":"supply-chain logistics and channel management","bold":true},{"text":"."}]},{"text":[{"text":"Distribution:","bold":true},{"text":" moving products from the point of production to the point of consumption. "},{"text":"Intermediaries","bold":true},{"text":" (wholesalers, retailers, agents) create "},{"text":"place, time and possession utility","bold":true},{"text":"."}]},{"text":[{"text":"Place questions:","bold":true},{"text":" Where do clients look for my product? Where do clients usually shop? Should I sell online?"}]}]},{"type":"paragraph","text":[{"text":"4 distribution strategies:","bold":true}]},{"type":"table","header":[[{"text":"Strategy"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"Intensive","bold":true}],[{"text":"As many outlets as possible"}],[{"text":"Soft drinks in every supermarket, kiosk, filling station and roadside stall"}]],[[{"text":"Selective","bold":true}],[{"text":"A few carefully chosen outlets per area"}],[{"text":"A home-appliance maker using chosen retailers in each city"}]],[[{"text":"Exclusive","bold":true}],[{"text":"One (or very few) dealers per area"}],[{"text":"A luxury car maker with one dealer in Lagos State"}]],[[{"text":"Franchising","bold":true}],[{"text":"Independent owners use the brand's name, recipes and systems for fees"}],[{"text":"Fast-food outlets in Port Harcourt and Enugu"}]]]},{"type":"paragraph","text":[{"text":"Channel levels:","bold":true},{"text":" zero-level (direct: producer → consumer); one-level (producer → retailer → consumer); two-level (producer → wholesaler → retailer → consumer); three-level (adds an agent or jobber)."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Promotion:","bold":true},{"text":" methods to win attention, "},{"text":"build awareness and persuade","bold":true},{"text":" the target audience, driving "},{"text":"brand visibility, purchase intent, sales and brand recognition","bold":true},{"text":"."}]},{"text":[{"text":"Promotion tools (promotion mix):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Advertising:","bold":true},{"text":" paid, non-personal presentation through media."}]},{"text":[{"text":"Sales promotion:","bold":true},{"text":" short-term incentives (buy two, get one free; coupons; samples)."}]},{"text":[{"text":"Personal selling","bold":true},{"text":" (sales organisation): face-to-face selling that "},{"text":"builds direct customer relationships","bold":true},{"text":"."}]},{"text":[{"text":"Public relations:","bold":true},{"text":" building goodwill and a positive image (sponsorships, press releases)."}]},{"text":[{"text":"Direct and digital marketing","bold":true},{"text":", and "},{"text":"customer service","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Promotion questions:","bold":true},{"text":" When is the best time to promote? What strategy are competitors using? Should I use social media? How can I send messages to my audience? Which channel is best for my audience?"}]},{"text":[{"text":"The promotion choice depends on "},{"text":"budget, communication goals and target market","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"MTN recharge cards and Coca-Cola use "},{"text":"intensive","bold":true},{"text":" distribution; luxury car brands use "},{"text":"exclusive","bold":true},{"text":" dealers; Jumia is an online channel (place), not a promotion tool."}]},{"text":[{"text":"A Surulere supermarket's \"buy two tins of milk, get one free\" for two weeks = "},{"text":"sales promotion","bold":true},{"text":". A beverage firm sponsoring a free health walk in Ibadan and sending a press release = "},{"text":"public relations","bold":true},{"text":"."}]},{"text":[{"text":"Traps: "},{"text":"franchising","bold":true},{"text":" is a distribution strategy, not a promotion tool; "},{"text":"penetration","bold":true},{"text":" is pricing, not distribution. \"Place\" in the mix is not the customer's home region and not the shop's physical surroundings (that is physical evidence)."}]},{"text":[{"text":"Services usually use a "},{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 28, $study_guide$:"direct channel","bold":true},{"text":" (bank, hotel, doctor) and widen reach through "},{"text":"franchising","bold":true},{"text":"."}]}]}]},{"number":"6.5","title":"People, process, physical evidence and services","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"People:","bold":true},{"text":" everyone tied to the offering: "},{"text":"customers","bold":true},{"text":" (is the target audience and demand large enough?) and "},{"text":"employees","bold":true},{"text":" who deliver it. Staff must be "},{"text":"fully trained","bold":true},{"text":" (customer service assistants, copywriters, designers, sales representatives)."}]},{"text":[{"text":"Process:","bold":true},{"text":" the systems and steps for delivering the service. Be "},{"text":"easy to do business with: efficient, helpful and timely","bold":true},{"text":". A good process "},{"text":"saves time and money","bold":true},{"text":" and keeps the "},{"text":"standard of service consistent","bold":true},{"text":", building reputation and loyalty. Remove bottlenecks; use process maps."}]},{"text":[{"text":"Physical evidence:","bold":true},{"text":" "},{"text":"everything a customer sees or hears","bold":true},{"text":" when interacting with the business: "},{"text":"branding, packaging, physical space (shop) and even the way staff and sales representatives act and dress","bold":true},{"text":". It must reflect brand values and can raise or lower sales."}]}]},{"type":"paragraph","text":[{"text":"4 characteristics of services:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Intangibility:","bold":true},{"text":" cannot be seen or touched in advance."}]},{"text":[{"text":"Inseparability:","bold":true},{"text":" produced and consumed at the same time; cannot be separated from the provider."}]},{"text":[{"text":"Heterogeneity (variability):","bold":true},{"text":" quality differs from one provider or occasion to another."}]},{"text":[{"text":"Perishability:","bold":true},{"text":" cannot be stored; unused capacity is lost forever."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Other features: "},{"text":"fluctuating (seasonal) demand","bold":true},{"text":"; prices set by "},{"text":"demand and competition","bold":true},{"text":"; a "},{"text":"direct channel","bold":true},{"text":", widened by franchising."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A hotel in Victoria Island training front-desk staff for two weeks strengthens "},{"text":"people","bold":true},{"text":". A bank branch in Ikeja cutting account opening from two days to 30 minutes improves "},{"text":"process","bold":true},{"text":". A Lekki restaurant repainting, relighting, reprinting menus and replacing its signboard changes "},{"text":"physical evidence","bold":true},{"text":"."}]},{"text":[{"text":"Trap: training staff is "},{"text":"people","bold":true},{"text":"; how staff look and dress as the customer sees them is part of "},{"text":"physical evidence","bold":true},{"text":". If asked what physical evidence includes among branding, packaging, shop space and staff dress, choose "},{"text":"all of them","bold":true},{"text":"."}]},{"text":[{"text":"Why physical evidence matters:","bold":true},{"text":" services are "},{"text":"intangible","bold":true},{"text":", so customers look for "},{"text":"visible cues","bold":true},{"text":" to judge quality (a clean banking hall, smart uniforms)."}]},{"text":[{"text":"Empty seats on a half-full Lagos-Abuja flight cannot be sold tomorrow: "},{"text":"perishability","bold":true},{"text":". Customers waiting for one particular barber in Yaba because haircuts differ: "},{"text":"variability","bold":true},{"text":". Variability is reduced by training and standards but never removed."}]}]}]},{"number":"6.6","title":"The product life cycle and market share","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Product life cycle (PLC):","bold":true},{"text":" the course of a product's "},{"text":"sales and profits over its lifetime","bold":true},{"text":". Before launch there is "},{"text":"product development","bold":true},{"text":" (no sales, rising costs). After launch: "},{"text":"Introduction → Growth → Maturity → Decline","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Introduction"}],[{"text":"Growth"}],[{"text":"Maturity"}],[{"text":"Decline"}]],"rows":[[[{"text":"Sales"}],[{"text":"Low"}],[{"text":"Rising rapidly"}],[{"text":"Peak","bold":true}],[{"text":"Declining"}]],[[{"text":"Cost per customer"}],[{"text":"Highest","bold":true}],[{"text":"Average"}],[{"text":"Low"}],[{"text":"Low"}]],[[{"text":"Profits"}],[{"text":"Low or negative"}],[{"text":"Rising"}],[{"text":"High"}],[{"text":"Declining"}]],[[{"text":"Customers"}],[{"text":"Innovators"}],[{"text":"Early adopters"}],[{"text":"Middle majority"}],[{"text":"Laggards","bold":true}]],[[{"text":"Competitors"}],[{"text":"Few"}],[{"text":"Growing number"}],[{"text":"Stable, beginning to decline"}],[{"text":"Declining"}]],[[{"text":"Objective"}],[{"text":"Awareness and trial"}],[{"text":"Maximise market share"}],[{"text":"Maximise profit, defend share"}],[{"text":"Cut spending, milk the brand"}]],[[{"text":"Price"}],[{"text":"Cost-plus (or skim or penetrate)"}],[{"text":"Price to penetrate; lower prices"}],[{"text":"Match or beat competitors"}],[{"text":"Cut price"}]],[[{"text":"Distribution"}],[{"text":"Selective"}],[{"text":"Intensive"}],[{"text":"More intensive"}],[{"text":"Selective; close unprofitable outlets"}]],[[{"text":"Advertising"}],[{"text":"Awareness among "},{"text":"early adopters and dealers","bold":true}],[{"text":"Awareness and interest in mass market"}],[{"text":"Stress brand differences and benefits","bold":true}],[{"text":"Reduce to level that keeps "},{"text":"hard-core loyals","bold":true}]],[[{"text":"Sales promotion"}],[{"text":"Heavy, to entice trial","bold":true}],[{"text":"Reduce"}],$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 29, $study_guide$[{"text":"Increase to encourage brand switching","bold":true}],[{"text":"Reduce to minimum"}]],[[{"text":"Product"}],[{"text":"Basic product"}],[{"text":"Extensions, service, warranty"}],[{"text":"Diversify brands and models"}],[{"text":"Phase out weak items","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Maturity","bold":true},{"text":" usually "},{"text":"lasts longest","bold":true},{"text":". Its strategies: "},{"text":"modify the market","bold":true},{"text":" (new users, new uses, new segments), "},{"text":"modify the product","bold":true},{"text":" (quality, features, style, variants), "},{"text":"modify the marketing mix","bold":true},{"text":"."}]},{"text":[{"text":"Decline","bold":true},{"text":" is triggered by "},{"text":"new technology or shifts in consumer preferences","bold":true},{"text":" (and competition). Options: "},{"text":"maintain","bold":true},{"text":" (reposition or revitalise, find new uses or markets), "},{"text":"harvest","bold":true},{"text":" (cut R&D and advertising, milk short-run cash), "},{"text":"drop","bold":true},{"text":" (discontinue or sell). Marketers must "},{"text":"find new ways to increase sales again","bold":true},{"text":" or reinvent the product."}]},{"text":[{"text":"Style:","bold":true},{"text":" a basic, distinctive mode of expression, lasting generations. "},{"text":"Fashion:","bold":true},{"text":" a currently accepted, popular style. "},{"text":"Fad:","bold":true},{"text":" a short period of unusually high sales driven by consumer enthusiasm and immediate popularity, then a quick fade."}]},{"text":[{"text":"Market share","bold":true},{"text":" = (firm's sales ÷ total industry sales of that product type) × 100."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Value of the PLC:","bold":true},{"text":" a dynamic tool to tailor strategy to each stage and to help forecast performance. It is not a fixed roadmap."}]},{"text":[{"text":"Spotting the stage:","bold":true},{"text":" a plantain-chip brand six months old, slow sales, few aware, almost no rivals, heavy awareness spending = "},{"text":"introduction","bold":true},{"text":". A bottled-water brand going ₦10m → ₦25m → ₦60m (up 150% then 140%) while rivals enter = "},{"text":"growth","bold":true},{"text":". A detergent ad stressing brand differences plus promotions to make rivals' customers switch = "},{"text":"maturity","bold":true},{"text":"."}]},{"text":[{"text":"A mature tea brand pushing iced tea to young non-drinkers = "},{"text":"modifying the market","bold":true},{"text":". A declining noodles brand cutting research and advertising to earn short-run cash = "},{"text":"harvesting","bold":true},{"text":"."}]},{"text":[{"text":"Introduction: high costs, low sales, low or negative profits, overcoming "},{"text":"consumer unfamiliarity","bold":true},{"text":". Growth: rising acceptance, competitors enter, so "},{"text":"differentiate","bold":true},{"text":". Maturity: slowing growth, intense competition, sustained promotion, new variants or segments."}]},{"text":[{"text":"Traps: relaunching an unchanged product does not return it to introduction; raising prices for exclusivity and aggressive expansion are not decline strategies."}]},{"text":[{"text":"Market share example:","bold":true},{"text":" industry sales of bottled water in a state are ₦800 million; one brand sells ₦120 million. Share = (120 ÷ 800) × 100 = "},{"text":"15%","bold":true},{"text":". Not 85% (the rest of the market) and not 6.67% (800 ÷ 120, upside down)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing mix = controllable tools blended for the target market: right product, place, time, price."}]},{"text":[{"text":"4Ps by McCarthy (1960s); 7Ps add people, process, physical evidence; 4Cs (1990s): place = convenience."}]},{"text":[{"text":"Product levels: core benefit, actual, augmented. Consumer products: convenience, shopping, specialty, unsought."}]},{"text":[{"text":"Price is the only revenue element and signals quality. Skimming = high launch price; penetration = low price for quick share."}]},{"text":[{"text":"Distribution: intensive, selective, exclusive, franchising. Promotion: advertising, sales promotion, personal selling, PR."}]},{"text":[{"text":"Services: intangible, inseparable, variable, perishable; physical evidence gives visible cues."}]},{"text":[{"text":"PLC: introduction, growth, maturity (peak, longest), decline (laggards; maintain, harvest, drop)."}]},{"text":[{"text":"Market share = firm's sales ÷ industry sales × 100."}]}]}],"theory":{"itemId":"e1dcb7c5-e773-5f9c-9c3d-921f683a9199","question":[{"type":"paragraph","text":[{"text":"Industry sales of packaged juice in Lagos were ₦2,500 million last year and ₦2,600 million this year. Brand A sold ₦400 million last year and ₦390 million this year. Find Brand A's market share each year, the industry growth rate, and the likely PLC stage of the category. Suggest two strategies."}]}]},"practice":[{"topic":"Marketing Mix and Product Life Cycle","named":false}]}},{"kind":"note","itemId":"7179f3be-8cc7-5b2f-a412-b9fcb926fc19","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Market Segmentation","body":"The meaning and origin of segmentation; the nature of a good segment and preference patterns; the bases (geographic, demographic, psychographic, behavioural, plus business markets) and every variable under each; the five requirements for effective segmentation; benefits and disadvantages; targeting strategies; positioning; simple segment-size and market-share sums.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"The meaning and origin of segmentation; the nature of a good segment and preference patterns; the bases (geographic, demographic, psychographic, behavioural, plus business markets) and every variable under each; the five requirements for effective segmentation; benefits and disadvantages; targeting strategies; positioning; simple segme$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 30, $study_guide$nt-size and market-share sums."}],"lessons":[{"number":"7.1","title":"Meaning, origin and the nature of a segment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market segmentation:","bold":true},{"text":" the process of dividing a broad market into smaller groups of customers who share meaningful characteristics, such as demographics, geography, psychographics or behaviour. Put another way, it is dividing the market of potential customers into smaller, more defined segments by shared characteristics such as demographics, interests, needs or location."}]},{"text":[{"text":"Market segment:","bold":true},{"text":" one of those groups. Its members have one or more things in common, so the marketer can craft one message for the whole group."}]},{"text":[{"text":"Major reason for segmenting:","bold":true},{"text":" to create a "},{"text":"custom marketing mix for each segment","bold":true},{"text":" and cater to it accordingly."}]},{"text":[{"text":"Strategic goal:","bold":true},{"text":" to meet diverse customer needs more precisely, so the firm can customise offerings for distinct groups and focus effort on solutions tailored to each group."}]},{"text":[{"text":"Origin:","bold":true},{"text":" the concept was introduced by "},{"text":"Wendell R. Smith","bold":true},{"text":" in his 1956 article \"Product Differentiation and Market Segmentation as Alternative Marketing Strategies\". Marketers have practised it since the late 1900s."}]},{"text":[{"text":"Opposite of segmentation:","bold":true},{"text":" "},{"text":"mass marketing","bold":true},{"text":" (one product, one programme, for everyone)."}]},{"text":[{"text":"Segmentation vs product differentiation:","bold":true},{"text":" segmentation focuses on the "},{"text":"market","bold":true},{"text":" (the buyers); product differentiation focuses on "},{"text":"product differences","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Nature of a good segment","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Internally homogeneous:","bold":true},{"text":" members share something the marketer can use."}]},{"text":[{"text":"Externally heterogeneous:","bold":true},{"text":" each segment differs clearly from other segments."}]},{"text":[{"text":"Members "},{"text":"respond in a similar way","bold":true},{"text":" to the marketing activities aimed at them (similar features alone are not enough)."}]}]},{"type":"paragraph","text":[{"text":"Memorise the rule: "},{"text":"a good segment is internally homogeneous and externally heterogeneous.","bold":true}]},{"type":"paragraph","text":[{"text":"Preference patterns","bold":true},{"text":" (how buyers' preferences spread out)"}]},{"type":"table","header":[[{"text":"Pattern"}],[{"text":"What it looks like"}],[{"text":"What it means"}]],"rows":[[[{"text":"Homogeneous"}],[{"text":"All buyers want roughly the same thing"}],[{"text":"Treat the whole market as one segment (e.g. table salt)"}]],[[{"text":"Diffused"}],[{"text":"Preferences scattered everywhere"}],[{"text":"In the extreme, each consumer is a separate segment"}]],[[{"text":"Clustered"}],[{"text":"Groups of buyers with similar preferences"}],[{"text":"Natural segments form (clusters)"}]]]},{"type":"paragraph","text":[{"text":"Customer-driven marketing strategy (STP), in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Segmentation:","bold":true},{"text":" divide the market."}]},{"text":[{"text":"Targeting:","bold":true},{"text":" choose which segment(s) to serve."}]},{"text":[{"text":"Positioning:","bold":true},{"text":" create a clear, distinctive place in target customers' minds (then differentiate the offer to deliver it)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Segmentation makes it easier to personalise campaigns, focus on what is necessary and group similar consumers so they can be reached cost-effectively. Today its main purpose is to get more "},{"text":"conversions","bold":true},{"text":" (sales) through personalised campaigns."}]},{"text":[{"text":"Wrong options in exams: \"treating all customers the same\", \"ignoring consumer diversity\", \"standardising marketing efforts\", \"reducing product diversity\", \"escalating costs\". These describe mass marketing or nonsense, never segmentation."}]},{"text":[{"text":"\"Concentrated preference pattern\" is "},{"text":"not","bold":true},{"text":" one of the three patterns; it is a distractor borrowed from \"concentrated marketing\". Products where tastes hardly vary (salt, sugar, petrol) show homogeneous preferences; fashion clothing, perfume and cars show scattered or clustered preferences."}]},{"text":[{"text":"Order trap: segmentation always comes first, positioning last. \"Targeting, segmentation, positioning\" is wrong."}]},{"text":[{"text":"Example:","bold":true},{"text":" Indomie does not sell one pack to everyone. It offers small single packs, bigger \"hungry man\" sizes and multipacks for families. Each pack serves a group with similar needs (internally alike) that differs from the others (externally different)."}]}]}]},{"number":"7.2","title":"Bases of segmentation, demographic and geographic","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Basis (base) of segmentation:","bold":true},{"text":" the characteristic used to split the market. The four major consumer bases: "},{"text":"geographic, demographic, psychographic, behavioural","bold":true},{"text":"."}]},{"text":[{"text":"Two ways to group bases:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Descriptive bases:","bold":true},{"text":" dimensions that simply "},{"text":"describe","bold":true},{"text":" consumers in a segment, e.g. age, income, location."}]},{"text":[{"text":"Causal bases:","bold":true},{"text":" dimensions that explain "},{"text":"why","bold":true},{"text":" customers respond to marketing mixes, e.g. benefits$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 31, $study_guide$ sought."}]}]}]},{"text":[{"text":"Segmentation by consumer characteristics","bold":true},{"text":" uses who the consumer is: geographic, demographic and psychographic variables (age, sex, income). "},{"text":"Segmentation by consumer responses","bold":true},{"text":" uses what consumers do or want: benefits, usage, occasions, loyalty (behavioural)."}]},{"text":[{"text":"Simple bases listed one by one: "},{"text":"gender, age group, income, place, occupation, usage, lifestyle","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Demographic segmentation:","bold":true},{"text":" groups people by population characteristics. Variables: "},{"text":"age, gender (sex), marital status, family size, income, religion, race, occupation, nationality","bold":true},{"text":" (also education). It is the "},{"text":"most common","bold":true},{"text":" type, the one most people think of when they hear \"market segmentation\". Its key strength: it uses "},{"text":"measurable, easily available data","bold":true},{"text":". It assumes buying behaviour is strongly influenced by demographics."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Gender:","bold":true},{"text":" simple but important; male and female needs differ (cosmetics, clothing, jewellery)."}]},{"text":[{"text":"Age group:","bold":true},{"text":" most products do not suit all ages; age targeting improves strategy and conversion."}]},{"text":[{"text":"Income:","bold":true},{"text":" decides "},{"text":"purchasing power","bold":true},{"text":" and whether to market the product as a "},{"text":"need, a want or a luxury","bold":true},{"text":". Three groups: "},{"text":"high income, mid income, low income","bold":true},{"text":" (the split varies with product, use and area)."}]},{"text":[{"text":"Occupation:","bold":true},{"text":" like income, it shapes purchases; a need for an entrepreneur may be a luxury for a civil servant."}]},{"text":[{"text":"Generational segmentation:","bold":true},{"text":" grouping by period of birth (Generation Z, millennials, Generation X, baby boomers)."}]},{"text":[{"text":"Life stage segmentation:","bold":true},{"text":" grouping by where people are in life now: finished school or not, earning or not, married or not, children (and their ages), home owner or not."}]},{"text":[{"text":"Generational and life stage segmentation are a "},{"text":"subset of demographic","bold":true},{"text":" segmentation."}]}]},{"type":"paragraph","text":[{"text":"Geographic segmentation:","bold":true},{"text":" groups people by the region where they live or work (country, state, city, neighbourhood). It is the base most sensitive to "},{"text":"regional preferences","bold":true},{"text":": use it when needs, tastes or climates differ by region. Its "},{"text":"6 variables:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Location:","bold":true},{"text":" solely where customers live or work, ignoring language or culture."}]},{"text":[{"text":"Time zone.","bold":true}]},{"text":[{"text":"Climate and season.","bold":true}]},{"text":[{"text":"Cultural preferences.","bold":true}]},{"text":[{"text":"Language","bold":true},{"text":" (including slang and colloquialisms)."}]},{"text":[{"text":"Urbanicity:","bold":true},{"text":" how urban an area is (urban, suburban, rural)."}]}]},{"type":"paragraph","text":[{"text":"Business (industrial) markets","bold":true},{"text":" are segmented by variables such as "},{"text":"industry type, company size and location","bold":true},{"text":", plus operating variables (technology, user status, customer capabilities), purchasing approaches, situational factors (urgency, order size) and personal characteristics of buyers."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Millennials with disposable income","bold":true},{"text":" = demographic (age generation plus income). "},{"text":"Coastal residents","bold":true},{"text":" = geographic."}]},{"text":[{"text":"Income example:","bold":true},{"text":" a car maker treats a Toyota Corolla as a need for mid-income buyers and a Lexus as a luxury for high-income buyers."}]},{"text":[{"text":"Occupation example:","bold":true},{"text":" a heavy-duty phone power bank may be a necessity for a self-employed trader in Onitsha who is out all day, but a luxury for a salaried civil servant who sits near a socket."}]},{"text":[{"text":"Generational example:","bold":true},{"text":" a social media app such as Snapchat markets itself to Generation Z rather than Generation X."}]},{"text":[{"text":"Life stage example:","bold":true},{"text":" two 30-year-old men grew up in the same Ibadan neighbourhood. One is married with a child; the other is single and lives with his parents. Same generation, different needs: a marketer who separates them is using life stage segmentation. Combining generation and life stage gives deeper insight."}]},{"text":[{"text":"Climate and season:","bold":true},{"text":" a clothing retailer pushes raincoats and umbrellas in Port Harcourt in the rainy season and warm wear in Jos during harmattan. Bottled water sells strongly where water is scarce and weakly where it is plentiful."}]},{"text":[{"text":"Cultural preferences:","bold":true},{"text":" drinking beer in the open is almost normal in Lagos but may be frowned upon in parts of Northern Nigeria, so a beer brand markets differently in each. Nigeria's Yoruba, Hausa and Igbo sub-cultures can be treated as distinct segments."}]},{"text":[{"text":"Urbanicity:","bold":true},{"text":" a dealer promotes small saloon cars in cities and pick-up trucks that handle rough roads and haul farm inputs in rural areas."}]},{"text":[{"text":"Place (geographic):","bold":true},{"text":" a snack brand sells a big ₦4,500 party pack in cities where teenagers buy snacks for parties and small ₦200 packs in rural areas where people spend little on snacks."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"spending habits\" and \"customer j$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 32, $study_guide$ourney stage\" are behavioural, not geographic. \"Personality\" is psychographic, not demographic."}]}]}]},{"number":"7.3","title":"Psychographic and behavioural segmentation","mustKnow":[{"type":"paragraph","text":[{"text":"Psychographic segmentation:","bold":true},{"text":" groups people by psychological traits: "},{"text":"personality, lifestyle and attitude","bold":true},{"text":" (also values, interests, opinions). It uncovers "},{"text":"intangible","bold":true},{"text":" factors and explains consumer motivations, so it is very useful for understanding "},{"text":"why","bold":true},{"text":" consumers choose certain brands. Its "},{"text":"6 variables:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Inner beliefs.","bold":true}]},{"text":[{"text":"Likes and dislikes.","bold":true}]},{"text":[{"text":"Lifestyle.","bold":true}]},{"text":[{"text":"Attitudes and values.","bold":true}]},{"text":[{"text":"Priorities and motivations.","bold":true}]},{"text":[{"text":"Personality.","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Personality:","bold":true},{"text":" the combination of characteristics forming a person's distinctive character (habits, traits, attitude, temperament): introverted, extroverted, sociable, optimistic, creative, emotional."}]},{"text":[{"text":"Lifestyle:","bold":true},{"text":" how a person lives; measured by "},{"text":"activities, interests and opinions (AIO)","bold":true},{"text":". Lifestyle also covers marital status, hobbies, religion and values (but asked on their own, religion and marital status are demographic variables)."}]},{"text":[{"text":"Social status:","bold":true},{"text":" how highly society views a person; people buy to enhance it."}]},{"text":[{"text":"Attitudes:","bold":true},{"text":" people's perceptions of the world, usually shaped by upbringing and cultural and religious background."}]}]},{"type":"paragraph","text":[{"text":"Behavioural segmentation:","bold":true},{"text":" groups people by how they behave towards the product or business: "},{"text":"usage, loyalty, purchase occasions","bold":true},{"text":", preference, choices, decision making, product knowledge. It is reported as the "},{"text":"most effective","bold":true},{"text":" method: "},{"text":"91%","bold":true},{"text":" of marketers said so (2019 Marketing Week survey). Its "},{"text":"6 variables:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Spending habits.","bold":true}]},{"text":[{"text":"Purchasing habits.","bold":true}]},{"text":[{"text":"Brand interactions.","bold":true}]},{"text":[{"text":"Customer journey stage.","bold":true}]},{"text":[{"text":"User status.","bold":true}]},{"text":[{"text":"Benefits sought.","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Purchasing habits, 4 groups:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Complex buyers:","bold":true},{"text":" do not yet know which product or brand to buy; still researching."}]},{"text":[{"text":"Variety-seeking:","bold":true},{"text":" happy with their current brand but open to trying other brands and varieties."}]},{"text":[{"text":"Dissonance-reducing:","bold":true},{"text":" happy with their current brand but think other brands could offer better."}]},{"text":[{"text":"Habitual:","bold":true},{"text":" loyal to their brand and unlikely to switch."}]}]}]},{"text":[{"text":"User status:","bold":true},{"text":" those who know or do not know the product, "},{"text":"ex-users, potential users, current users, first-time users","bold":true},{"text":"."}]},{"text":[{"text":"Usage rate:","bold":true},{"text":" "},{"text":"heavy, medium, light","bold":true},{"text":" users."}]},{"text":[{"text":"Loyalty status:","bold":true},{"text":" "},{"text":"brand loyal, brand-neutral, competitor loyal","bold":true},{"text":"."}]},{"text":[{"text":"Benefit segmentation:","bold":true},{"text":" segments formed by "},{"text":"what consumers want from the product","bold":true},{"text":" (the benefit sought)."}]},{"text":[{"text":"Other behavioural variables: occasions (when they buy or use), buyer readiness, attitude towards the product."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Personality:","bold":true},{"text":" an events company tells introverts the concert lets them choose quiet activities, and tells extroverts it is full of socialising. Same event, two personality segments."}]},{"text":[{"text":"Lifestyle:","bold":true},{"text":" an online sneaker store in Lagos runs one campaign for joggers and gym users and another for buyers who want sneakers as a fashion statement."}]},{"text":[{"text":"Social status:","bold":true},{"text":" a five-star hotel in Abuja sells luxury and quality service; a budget hotel in the same city sells affordability."}]},{"text":[{"text":"Attitudes:","bold":true},{"text":" some gym users train to avoid health problems; others train for a sense of accomplishment."}]},{"text":[{"text":"Lifestyle example:","bold":true},{"text":" a person with a lavish lifestyle sees an air conditioner in every room as a need; a conservative person in the same city sees it as a luxury."}]},{"text":[{"text":"Purchasing habits:","bold":true},{"text":" Ada is buying her first laptop, does not know which brand, and is reading reviews and asking friends: a "},{"text":"complex buyer","bold":true},{"text":". \"Impulse buyers\" is "},{"text":"not","bold":true},{"text":" one of the four groups."}]},{"text":[{"text":"User status:","bold":true},{"text":" MTN or Airtel can send ex-users a \"come back\" bonus, first-time users a welcome bundle and current users a loyalty reward."}]},{"text":[{"text":"Usage rate:","bold":true},{"text":" an athlete is a heavy user of an energy drink; a non-sporty person who buys it for the taste is a light or medium user."}]},{"text":[{"text":"Behavioural targets:","bold":true},{"text":" freque$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 33, $study_guide$nt flyers (usage), brand-loyal customers for retention campaigns (loyalty). Benefit segmentation for toothpaste: one group wants white teeth, another wants cavity protection, another wants sensitivity relief."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"values and lifestyles\" or \"attitudes, interests and opinions\" means psychographic. \"How heavily they use the product\", \"purchase frequency\" and \"loyalty\" mean behavioural. Behavioural looks at what people "},{"text":"do","bold":true},{"text":"; psychographic looks at who they "},{"text":"are inside","bold":true},{"text":"."}]}]}]},{"number":"7.4","title":"Requirements, benefits and disadvantages, and segment sums","mustKnow":[{"type":"paragraph","text":[{"text":"5 requirements for effective segmentation","bold":true},{"text":" (segments must be):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Measurable:","bold":true},{"text":" the size, purchasing power and profiles of the segment can be measured."}]},{"text":[{"text":"Accessible:","bold":true},{"text":" the segment can be effectively reached and served."}]},{"text":[{"text":"Substantial:","bold":true},{"text":" the segment is large and/or profitable enough to serve."}]},{"text":[{"text":"Differentiable:","bold":true},{"text":" segments are conceptually distinguishable and respond differently to different marketing mix elements and programmes."}]},{"text":[{"text":"Actionable:","bold":true},{"text":" effective programmes can be formulated for attracting and serving the segment."}]}]},{"type":"paragraph","text":[{"text":"\"Ability\" and \"inexpensive\" are "},{"text":"not","bold":true},{"text":" requirements."}]},{"type":"paragraph","text":[{"text":"Benefits of market segmentation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Better matching of customer needs.","bold":true}]},{"text":[{"text":"Identification of gaps in the market.","bold":true}]},{"text":[{"text":"Increased ROI","bold":true},{"text":" (less wasted spending, more repeat sales, referrals and word of mouth)."}]},{"text":[{"text":"Customer retention.","bold":true}]},{"text":[{"text":"Increased market share.","bold":true}]}]},{"type":"paragraph","text":[{"text":"Also: better allocation of resources (directing them to high-potential segments), greater customer satisfaction, better spotting of opportunities, lower costs, higher conversions, more specific planning, and reaching niche users through smaller segments."}]},{"type":"paragraph","text":[{"text":"Disadvantages (limitations):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Extensive research and development","bold":true},{"text":" is needed, which some businesses cannot afford."}]},{"text":[{"text":"Expensive process","bold":true},{"text":" in both time and money."}]}]},{"type":"paragraph","text":[{"text":"Formulas","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Segment size = Total market (buyers or units) x Segment percentage"}]},{"text":[{"text":"Market share (%) = Firm's sales / Total market sales x 100"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Failing requirements:","bold":true},{"text":" left-handed golfers in Owerri, too few to be profitable, fail "},{"text":"substantial","bold":true},{"text":". A large, profitable group that no media or channel the firm uses can reach fails "},{"text":"accessible","bold":true},{"text":". A small airline with seven attractive segments but too few staff and too little money to run seven programmes fails "},{"text":"actionable","bold":true},{"text":". Two \"segments\" that react the same way to every offer fail "},{"text":"differentiable","bold":true},{"text":"."}]},{"text":[{"text":"Gap example:","bold":true},{"text":" after segmenting the Lagos food market, a start-up finds nobody serves healthy ready-to-eat lunches for night-shift workers and launches for them: identification of gaps in the market."}]},{"text":[{"text":"Not benefits:","bold":true},{"text":" \"using one identical marketing mix for everyone\" and \"removing the need for market research\". Segmentation needs "},{"text":"more","bold":true},{"text":" research, not less."}]}]},{"type":"paragraph","text":[{"text":"Worked example 1: segment size","bold":true}]},{"type":"paragraph","text":[{"text":"A study finds 200,000 potential buyers of a new study app in a city; 35% are aged 16 to 24."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Segment size = 200,000 x 35% = 200,000 x 0.35 = "},{"text":"70,000 buyers","bold":true},{"text":"."}]},{"text":[{"text":"Trap answers: 7,000 (decimal slip), 130,000 (the other 65%)."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2: market share","bold":true}]},{"type":"paragraph","text":[{"text":"A town buys 300,000 sachet-water units in a month; one brand sells 45,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Market share = 45,000 / 300,000 x 100 = "},{"text":"15%","bold":true},{"text":". Competitors together hold 255,000 units (85%)."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3: is the segment substantial?","bold":true}]},{"type":"paragraph","text":[{"text":"Of those 70,000 young buyers, 20% are expected to pay ₦2,000 a year."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Buyers = 70,000 x 0.20 = 14,000. Revenue = 14,000 x ₦2,000 = "},{"text":"₦28,000,000","bold":true},{"text":" a year: substantial."}]},{"text":[{"text":"The golf segment: 120 buyers x ₦50,000 = "},{"text":"₦6,000,000","bold":true},{"text":", against ₦15,000,000 needed to serve them: not substantial."}]}]}]},{"number":"7.5","title":"Targeting strategies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Target market:","bold":true},{"text":" a set of buyers sharing common needs or characteristics that a company decides to serve."}]},{"text":[{"text":"Market targeting:","bold":true},{"text":" evaluating e$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 34, $study_guide$ach segment's attractiveness and selecting one or more to enter. Evaluate segments on (1) "},{"text":"size and growth","bold":true},{"text":", (2) "},{"text":"structural attractiveness","bold":true},{"text":" (competitors, substitutes, buyer and supplier power), (3) "},{"text":"company objectives and resources","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Strategy"}],[{"text":"What the firm does"}],[{"text":"Example"}]],"rows":[[[{"text":"Undifferentiated (mass)"}],[{"text":"Ignores segment differences; one offer, one programme for the whole market"}],[{"text":"A salt producer selling one product nationwide"}]],[[{"text":"Differentiated (segmented)"}],[{"text":"Targets several segments with a separate offer and programme for each"}],[{"text":"A drinks firm with a low-sugar drink, an energy drink and a malt drink, each with its own ads"}]],[[{"text":"Concentrated (niche)"}],[{"text":"Goes after a large share of one (or a few) small segments; suits limited resources"}],[{"text":"A small Lagos firm making only handmade shoes for very large feet"}]],[[{"text":"Micromarketing"}],[{"text":"Tailors products and programmes to specific individuals and local customer groups"}],[{"text":"See below"}]]]},{"type":"paragraph","text":[{"text":"Micromarketing, 2 forms:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Local marketing:","bold":true},{"text":" tailoring to cities, neighbourhoods or specific stores."}]},{"text":[{"text":"Individual (one-to-one, customised) marketing:","bold":true},{"text":" tailoring to one customer's needs and preferences."}]}]},{"type":"paragraph","text":[{"text":"Factors in choosing a strategy:","bold":true},{"text":" company resources, product variability, product life-cycle stage, market variability, competitors' strategies."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The strategies run from broad to narrow: undifferentiated, then differentiated, then concentrated, then micromarketing."}]},{"text":[{"text":"Undifferentiated","bold":true},{"text":" keeps costs low but struggles where tastes differ. It suits homogeneous products such as salt or sugar."}]},{"text":[{"text":"Differentiated","bold":true},{"text":" usually raises total sales but also costs (separate products, research, advertising). Nestlé Nigeria (Milo, Golden Morn, Maggi) and Dangote's different pack sizes of sugar and salt serve different segments."}]},{"text":[{"text":"Concentrated","bold":true},{"text":" gives deep knowledge of the niche and a strong position, but it is risky if that one segment shrinks or a big rival enters."}]},{"text":[{"text":"Local marketing:","bold":true},{"text":" a supermarket chain stocking different goods in its Lekki and Ikorodu branches. "},{"text":"Individual marketing:","bold":true},{"text":" a tailor in Abeokuta who takes each customer's measurements and sews to that one order."}]}]}]},{"number":"7.6","title":"Positioning","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Positioning:","bold":true},{"text":" arranging for a product to occupy a "},{"text":"clear, distinctive and desirable place","bold":true},{"text":" relative to competing products in the minds of target consumers."}]},{"text":[{"text":"Product position:","bold":true},{"text":" the way consumers define the product on important attributes, compared with competitors."}]},{"text":[{"text":"Differentiation:","bold":true},{"text":" actually making the offer different (product, services, channels, people, image) so the firm can deliver the position it claims."}]},{"text":[{"text":"Value proposition:","bold":true},{"text":" the full mix of benefits on which a brand is positioned."}]},{"text":[{"text":"Perceptual (positioning) map:","bold":true},{"text":" a chart of how consumers see competing brands on key buying attributes such as price and quality."}]},{"text":[{"text":"Positioning statement:","bold":true},{"text":" To (target segment and need), our (brand) is (concept) that (point of difference)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Positioning is the "},{"text":"last","bold":true},{"text":" step of STP; the marketing mix must then deliver it (product, price, place and promotion all support one position)."}]},{"text":[{"text":"Examples:","bold":true},{"text":" GTBank positions on modern, convenient banking; Dangote Cement on strength and reliability for builders; Jumia on wide choice and home delivery. Each place is fixed relative to rivals, in buyers' minds."}]},{"text":[{"text":"Trap:","bold":true},{"text":" positioning is about the "},{"text":"mind","bold":true},{"text":" of the target customer. Choosing which group to serve is targeting; splitting the market is segmentation; the 4Ps are the marketing mix."}]},{"text":[{"text":"Industry examples of STP:","bold":true},{"text":" a beauty brand ran an \"Age Defying\" range for mature adults and a \"Clearly Clean\" range for teens and young adults (age). Fast-food chains give toys with kids' meals but promise fast service and free Wi-Fi to working adults. Sports brands such as Nike and Adidas segment by the sport played."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Segmentation divides a broad market into groups with shared characteristics, so each gets its own marketing mix; opposite = mass marketing; Wendell Smith, 1956."}]},{"text":[{"text":"Good segment: internally homogeneous, externally heterogeneous; members respond alike. Preference patterns: homogeneous, diffused, clustered."}]},{"text":[{"text":"STP order: segmentation, targeting, positioning."}]},{"text":[{"text":"Demographic (most common; age, sex, income, occupation, religion; generational and life stage are subsets). Geographic: location, time zone, climate and season, cultural preferences, language, urbanicity."}]},{"text":[{"text":"Psychographic: personality, lifestyle (AIO), attitudes, values, social status. Behavi$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 35, $study_guide$oural (91% say most effective): spending and purchasing habits, brand interactions, journey stage, user status, benefits sought, usage rate, loyalty."}]},{"text":[{"text":"Descriptive bases describe; causal bases explain why. Business markets: industry type, company size, location."}]},{"text":[{"text":"Requirements: measurable, accessible, substantial, differentiable, actionable."}]},{"text":[{"text":"Benefits: needs matched, gaps found, ROI, retention, market share. Disadvantages: extensive research, expensive."}]},{"text":[{"text":"Targeting: undifferentiated, differentiated, concentrated, micromarketing (local, individual). Positioning = a clear, distinctive, desirable place in consumers' minds."}]},{"text":[{"text":"Segment size = total x %; market share = firm's sales / market sales x 100."}]}]}],"theory":{"itemId":"be825d80-15e4-575d-ba66-de4e51851e7b","question":[{"type":"paragraph","text":[{"text":"A noodle maker finds 480,000 noodle buyers in Ibadan, of whom 25% are students. It sells to 18,000 students. (a) How large is the student segment? (b) What share of that segment does the firm hold? (c) Which segmentation base is \"students\" and which targeting strategy would the firm use if it served only this group?"}]}]},"practice":[{"topic":"Market Segmentation","named":false}]}},{"kind":"note","itemId":"2d97598e-669d-59f5-9124-deefe92ce89f","sourceKey":"guide-topic:8","position":8,"payload":{"title":"Marketing System","body":"The meaning of a marketing system and a market system; the components of the marketing system; the simplest marketing system and its two flows; the simple versus the complex (modern) system and the five markets of a modern exchange economy; the actors (suppliers, intermediaries and their types, competitors, customers) and the utilities intermediaries create; marketing channels, channel levels, the contact computation, channel flows and channel functions; vertical, horizontal and multichannel systems and channel conflict; the systems view.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"The meaning of a marketing system and a market system; the components of the marketing system; the simplest marketing system and its two flows; the simple versus the complex (modern) system and the five markets of a modern exchange economy; the actors (suppliers, intermediaries and their types, competitors, customers) and the utilities intermediaries create; marketing channels, channel levels, the contact computation, channel flows and channel functions; vertical, horizontal and multichannel systems and channel conflict; the systems view."}],"lessons":[{"number":"8.1","title":"Meaning, components and the systems view","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing system:","bold":true},{"text":" an integrative set of "},{"text":"institutions, flows and activities","bold":true},{"text":" affecting the ability of an organisation to develop and maintain successful transactions with its market."}]},{"text":[{"text":"Exam-style definition:","bold":true},{"text":" a set of "},{"text":"interacting and interdependent","bold":true},{"text":" individuals and institutions (producers, suppliers, intermediaries and customers) linked together by "},{"text":"flows of goods, money and information","bold":true},{"text":". Put another way, it is the "},{"text":"network of firms, suppliers, intermediaries and customers","bold":true},{"text":" linked by these flows."}]},{"text":[{"text":"Market system:","bold":true},{"text":" the network of buyers, sellers and other actors that come together to trade in a given product or service."}]}]},{"type":"paragraph","text":[{"text":"3 groups of participants in a market system:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Direct market players:","bold":true},{"text":" producers, buyers and consumers who drive economic activity in the market."}]},{"text":[{"text":"Suppliers of supporting goods and services:","bold":true},{"text":" finance, equipment, business consulting."}]},{"text":[{"text":"Entities that influence the business environment:","bold":true},{"text":" regulatory agencies, infrastructure providers, business associations."}]}]},{"type":"paragraph","text":[{"text":"Components of the marketing system","bold":true},{"text":" (the \"integrative set of institutions, flows and activities\"):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The marketing organisation:","bold":true},{"text":" an organisation that places customers and the satisfaction of their needs and wants at the centre of its corporate thinking."}]},{"text":[{"text":"The controllable elements of the marketing mix:","bold":true},{"text":" product, price, distribution, advertising and others."}]},{"text":[{"text":"The target market.","bold":true}]},{"text":[{"text":"The facilitating institutions:","bold":true},{"text":" wholesalers, retailers, agents and others for the "},{"text":"distribution","bold":true},{"text":" function; advertising agencies and media for "},{"text":"communication","bold":true},{"text":"; marketing research for "},{"text":"marketing information","bold":true},{"text":"."}]},{"text":[{"text":"The uncontrollable environmental variables:","bold":true},{"text":" economic conditions, demographics, social and cultural values, competition, legal forces, technology, trade barriers and sources of raw materials."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Viewed as actors, the firm's marketing system is: the "},{"text":"company","bold":true},{"text":", "},{"text":"suppliers","bold":true},{"text":", "},{"text":"marketing intermediaries","bold":true},{"text":", "},{"text":"competitors","bold":true},{"text":" and "},{"text":"customers","bold":true},{"text":" (the end-user market), all operating inside the wider "},{"text":"environment","bold":true},{"text":", and linked by flows of "},{"text":"goods, money and information","bold":true},{"text":"."}]}]}],"ex$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 36, $study_guide$plainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Picture the system as rings.","bold":true},{"text":" At the centre sits the marketing organisation with its mix (product, price, distribution, sales promotion and personal selling, advertising). Around it is a ring of functions: "},{"text":"marketing information","bold":true},{"text":", "},{"text":"communication","bold":true},{"text":", "},{"text":"distribution","bold":true},{"text":", and social-cultural value. The outer ring is the environment: physical, legal environment and competition, the economy and the international environment."}]},{"text":[{"text":"The systems idea:","bold":true},{"text":" the parts are "},{"text":"interdependent","bold":true},{"text":", so a change in one part affects the others. If a supplier of wheat flour raises its price, the noodle maker's costs rise, the wholesaler's margin is squeezed, and the shop price paid by the student goes up. The system is not fixed; it changes over time. No participant operates in isolation, and the firm cannot ignore suppliers or intermediaries."}]},{"text":[{"text":"Glaser's view:","bold":true},{"text":" the marketing system covers a narrow, limited range of organisational activities; it is only a "},{"text":"sub-system","bold":true},{"text":" of a larger organisation and is joined to other organisational sub-systems (production, finance, personnel) and to the environment."}]},{"text":[{"text":"The effectiveness of a firm's marketing activities "},{"text":"increases substantially","bold":true},{"text":" through proper "},{"text":"co-ordination","bold":true},{"text":" of the different parts to form a system."}]},{"text":[{"text":"Marketing systems of developing countries (LDCs):","bold":true},{"text":" one view (Sorenson; Bhandari and Vora) is that they are "},{"text":"resilient, adaptive","bold":true},{"text":" to economic conditions and fairly "},{"text":"low-cost","bold":true},{"text":". The opposing view (Dholakia) is that they have been generally "},{"text":"incapable of major innovations","bold":true},{"text":" in products, customer services, marketing methods, communications media or research techniques, and have not produced market-expansion strategies at home or abroad. So the typical LDC marketing system merely performs a "},{"text":"system maintenance function","bold":true},{"text":": it can neither spur rapid economic development nor generate products that benefit the mass of the population."}]},{"text":[{"text":"Traps:","bold":true},{"text":" \"the uncontrollable forces outside the firm\" describes the "},{"text":"environment","bold":true},{"text":", not the marketing system. \"The controllable variables blended to satisfy the target market\" is the "},{"text":"marketing mix","bold":true},{"text":". \"Dividing a market into distinct groups\" is "},{"text":"segmentation","bold":true},{"text":". A firm's internal accounting depreciation method is "},{"text":"not","bold":true},{"text":" a component of its marketing system."}]},{"text":[{"text":"In the evolution of marketing, the "},{"text":"stage of marketing system","bold":true},{"text":" came after barter: people tired of travelling to different places to exchange goods, so they began to use a particular place for exchange."}]}]}]},{"number":"8.2","title":"Simple and complex (modern) marketing systems","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The simplest marketing system","bold":true},{"text":" has "},{"text":"two interacting elements:","bold":true},{"text":" the "},{"text":"marketing organisation","bold":true},{"text":" and its "},{"text":"target market","bold":true},{"text":". They are connected by "},{"text":"two sets of flows:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Product and payment flow:","bold":true},{"text":" the company distributes a product or service to customers in exchange for some kind of payment."}]},{"text":[{"text":"Information flow:","bold":true},{"text":" the company communicates with its market (sales force, advertising); the market returns "},{"text":"informational feedback","bold":true},{"text":" to the firm."}]}]}]}]},{"type":"table","header":[[{"text":"Flow"}],[{"text":"Direction"}]],"rows":[[[{"text":"Goods/services"}],[{"text":"Seller to buyer (market)"}]],[[{"text":"Communication"}],[{"text":"Seller to buyer (market)"}]],[[{"text":"Money (payment)"}],[{"text":"Buyer to seller"}]],[[{"text":"Information (feedback)"}],[{"text":"Buyer to seller"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"So "},{"text":"from seller to buyer: goods/services and communication","bold":true},{"text":". "},{"text":"From buyer to seller: money and information.","bold":true},{"text":" Information therefore flows in "},{"text":"both directions","bold":true},{"text":"."}]},{"text":[{"text":"Complex (modern) marketing system:","bold":true},{"text":" links "},{"text":"many markets","bold":true},{"text":" through flows of resources, goods, money, taxes and services, rather than just one seller and its buyers."}]}]},{"type":"paragraph","text":[{"text":"5 markets in a modern exchange economy:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Resource markets:","bold":true},{"text":" raw materials, labour, money."}]},{"text":[{"text":"Manufacturer markets:","bold":true},{"text":" producers buy resources and turn them into goods and services."}]},{"text":[{"text":"Intermediary markets:","bold":true},{"text":" buy from manufacturers and sell to consumers."}]},{"text":[{"text":"Consumer markets:","bold":true},{"text":" households sell their labour for money, then spend it on goods and services."}]},{"text":[{"text":"Government markets:","bold":true},{"text":" buy goods from resource, manufacturer and intermediary markets and pay them; "},{"text":"collect taxes","bold":true},{"text":" from these markets and from consumers; and "},{"text":"provide public services","bold":true}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 37, $study_guide$,{"text":" in return."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Simple system example:","bold":true},{"text":" a pepper seller at a village market in Ogun State sells her own produce straight to shoppers. Goods go from her to them; they pay her cash and tell her which peppers they prefer (information feedback). One seller, her buyers, two sets of flows: a "},{"text":"simple marketing system","bold":true},{"text":"."}]},{"text":[{"text":"Complex system example:","bold":true},{"text":" a Dangote factory buys gypsum, labour and bank loans in resource markets; it sells cement to distributors (intermediary market), who sell to builders and households (consumer market). Government buys cement for roads, collects companies income tax and VAT, and provides public services such as roads and security. The workers' wages go back into consumer spending. Every market depends on the others."}]},{"text":[{"text":"Traps:","bold":true},{"text":" the government is "},{"text":"inside","bold":true},{"text":" the modern system (it buys, taxes and provides services); it is not outside it and it is not just a retailer. The complex system does "},{"text":"not","bold":true},{"text":" consist only of direct sales, and it still has information flows. \"Marketing mix market\" is "},{"text":"not","bold":true},{"text":" one of the five markets."}]},{"text":[{"text":"Do not mix up \"simple marketing system\" with the channel arrangements in Lesson 8.5 (vertical, horizontal, multichannel). A single seller dealing directly with her buyers is a simple system, not a vertical or horizontal one."}]}]}]},{"number":"8.3","title":"The actors in the marketing system","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Supply side","bold":true},{"text":" of the micro environment (and of the marketing system): "},{"text":"suppliers, marketing intermediaries and competitors","bold":true},{"text":". "},{"text":"Demand side:","bold":true},{"text":" "},{"text":"customers","bold":true},{"text":"."}]},{"text":[{"text":"Suppliers:","bold":true},{"text":" firms and individuals that provide the raw materials and other resources a company needs to produce its goods and services. The price of raw materials shapes the final price, so suppliers can affect profit; firms monitor them for shortages and price changes."}]},{"text":[{"text":"Marketing intermediaries:","bold":true},{"text":" independent businesses that help a company "},{"text":"link with its customers","bold":true},{"text":" by "},{"text":"promoting, selling and distributing","bold":true},{"text":" its products; they perform the activities needed to move products from manufacturers to ultimate consumers (wholesalers, retailers, agents, distributors). They are part of the firm's distribution channels."}]}]},{"type":"paragraph","text":[{"text":"4 types of marketing intermediaries:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Resellers:","bold":true},{"text":" buy the products and sell them to customers (wholesalers, retailers)."}]},{"text":[{"text":"Distribution centres:","bold":true},{"text":" help the firm "},{"text":"store","bold":true},{"text":" goods (a warehouse)."}]},{"text":[{"text":"Marketing agencies:","bold":true},{"text":" promote products by making customers aware of their benefits (an advertising agency)."}]},{"text":[{"text":"Financial intermediaries:","bold":true},{"text":" finance business transactions (banks, credit organisations, insurance organisations)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Competitors:","bold":true},{"text":" organisations offering similar products and trying to win market share with different strategies; competition pushes a firm to "},{"text":"differentiate","bold":true},{"text":" its product."}]},{"text":[{"text":"Customers:","bold":true},{"text":" buy the product; customer satisfaction is the firm's main goal. "},{"text":"5 customer markets:","bold":true},{"text":" consumer, industrial (business), reseller, government and non-profit, international."}]}]},{"type":"paragraph","text":[{"text":"5 utilities intermediaries create:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Place:","bold":true},{"text":" stocking products where customers are located."}]},{"text":[{"text":"Time:","bold":true},{"text":" opening long hours so customers buy when convenient."}]},{"text":[{"text":"Quantity:","bold":true},{"text":" offering amounts customers can afford to buy."}]},{"text":[{"text":"Assortment:","bold":true},{"text":" gathering many products in one place for one shopping trip."}]},{"text":[{"text":"Possession:","bold":true},{"text":" transferring the product to the customer through a successful transaction."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Applications:","bold":true},{"text":" a warehouse operator near the Lagos-Ibadan expressway storing a drinks maker's stock is a "},{"text":"distribution centre","bold":true},{"text":". An advertising agency running a radio campaign for a new detergent is a "},{"text":"marketing agency","bold":true},{"text":". GTBank lending to a distributor is a "},{"text":"financial intermediary","bold":true},{"text":". A Shoprite branch buying and reselling is a "},{"text":"reseller","bold":true},{"text":"."}]},{"text":[{"text":"Two noodle brands (say Indomie and a rival) chasing the same students with different packs and flavours are each other's "},{"text":"competitors","bold":true},{"text":", not suppliers or resellers."}]},{"text":[{"text":"Intratype competition:","bold":true},{"text":" between firms in the same basic activity (Nigerian Bottling Company versus Seven Up Bottling Company). "},{"text":"Intertype competition:","bold":true},{"text":" between different types of organisations (finance houses competing with banks for savers)."}]},{"text":[{"text":"\"Right place, right time, in a form they can own\" points to "},{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 38, $study_guide$"place, time and possession utility","bold":true},{"text":". "},{"text":"Form utility","bold":true},{"text":" is created by production, not by intermediaries."}]},{"text":[{"text":"Distribution channels change slowly but constantly, like the "},{"text":"hour hand of a watch","bold":true},{"text":": each movement is too small to see, yet the change over years can be massive."}]}]}]},{"number":"8.4","title":"Marketing channels, levels, flows and functions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing (distribution) channel:","bold":true},{"text":" a set of "},{"text":"interdependent organisations","bold":true},{"text":" that help make a product or service available for use or consumption by the consumer or business user."}]}]},{"type":"paragraph","text":[{"text":"Channel levels","bold":true},{"text":" (count the "},{"text":"intermediaries","bold":true},{"text":" only):"}]},{"type":"table","header":[[{"text":"Level"}],[{"text":"Structure"}]],"rows":[[[{"text":"Zero-level (direct)"}],[{"text":"Producer to consumer"}]],[[{"text":"One-level"}],[{"text":"Producer to retailer to consumer"}]],[[{"text":"Two-level"}],[{"text":"Producer to wholesaler to retailer to consumer"}]],[[{"text":"Three-level"}],[{"text":"Producer to wholesaler to jobber (sub-wholesaler) to retailer to consumer"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Contact formula","bold":true},{"text":" (each intermediary cuts the number of transactions):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct contacts = number of producers × number of buyers"}]},{"text":[{"text":"Contacts through one intermediary = number of producers + number of buyers"}]},{"text":[{"text":"Contacts saved = (producers × buyers) − (producers + buyers)"}]}]}]}]},{"type":"paragraph","text":[{"text":"Channel flows:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physical flow","bold":true},{"text":" of goods: forward, producer to consumer."}]},{"text":[{"text":"Title (ownership) flow:","bold":true},{"text":" forward."}]},{"text":[{"text":"Promotion flow:","bold":true},{"text":" forward."}]},{"text":[{"text":"Payment flow:","bold":true},{"text":" backward, consumer to producer."}]},{"text":[{"text":"Information flow:","bold":true},{"text":" both directions."}]}]},{"type":"paragraph","text":[{"text":"8 channel functions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Information:","bold":true},{"text":" gathering and spreading research and intelligence about the market."}]},{"text":[{"text":"Promotion:","bold":true},{"text":" developing and spreading persuasive communication about an offer."}]},{"text":[{"text":"Contact:","bold":true},{"text":" finding and communicating with prospective buyers."}]},{"text":[{"text":"Matching:","bold":true},{"text":" shaping and fitting the offer to the buyer's needs (manufacturing, grading, assembling, packaging)."}]},{"text":[{"text":"Negotiation:","bold":true},{"text":" agreeing on price and other terms so ownership can be transferred."}]},{"text":[{"text":"Physical distribution:","bold":true},{"text":" transporting and storing goods."}]},{"text":[{"text":"Financing:","bold":true},{"text":" acquiring and using funds to cover the costs of channel work."}]},{"text":[{"text":"Risk taking:","bold":true},{"text":" bearing the risks of carrying out channel work."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Levels:","bold":true},{"text":" a Kano farmer selling yoghurt at his farm gate is "},{"text":"zero-level (direct)","bold":true},{"text":". A soap maker selling to distributors, who sell to neighbourhood shops, who sell to households, has "},{"text":"two","bold":true},{"text":" intermediaries, so it is a "},{"text":"two-level","bold":true},{"text":" channel. Count only the middlemen, never the producer or the consumer."}]},{"text":[{"text":"Worked example 1:","bold":true},{"text":" 4 textile producers, 5 clothing shops."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct: 4 × 5 = "},{"text":"20 contacts","bold":true},{"text":"."}]},{"text":[{"text":"Through one wholesaler: 4 + 5 = "},{"text":"9 contacts","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Worked example 2:","bold":true},{"text":" 6 pharmaceutical producers, 8 pharmacies."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct: 6 × 8 = 48. Through one distributor: 6 + 8 = 14."}]},{"text":[{"text":"Fall = 48 − 14 = "},{"text":"34 contacts","bold":true},{"text":". (Options of 48 or 14 are the traps: the question asks for the fall.)"}]}]}]},{"text":[{"text":"Worked example 3 (cost):","bold":true},{"text":" 5 producers, 12 retailers, each contact costs ₦2,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Direct: 5 × 12 = 60 contacts; 60 × ₦2,000 = ₦120,000."}]},{"text":[{"text":"Through one wholesaler: 5 + 12 = 17 contacts; 17 × ₦2,000 = ₦34,000."}]},{"text":[{"text":"Saving = ₦120,000 − ₦34,000 = "},{"text":"₦86,000","bold":true},{"text":" (43 fewer contacts)."}]}]}]},{"text":[{"text":"Function applications:","bold":true},{"text":" a Lagos wholesaler that buys 5,000 cartons of tomato paste in advance and accepts losses if prices fall or stock expires is performing "},{"text":"risk taking","bold":true},{"text":". Grading and packaging rice to suit buyers is "},{"text":"matching","bold":true},{"text":". A distributor giving a retailer 30 days' credit is "},{"text":"financing","bold":true},{"text":". Setting the national interest rate is "},{"text":"not","bold":true},{"text":" a channel function; that is the Central Bank of Nigeria's job."}]},{"text":[{"text":"Information, promotion, contact, matching and negotiation help "},{"text":"complete transactions","bold":true},{"text":"; physical distribution, financing and risk taking help "},{"text":"fulfil","bold":true},{"text":" them."}]}]}]},{"number":"8.5","title":"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 39, $study_guide$Organising the channel: conventional, vertical, horizontal and multichannel systems","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Conventional distribution channel:","bold":true},{"text":" an independent producer, wholesaler(s) and retailer(s), each a separate business seeking to maximise its own profit, even at the expense of the whole system; no member has much control over the others."}]},{"text":[{"text":"Vertical marketing system (VMS):","bold":true},{"text":" producers, wholesalers and retailers acting as a "},{"text":"unified system","bold":true},{"text":". One member "},{"text":"owns","bold":true},{"text":" the others, has "},{"text":"contracts","bold":true},{"text":" with them, or has so much "},{"text":"power","bold":true},{"text":" that they must cooperate."}]}]},{"type":"paragraph","text":[{"text":"3 types of VMS:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Corporate VMS:","bold":true},{"text":" successive stages of production and distribution under "},{"text":"single ownership","bold":true},{"text":"."}]},{"text":[{"text":"Contractual VMS:","bold":true},{"text":" independent firms at different levels joined by "},{"text":"contracts","bold":true},{"text":"; the "},{"text":"franchise","bold":true},{"text":" organisation is the most common form (also wholesaler-sponsored voluntary chains and retailer cooperatives)."}]},{"text":[{"text":"Administered VMS:","bold":true},{"text":" leadership comes from the "},{"text":"size and power","bold":true},{"text":" of one dominant member, not from ownership or contracts."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Horizontal marketing system:","bold":true},{"text":" two or more companies "},{"text":"at the same channel level","bold":true},{"text":" join together to follow a new marketing opportunity."}]},{"text":[{"text":"Multichannel (hybrid) distribution system:","bold":true},{"text":" one firm sets up "},{"text":"two or more channels","bold":true},{"text":" to reach one or more customer segments."}]},{"text":[{"text":"Channel conflict:","bold":true},{"text":" disagreement among channel members over goals, roles and rewards."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Vertical conflict:","bold":true},{"text":" between "},{"text":"different levels","bold":true},{"text":" of the same channel (manufacturer versus its own retailers)."}]},{"text":[{"text":"Horizontal conflict:","bold":true},{"text":" between firms "},{"text":"at the same level","bold":true},{"text":" (one dealer versus another dealer of the same brand)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A food company that owns its own flour mills, delivery trucks and retail outlets is a "},{"text":"corporate VMS","bold":true},{"text":". A manufacturer tied to its dealers by franchise agreements, without owning them, is a "},{"text":"contractual VMS","bold":true},{"text":". A giant brand whose size lets it dictate shelf space and promotions to independent retailers is running an "},{"text":"administered VMS","bold":true},{"text":"."}]},{"text":[{"text":"A bank placing kiosks or ATMs inside a supermarket chain's stores is a "},{"text":"horizontal marketing system","bold":true},{"text":": the two firms sit at the same level and combine resources; neither owns the other."}]},{"text":[{"text":"A phone-accessories brand selling through its own website, Computer Village traders and supermarkets at once is a "},{"text":"multichannel (hybrid)","bold":true},{"text":" system. Many Nigerian brands add Jumia as an online channel alongside shops."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a fight between a manufacturer and its own retailers over prices and margins is "},{"text":"vertical","bold":true},{"text":" conflict (different levels), even though \"horizontal\" sounds right to some students. Two retailers undercutting each other is horizontal conflict."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"ownership\" points to corporate, \"contract or franchise\" to contractual, \"power\" to administered."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing system = interacting, interdependent producers, suppliers, intermediaries and customers linked by flows of goods, money and information."}]},{"text":[{"text":"Components: marketing organisation, controllable mix, target market, facilitating institutions, uncontrollable environment."}]},{"text":[{"text":"Simplest system = marketing organisation + target market; goods and communication go to the market, money and information come back."}]},{"text":[{"text":"Modern exchange economy: resource, manufacturer, intermediary, consumer and government markets; government buys, taxes and provides services."}]},{"text":[{"text":"Supply side = suppliers, intermediaries, competitors; demand side = customers. 4 intermediaries: resellers, distribution centres, marketing agencies, financial intermediaries."}]},{"text":[{"text":"Intermediaries create place, time, quantity, assortment and possession utility."}]},{"text":[{"text":"Channel levels count middlemen: zero, one, two, three. Contacts: direct = P × B; via one intermediary = P + B."}]},{"text":[{"text":"Goods and title flow forward, payment backward, information both ways. 8 functions: information, promotion, contact, matching, negotiation, physical distribution, financing, risk taking."}]},{"text":[{"text":"VMS: corporate (ownership), contractual (franchise), administered (power). Horizontal = same level. Multichannel = several channels. Vertical conflict = different levels."}]}]}],"theory":{"itemId":"b054ce88-2258-5fe6-ad23-e532ea5087ed","question":[{"type":"paragraph","text":[{"text":"Three paint manufacturers sell to ten hardware shops. Each sales contact costs ₦1,500. How much does the industry save if all trade passes through one wholesaler?"}]}]},"practice":[{"topic":"Marketing System","named":false}]}},$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 40, $study_guide${"kind":"note","itemId":"27c24510-6889-52b2-af78-b34d9dd569d9","sourceKey":"guide-topic:9","position":9,"payload":{"title":"Market Measurement and Forecasting","body":"What market measurement and forecasting are and why firms do them; the levels of a market; market demand, market minimum, market potential, company demand, sales forecast, quota and budget; market share, relative share and penetration; estimating current demand (n x q x p, market build-up, chain ratio, multiple-factor index); the forecasting methods; time series with moving averages and trend lines, all with computations.","noteType":"guide_topic","number":9,"mustKnow":[{"text":"What market measurement and forecasting are and why firms do them; the levels of a market; market demand, market minimum, market potential, company demand, sales forecast, quota and budget; market share, relative share and penetration; estimating current demand (n x q x p, market build-up, chain ratio, multiple-factor index); the forecasting methods; time series with moving averages and trend lines, all with computations."}],"lessons":[{"number":"9.1","title":"Meaning, importance and managing measurement","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market measurement:","bold":true},{"text":" helps management understand the market and sales potential for a "},{"text":"specific area, time period, product and segment","bold":true},{"text":". "},{"text":"\"Ordinal analytics\"","bold":true},{"text":" studies market share, size and growth by customer segment and product."}]},{"text":[{"text":"Forecasting:","bold":true},{"text":" giving managers reliable, early predictive information on emerging trends and \"what if\" scenarios so they can prepare and react. It uses business requirements, industry challenges, macroeconomic factors and statistical/econometric techniques, and is "},{"text":"re-run as new data arrive","bold":true},{"text":"."}]},{"text":[{"text":"Importance:","bold":true},{"text":" the main aim is to "},{"text":"support marketing decisions","bold":true},{"text":". Decisions are only as good as their information, so measurement makes decisions more "},{"text":"objective and scientific","bold":true},{"text":", reducing risk and guesswork. For minor, low-risk decisions it may not be worth it: weigh the decision's importance and risk against the "},{"text":"cost and time","bold":true},{"text":" of gathering information."}]},{"text":[{"text":"Managing measurement and forecasting","bold":true},{"text":" = planning, implementing and controlling these activities systematically. Steps:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Describe the problem and information needs","bold":true},{"text":" (gathering information is costly, so a clear problem definition decides what data is relevant)."}]},{"text":[{"text":"Gather relevant information","bold":true},{"text":" (dual purpose: supplies data for the problem and guides the choice of method)."}]},{"text":[{"text":"Select the methods","bold":true},{"text":" of measurement and forecasting (start by checking there is enough data of the right quality, then match information needs to what each method can do)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"5 factors in choosing a method:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Nature and availability of data","bold":true},{"text":" (enough suitable data? what pattern: "},{"text":"trends, seasonal fluctuations, conjuncture patterns","bold":true},{"text":"?)"}]},{"text":[{"text":"Accuracy required","bold":true}]},{"text":[{"text":"Costs","bold":true}]},{"text":[{"text":"Time","bold":true}]},{"text":[{"text":"Application","bold":true},{"text":" (results must be usable and understandable by decision makers)"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Think of Dangote Cement deciding whether to build a new plant in the north. A wrong demand estimate costs billions, so careful measurement pays. Choosing between two jingle colours does not justify an expensive study."}]},{"text":[{"text":"More reliable methods usually cost more time and money; a perfect answer that arrives after the decision is useless."}]}]}]},{"number":"9.2","title":"Levels of the market and key demand concepts","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market:","bold":true},{"text":" the set of all actual and potential buyers of a product."}]}]},{"type":"table","header":[[{"text":"Level"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Potential market"}],[{"text":"consumers who profess a sufficient level of "},{"text":"interest","bold":true},{"text":" in an offer"}]],[[{"text":"Available market"}],[{"text":"consumers with "},{"text":"interest, income and access","bold":true},{"text":" to the offer"}]],[[{"text":"Qualified available market"}],[{"text":"available market who also "},{"text":"qualify","bold":true},{"text":" (e.g. legal age)"}]],[[{"text":"Target (served) market"}],[{"text":"the part of the qualified available market the company "},{"text":"decides to pursue","bold":true}]],[[{"text":"Penetrated market"}],[{"text":"consumers who are "},{"text":"already buying","bold":true},{"text":" the product"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Market demand:","bold":true},{"text":" the "},{"text":"total volume","bold":true},{"text":" of a product that would be "},{"text":"bought","bold":true},{"text":" by a defined "},{"text":"customer group","bold":true},{"text":", in a defined "},{"text":"geographical area","bold":true},{"text":", in a defined "},{"text":"time period","bold":true},{"text":", in a defined "},{"text":"marketing environment","bold":true},{"text":", under a defined "},{"text":"marketing programme","bold":true},{"text":" (8 elements: product, total volume, bought, customer group, area, time, environment, programme)."}]},{"text":[{"text":"Market demand is "},{"text":"not a fixed number"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 41, $study_guide$,"bold":true},{"text":" but a function of conditions and industry marketing spending."}]},{"text":[{"text":"Market minimum:","bold":true},{"text":" sales that would occur "},{"text":"without any marketing expenditure","bold":true},{"text":" to stimulate demand."}]},{"text":[{"text":"Market potential:","bold":true},{"text":" the "},{"text":"limit approached by market demand as industry marketing expenditure approaches infinity","bold":true},{"text":", for a given marketing environment. Also: the maximum possible demand for a "},{"text":"product type","bold":true},{"text":" in a whole market, for a given area, period and segment."}]},{"text":[{"text":"3 aspects in defining market potential:","bold":true},{"text":" (1) defined market environment, (2) marketing expenditure by the industry, (3) market demand."}]},{"text":[{"text":"Primary demand:","bold":true},{"text":" demand for the "},{"text":"product class","bold":true},{"text":" as a whole (e.g. bottled water in general). "},{"text":"Selective (brand) demand:","bold":true},{"text":" demand for "},{"text":"one brand","bold":true},{"text":" (e.g. Eva water)."}]},{"text":[{"text":"Company demand:","bold":true},{"text":" the company's "},{"text":"estimated share of market demand","bold":true},{"text":" at alternative levels of its marketing effort in a given period. Formula: Company demand = market share x total market demand."}]},{"text":[{"text":"Company sales forecast:","bold":true},{"text":" the "},{"text":"expected","bold":true},{"text":" level of company sales based on a "},{"text":"chosen marketing plan","bold":true},{"text":" and an "},{"text":"assumed marketing environment","bold":true},{"text":"."}]},{"text":[{"text":"Company sales potential (sales potential):","bold":true},{"text":" the "},{"text":"limit","bold":true},{"text":" approached by company demand as its marketing effort increases "},{"text":"relative to competitors","bold":true},{"text":"; the maximum demand for "},{"text":"one firm's brand","bold":true},{"text":", not the product type."}]},{"text":[{"text":"Sales quota:","bold":true},{"text":" a sales "},{"text":"goal","bold":true},{"text":" set for a product line, division or salesperson; usually set "},{"text":"slightly above","bold":true},{"text":" estimated sales to stretch effort."}]},{"text":[{"text":"Sales budget:","bold":true},{"text":" a "},{"text":"conservative","bold":true},{"text":" estimate of expected sales, used for purchasing, production and cash-flow decisions; usually set "},{"text":"slightly below","bold":true},{"text":" the forecast."}]},{"text":[{"text":"Potential market share:","bold":true},{"text":" the relation between market potential and sales potential; what part of the potential market the firm expects to win."}]},{"text":[{"text":"Effective demand:","bold":true},{"text":" "},{"text":"actual sales","bold":true},{"text":" of a product type in a given area, period and segment."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Potential versus forecast (favourite trap):","bold":true},{"text":" sales potential is what the firm "},{"text":"could","bold":true},{"text":" reach if it pushed effort to the limit; the forecast is what it "},{"text":"expects","bold":true},{"text":" under the plan it has "},{"text":"actually chosen","bold":true},{"text":". They are not the same; potential is normally the higher figure."}]},{"text":[{"text":"Company sales potential equals market potential only if the company took "},{"text":"100%","bold":true},{"text":" of the market, which almost never happens."}]},{"text":[{"text":"Expansible market:","bold":true},{"text":" total size changes a lot with industry marketing spend (e.g. a new snack category). "},{"text":"Non-expansible:","bold":true},{"text":" spend barely changes it (e.g. salt); the gap between market minimum and market potential is small."}]},{"text":[{"text":"A \"Drink more water\" campaign from a water producers' association builds "},{"text":"primary","bold":true},{"text":" demand; \"Choose Nestlé Pure Life\" builds "},{"text":"selective","bold":true},{"text":" demand."}]},{"text":[{"text":"The forecast does "},{"text":"not","bold":true},{"text":" decide marketing spend; the plan comes first, and the forecast follows from it."}]},{"text":[{"text":"All these measures can refer to the "},{"text":"present or the future","bold":true},{"text":". Comparing them shows how well an offering does against rivals, the total market and market potential."}]}]}]},{"number":"9.3","title":"Estimating current demand and market share","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Total market potential:","bold":true},{"text":" Q = n x q x p, where n = number of buyers, q = quantity bought by an average buyer per period, p = average price per unit."}]},{"text":[{"text":"Area market potential","bold":true},{"text":" (for a city, state or region), 2 main methods:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Market-buildup method:","bold":true},{"text":" identify "},{"text":"all potential buyers","bold":true},{"text":" in each market (mainly business buyers, e.g. every bakery in a state) and estimate their potential purchases, then "},{"text":"add up","bold":true},{"text":"."}]},{"text":[{"text":"Multiple-factor index method","bold":true},{"text":" (mainly consumer markets): weight several factors. The best known is the "},{"text":"buying power index (BPI)","bold":true},{"text":": BPI = 0.5(area % of national disposable income) + 0.3(area % of national retail sales) + 0.2(area % of national population). Area potential = BPI% x national potential."}]}]}]},{"text":[{"text":"Chain-ratio method:","bold":true},{"text":" start with a "},{"text":"base number","bold":true},{"text":" (e.g. population) and multiply by a "},{"text":"series of percentages","bold":true},{"text":" that narrow it to likely buyers (then by usage per buyer if needed)."}]},{"text":[{"text":"Market share","bold":true},{"te$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 42, $study_guide$xt":" = (company sales / total market sales, including the company) x 100%."}]},{"text":[{"text":"Relative market share","bold":true},{"text":" = company's market share / largest competitor's share."}]},{"text":[{"text":"Market penetration index","bold":true},{"text":" = (current market demand / market potential) x 100%."}]},{"text":[{"text":"Sales forecast","bold":true},{"text":" = forecast market demand x expected market share."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (n x q x p).","bold":true},{"text":" 500,000 buyers each buy 6 tins a year at ₦800. Q = 500,000 x 6 x ₦800 = "},{"text":"₦2,400,000,000","bold":true},{"text":" a year."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (weekly data).","bold":true},{"text":" 20,000 households buy 2 tins of milk a week at ₦1,500. Weekly = 20,000 x 2 x ₦1,500 = ₦60,000,000. Annual (52 weeks) = "},{"text":"₦3,120,000,000","bold":true},{"text":". Trap: forgetting to multiply by 52 (or by 12 for monthly data)."}]},{"type":"paragraph","text":[{"text":"Worked example 3 (market build-up).","bold":true},{"text":" A drinks distributor finds 250 restaurants in a state, each buying 30 crates a month at ₦5,000. Monthly = 250 x 30 x ₦5,000 = ₦37,500,000. Annual = x 12 = "},{"text":"₦450,000,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 4 (chain ratio).","bold":true},{"text":" A city has 2,000,000 people; 55% are adults; 30% of adults drink yoghurt; each drinks 24 cups a year. 2,000,000 x 0.55 = 1,100,000 adults; x 0.30 = 330,000 drinkers; x 24 = "},{"text":"7,920,000 cups","bold":true},{"text":" a year."}]},{"type":"paragraph","text":[{"text":"Worked example 5 (BPI).","bold":true},{"text":" A state has 6% of national income, 4% of retail sales, 5% of population. BPI = 0.5(6) + 0.3(4) + 0.2(5) = 3 + 1.2 + 1 = 5.2%. If national potential is ₦200 billion, state potential = 0.052 x ₦200bn = "},{"text":"₦10.4 billion","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 6 (shares).","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A paint firm sells ₦84m; the whole market (including it) sells ₦420m. Share = 84/420 x 100 = "},{"text":"20%","bold":true},{"text":". Trap: dividing by sales of rivals only (84/336 = 25%) is wrong."}]},{"text":[{"text":"Firm with 18% against a leader with 27%: relative share = 18/27 = "},{"text":"0.67","bold":true},{"text":" (2 d.p.). The leader's relative share = 27/18 = "},{"text":"1.5","bold":true},{"text":" (above 1 means you lead)."}]},{"text":[{"text":"Current demand 3m units, potential 12m: penetration = 3/12 x 100 = "},{"text":"25%","bold":true},{"text":" (a low index means room to grow)."}]},{"text":[{"text":"Market demand forecast ₦1.5 billion, expected share 8%: sales forecast = 0.08 x ₦1.5bn = "},{"text":"₦120 million","bold":true},{"text":"."}]},{"text":[{"text":"Actual industry sales come from trade associations, government statistics and research firms; comparing your growth with the industry's tells you whether you are gaining or losing share."}]}]}]},{"number":"9.4","title":"Forecasting from what buyers, salespeople and experts say, and what buyers do","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Forecasts rest on 3 information bases: what people "},{"text":"say","bold":true},{"text":" (buyers' intentions, sales-force opinion, expert opinion), what people "},{"text":"do","bold":true},{"text":" (market test), what people "},{"text":"have done","bold":true},{"text":" (time-series and statistical analysis of past sales)."}]},{"text":[{"text":"Usual sequence: macroeconomic forecast, then industry forecast, then company sales forecast."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Survey of buyers' intentions:","bold":true},{"text":" ask buyers what they plan to buy. Most useful when buyers are "},{"text":"few","bold":true},{"text":", "},{"text":"cheap to reach","bold":true},{"text":", have "},{"text":"clear intentions","bold":true},{"text":", will "},{"text":"carry them out","bold":true},{"text":" and are "},{"text":"willing to disclose","bold":true},{"text":" them (strongest for industrial buyers and durables)."}]},{"text":[{"text":"Composite of sales-force opinions (sales-force composite):","bold":true},{"text":" each salesperson estimates sales in his or her "},{"text":"territory","bold":true},{"text":"; estimates are "},{"text":"added up","bold":true},{"text":" and adjusted by management."}]},{"text":[{"text":"Expert opinion:","bold":true},{"text":" dealers, distributors, suppliers, consultants, trade associations. "},{"text":"Delphi method:","bold":true},{"text":" experts give estimates "},{"text":"anonymously","bold":true},{"text":", receive a "},{"text":"summary","bold":true},{"text":" of the group's answers, and "},{"text":"revise over several rounds","bold":true},{"text":" until a "},{"text":"consensus","bold":true},{"text":" emerges."}]},{"text":[{"text":"Market test method:","bold":true},{"text":" launch in a limited, representative area, record "},{"text":"actual purchases","bold":true},{"text":", project to the full market. Best for "},{"text":"new products","bold":true},{"text":", new channels or territories, or when buyers do not plan purchases."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sales-force composite strengths:","bold":true},{"text":" salespeople are closest to customers and spot trends; they trust quotas they helped set; estimates break down by product, territory, customer and salesperson. "},{"text":"Weaknesses:","bold":true},{"text":" bias (over-optimism or pessimism); salespeople may "},{"text":"deliberately underestimate so their quotas are set low","bold":true},{"text":"; they may not see wider economic developments."}]},{"text":[{"text":"Buyers' intentions are weak when buyers are millions of scattered consumers who rarely plan, refuse to share plans, or cannot picture a $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 43, $study_guide$brand-new product."}]},{"text":[{"text":"An Ibadan-only launch of a new Lagos snack to project national sales is a "},{"text":"market test","bold":true},{"text":", not a survey."}]}]},{"type":"paragraph","text":[{"text":"Worked example 7 (buyers' intentions).","bold":true},{"text":" 100,000 households: 20% \"definitely buy\", 30% \"probably buy\". Past conversion: 70% of definites, 10% of probables. Definite buyers = 100,000 x 0.20 x 0.70 = 14,000. Probable buyers = 100,000 x 0.30 x 0.10 = 3,000. Expected buyers = "},{"text":"17,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 8 (sales-force composite).","bold":true},{"text":" Estimates 30,000 + 45,000 + 25,000 = 100,000 units. Management cuts 15% for over-optimism: 100,000 x 0.85 = "},{"text":"85,000 units","bold":true},{"text":". (If the team usually underestimates, management raises the total instead.)"}]},{"type":"paragraph","text":[{"text":"Worked example 9 (weighted expert opinion).","bold":true},{"text":" Forecasts ₦100m, ₦140m, ₦120m with weights 0.2, 0.5, 0.3 (weights sum to 1). Forecast = 0.2(100) + 0.5(140) + 0.3(120) = 20 + 70 + 36 = "},{"text":"₦126 million","bold":true},{"text":". A simple average would be ₦120m; adding the three (₦360m) is a trap."}]},{"type":"paragraph","text":[{"text":"Worked example 10 (market test).","bold":true},{"text":" A test city holds 3% of the target population and sells 12,000 packs. National estimate = 12,000 / 0.03 = "},{"text":"400,000 packs","bold":true},{"text":". Trap: multiplying by 3% instead of dividing."}]}]},{"number":"9.5","title":"Time-series analysis, moving averages and trend projection","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Time-series analysis:","bold":true},{"text":" breaks past sales into "},{"text":"4 components","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Trend (T):","bold":true},{"text":" the long-run, underlying growth or decline (population, capital, technology)."}]},{"text":[{"text":"Cycle (C):","bold":true},{"text":" wave-like movement over "},{"text":"several years","bold":true},{"text":", from general economic activity (booms, recessions)."}]},{"text":[{"text":"Season (S):","bold":true},{"text":" a "},{"text":"recurring pattern within the year","bold":true},{"text":" (weather, holidays, festivals)."}]},{"text":[{"text":"Erratic events (E):","bold":true},{"text":" "},{"text":"unpredictable","bold":true},{"text":" one-off shocks (strikes, fuel scarcity, riots, floods)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Elasticity is not a component.","bold":true}]},{"text":[{"text":"Simple moving average (SMA)","bold":true},{"text":" = sum of sales in the last n periods / n. Purpose: "},{"text":"smooth out short-term random fluctuations","bold":true},{"text":" so the underlying level is clearer."}]},{"text":[{"text":"Weighted moving average (WMA)","bold":true},{"text":" = sum of (weight x sales) / sum of weights; gives "},{"text":"different weights","bold":true},{"text":", usually "},{"text":"more weight to recent","bold":true},{"text":" periods."}]},{"text":[{"text":"Trend projection:","bold":true},{"text":" assumes the "},{"text":"pattern of past sales will continue","bold":true},{"text":". Trend line: Y = a + bX."}]},{"text":[{"text":"Least squares (X coded to sum to zero, e.g. -2, -1, 0, 1, 2):","bold":true},{"text":" a = sum of Y / n; b = sum of XY / sum of X^2. b is the "},{"text":"average yearly increase","bold":true},{"text":"."}]},{"text":[{"text":"Straight-line growth:","bold":true},{"text":" yearly increase = (last value - first value) / number of intervals."}]},{"text":[{"text":"Compound growth:","bold":true},{"text":" forecast = current sales x (1 + g)^t."}]},{"text":[{"text":"Statistical demand analysis:","bold":true},{"text":" statistical procedures (e.g. multiple regression) that find the real factors affecting sales (price, income, population, promotion) and their relative influence."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Umbrella sales rising every April to July in Lagos = "},{"text":"seasonal","bold":true},{"text":". A two-week ticket slump from a sudden fuel scarcity = "},{"text":"erratic","bold":true},{"text":". A recession that lowers car sales for three years = "},{"text":"cyclical","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 11 (SMA).","bold":true},{"text":" Monthly sales: 30, 34, 38, 36, 41 (thousand). 3-month SMA forecast = (38 + 36 + 41) / 3 = 115 / 3 = "},{"text":"38.33 thousand","bold":true},{"text":" (2 d.p.). Use only the "},{"text":"last","bold":true},{"text":" n periods."}]},{"type":"paragraph","text":[{"text":"Worked example 12 (WMA).","bold":true},{"text":" Last three months (oldest first): 200, 220, 260; weights 1, 2, 3 (3 on the most recent). Forecast = (1x200 + 2x220 + 3x260) / (1 + 2 + 3) = (200 + 440 + 780) / 6 = 1,420 / 6 = "},{"text":"236.67 units","bold":true},{"text":" (2 d.p.). Trap: dividing by 3 instead of 6."}]},{"type":"paragraph","text":[{"text":"Worked example 13 (given trend line).","bold":true},{"text":" Y = 120 + 8X, X = 1 for 2020. For 2027, X = 8 (2027 - 2020 + 1). Y = 120 + 8 x 8 = "},{"text":"184","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 14 (least squares).","bold":true},{"text":" Sales 2021 to 2025: 10, 13, 15, 18, 19 (₦m); X = -2, -1, 0, 1, 2."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Sum of Y = 75; a = 75 / 5 = 15."}]},{"text":[{"text":"XY: -20, -13, 0, 18, 38; sum = 23. Sum of X^2 = 4 + 1 + 0 + 1 + 4 = 10. b = 23 / 10 = 2.3."}]},{"text":[{"text":"2026 is X = 3: Y = 15 + 2.3 x 3 = "},{"text":"₦21.9 million","bold":true},{"text":"."}]},{"text":[{"text":"(With an even number of years, code X as -3, -1, 1, 3, so each year is 2 units of X.)"}]}]},{"type":"paragraph","text":[{"text":"Worked example 15 (straight-line growth).","bold":true},{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 44, $study_guide$" ₦60m in 2020, ₦90m in 2025. Intervals = 5 (not 6). Increase = 30 / 5 = ₦6m a year. 2026 = 90 + 6 = "},{"text":"₦96 million","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 16 (compound growth).","bold":true},{"text":" ₦80m now, 5% a year. In two years = 80 x 1.05^2 = 80 x 1.1025 = "},{"text":"₦88.2 million","bold":true},{"text":". Trap: simple growth (80 + 4 + 4 = ₦88m) is wrong for compound growth."}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market levels: potential, available (interest, income, access), qualified available, target (served), penetrated."}]},{"text":[{"text":"Market demand = total volume bought by a defined group, area, time, environment and programme; market minimum = sales with no marketing spend; market potential = limit as industry spend approaches infinity."}]},{"text":[{"text":"Primary demand = product class; selective = one brand."}]},{"text":[{"text":"Company demand = share x market demand; sales forecast = expected sales under the chosen plan; sales potential = limit as company effort rises relative to rivals."}]},{"text":[{"text":"Quota is set above, budget below, the forecast."}]},{"text":[{"text":"Q = n x q x p; market build-up adds up all buyers; chain ratio multiplies a base by percentages; BPI = 0.5 income + 0.3 retail sales + 0.2 population."}]},{"text":[{"text":"Market share = own sales / total market; relative share = own share / largest rival's; penetration = current demand / potential."}]},{"text":[{"text":"Methods: buyers' intentions, sales-force composite, expert opinion (Delphi), market test, time series, statistical demand analysis."}]},{"text":[{"text":"Time series: trend, cycle, season, erratic; SMA smooths, WMA weights recent periods more; least squares a = sum Y / n, b = sum XY / sum X^2."}]}]}],"theory":{"itemId":"d53c397c-38d8-5169-9abf-0ee638ad1991","question":[{"type":"paragraph","text":[{"text":"In a city of 800,000 adults, 25% drink yoghurt and each drinker buys 40 cups a year at ₦500. (a) What is the annual market potential in naira? (b) If a firm expects a 15% share, what is its sales forecast?"}]}]},"practice":[{"topic":"Market Measurement and Forecasting","named":false}]}},{"kind":"note","itemId":"e137ffa6-cdbd-5588-a055-332b8b33a255","sourceKey":"guide-topic:10","position":10,"payload":{"title":"Marketing in the Digital and Social Media Era","body":"The meaning of digital marketing and e-marketing and how they differ from traditional marketing; the main digital channels (search, SEO and PPC, display, retargeting, content, email, mobile, affiliate, influencer, viral); social media marketing, its platforms, social commerce and e-commerce; paid, owned and earned media, user-generated content and eWOM; the advantages and challenges of digital marketing in Nigeria; and the six campaign metrics with their formulas.","noteType":"guide_topic","number":10,"mustKnow":[{"text":"The meaning of digital marketing and e-marketing and how they differ from traditional marketing; the main digital channels (search, SEO and PPC, display, retargeting, content, email, mobile, affiliate, influencer, viral); social media marketing, its platforms, social commerce and e-commerce; paid, owned and earned media, user-generated content and eWOM; the advantages and challenges of digital marketing in Nigeria; and the six campaign metrics with their formulas."}],"lessons":[{"number":"10.1","title":"Meaning of digital marketing and how it differs from traditional marketing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Digital marketing:","bold":true},{"text":" the use of digital channels and technologies, such as websites, search engines, social media, email and mobile apps, to promote products and engage customers."}]},{"text":[{"text":"E-marketing (internet or online marketing):","bold":true},{"text":" marketing products and services over the internet, through websites, online ads, email and similar tools. In an exam, treat it as the internet side of digital marketing."}]},{"text":[{"text":"Social media marketing:","bold":true},{"text":" using platforms such as Facebook, Instagram, TikTok, X (Twitter) and LinkedIn to build brand awareness, interact with customers and promote offers."}]},{"text":[{"text":"E-commerce:","bold":true},{"text":" buying and selling goods and services over the internet (e.g. Jumia, Konga, Jiji)."}]},{"text":[{"text":"Online advertising:","bold":true},{"text":" paid messages shown on the internet, e.g. a banner ad for a hotel on a Nigerian news website."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Traditional marketing"}],[{"text":"Digital marketing"}]],"rows":[[[{"text":"Media"}],[{"text":"Print, radio, TV, billboards, handbills"}],[{"text":"Websites, search, social media, email, mobile"}]],[[{"text":"Direction"}],[{"text":"Mostly one-way mass communication"}],[{"text":"Two-way and interactive: customers reply, comment, share"}]],[[{"text":"Targeting"}],[{"text":"Broad, by medium and location"}],[{"text":"Precise: by location, age, interests, behaviour"}]],[[{"text":"Measurement"}],[{"text":"Slow and approximate"}],[{"text":"Precise and real-time: views, clicks, sales"}]],[[{"text":"Cost"}],[{"text":"Often high entry cost"}],[{"text":"Can start small; low cost per person reached"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Is it digital or not?","bold":true},{"text":" A sponsored Instagram post, optimising a website to rank higher on search engines and an email newsletter are all digital marketing. Painting a shop's name on a roadside wall, a handbill at a bus stop, a jingle on a market loudspeaker and a billboard on Third Mainland Bridge are "},{"text":"not","bold":true},{"text":"; they are traditional (outdoor or print) methods."}]},{"text":[{"text":"The single feature that most clearly separates social media marketing from newspaper or TV advertising is "},{"text":"two-way, interactive communicat$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 45, $study_guide$ion","bold":true},{"text":". Options saying social media is \"one-way\", \"cannot be measured\" or \"cannot be targeted\" are always wrong."}]},{"text":[{"text":"Technology is a fast-changing force in the marketing environment: it creates opportunities to win market share and makes older products obsolete. Electronic banking cut banks' costs and made services more convenient; GTBank now serves many customers through apps and USSD."}]},{"text":[{"text":"New business models:","bold":true},{"text":" technology firms such as Uber, Airbnb and Amazon (in Nigeria, Bolt, Jumia and Paystack) have reshaped whole industries. Marketers should think in terms of the value delivered to the client and experiment with new pricing structures."}]},{"text":[{"text":"360-degree marketing:","bold":true},{"text":" be present wherever customers look for help, which is increasingly online. Firms that blend online and offline methods grow fastest and are most profitable; assuming \"my customers don't go online\" is risky."}]}]}]},{"number":"10.2","title":"The main digital marketing channels","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Search engine optimisation (SEO):","bold":true},{"text":" improving a website so it ranks higher in the "},{"text":"free (organic)","bold":true},{"text":" search results. The firm does not pay per click."}]},{"text":[{"text":"Pay-per-click (PPC) search advertising:","bold":true},{"text":" buying "},{"text":"sponsored listings","bold":true},{"text":" by bidding on keywords; the advertiser "},{"text":"pays each time the ad is clicked","bold":true},{"text":". SEO plus paid search together are broadly called "},{"text":"search engine marketing (SEM)","bold":true},{"text":", though some use SEM for paid search alone."}]},{"text":[{"text":"Display (banner) advertising:","bold":true},{"text":" image or video ads on other websites and apps."}]},{"text":[{"text":"Retargeting (remarketing):","bold":true},{"text":" showing ads to people who visited a site or viewed a product but left without buying, as they browse other websites and social media."}]},{"text":[{"text":"Content marketing:","bold":true},{"text":" creating and sharing valuable, relevant material (blog posts, how-to videos, infographics) to attract and engage a clearly defined audience "},{"text":"rather than directly pushing a sales message","bold":true},{"text":"."}]},{"text":[{"text":"Email marketing:","bold":true},{"text":" sending newsletters and offers by email. It should be "},{"text":"permission-based","bold":true},{"text":"."}]},{"text":[{"text":"Mobile marketing:","bold":true},{"text":" messages, promotions and content delivered through mobile phones: "},{"text":"SMS","bold":true},{"text":", in-app ads, mobile websites, and "},{"text":"location-based (geo-targeted)","bold":true},{"text":" offers sent when the phone is near a place."}]},{"text":[{"text":"Affiliate marketing:","bold":true},{"text":" paying a "},{"text":"commission","bold":true},{"text":" to bloggers or website owners for "},{"text":"each sale","bold":true},{"text":" made through their special link or code."}]},{"text":[{"text":"Influencer marketing:","bold":true},{"text":" partnering with people who have a large or highly engaged online following (content creators, celebrities) so they recommend the brand to their followers."}]},{"text":[{"text":"Viral marketing:","bold":true},{"text":" a message so entertaining or useful that people pass it on rapidly online; the "},{"text":"digital version of word-of-mouth","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Permission-based marketing:","bold":true},{"text":" sending messages only to people who have agreed ("},{"text":"opted in","bold":true},{"text":"), e.g. by subscribing to a newsletter."}]},{"text":[{"text":"Spam:","bold":true},{"text":" unsolicited, unwanted commercial messages sent in bulk to people who did not ask for them."}]},{"text":[{"text":"Micro-influencers:","bold":true},{"text":" smaller, more focused audiences that often show "},{"text":"higher engagement and trust","bold":true},{"text":" than celebrity (\"mega\") influencers."}]},{"text":[{"text":"Marketing automation:","bold":true},{"text":" software that automates large parts of marketing, such as follow-up emails, lead generation and lead nurturing."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"SEO versus PPC","bold":true},{"text":" is the favourite trap. SEO = organic, earned over time, no fee per click. PPC = paid, instant, charged per click. An option saying \"SEO is paid per click\" or \"PPC is always free\" is reversed. A Lagos furniture store bidding on \"office chairs Lagos\" so its sponsored link sits at the top, paying only when someone clicks, is "},{"text":"PPC","bold":true},{"text":", not SEO."}]},{"text":[{"text":"Content marketing:","bold":true},{"text":" a Nigerian skincare brand posting free weekly videos on caring for skin in hot, humid weather, without asking viewers to buy, is content marketing. The sale comes later, from trust."}]},{"text":[{"text":"Mobile marketing in practice:","bold":true},{"text":" a supermarket texting customers who gave their numbers at checkout about a weekend discount is "},{"text":"SMS (mobile) marketing","bold":true},{"text":". A restaurant in Ikeja whose app sends an offer only when the customer is within 1 km is "},{"text":"location-based (geo-targeted) mobile marketing","bold":true},{"text":". MTN, Airtel and Glo also push offers by SMS and USSD."}]},{"text":[{"text":"Retargeting:","bold":true},{"text":" a student views a laptop on Jumia, leaves, and then sees the same laptop in ads on other sites for days. That is retargeting, not viral marketing or market testing."}]},{"text":[{"text":"Affiliate versus influencer:","bold":true},{"text":" the affiliate is paid "},{"text":"per sale","bold":true},{"text":" through a tracked link or code; the influencer is usually paid to "},{"text":"re$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 46, $study_guide$commend","bold":true},{"text":". \"Commission per sale through a link\" means affiliate."}]},{"text":[{"text":"Hyper-targeted advertising:","bold":true},{"text":" online ads can now reach specific companies, job roles or niche interests, and link to downloadable content that proves expertise. This suits professional service firms that traditional mass advertising served poorly."}]},{"text":[{"text":"Permission versus spam:","bold":true},{"text":" opt-in lists get better responses; spam damages trust. In Nigeria, personal data is protected by the Nigeria Data Protection Act 2023."}]}]}]},{"number":"10.3","title":"Social media marketing, social commerce and types of media","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Main platforms:","bold":true},{"text":" Facebook, Instagram, TikTok, X (Twitter), LinkedIn (professional and B2B), YouTube, WhatsApp."}]},{"text":[{"text":"Social commerce:","bold":true},{"text":" buying and selling directly within social media platforms, e.g. a vendor showing products in a "},{"text":"WhatsApp Business catalogue","bold":true},{"text":" and taking orders in the chat, or selling through Instagram shops."}]},{"text":[{"text":"User-generated content (UGC):","bold":true},{"text":" photos, videos, reviews and posts about a brand "},{"text":"created and shared by customers","bold":true},{"text":", not by the company."}]},{"text":[{"text":"Electronic word-of-mouth (eWOM):","bold":true},{"text":" positive or negative comments about products and brands that consumers share with each other through reviews, social media posts and online forums."}]}]},{"type":"paragraph","text":[{"text":"The three types of media (POE):","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}],[{"text":"Examples"}]],"rows":[[[{"text":"Paid","bold":true}],[{"text":"Exposure the brand pays for"}],[{"text":"Boosted (sponsored) Instagram post, PPC ads, banner ads, paid influencer posts"}]],[[{"text":"Owned","bold":true}],[{"text":"Channels the brand itself controls"}],[{"text":"Its own website, Instagram page, company blog, app, email list"}]],[[{"text":"Earned","bold":true}],[{"text":"Free exposure others give the brand"}],[{"text":"An unpaid blogger's review, shares, mentions, press coverage, eWOM"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classify carefully.","bold":true},{"text":" A fashion brand paying to \"boost\" its Instagram post into the feeds of 50,000 targeted users = "},{"text":"paid","bold":true},{"text":". The same brand's Instagram page itself = "},{"text":"owned","bold":true},{"text":". A food blogger, "},{"text":"not paid","bold":true},{"text":", posting a glowing review of a new Lekki restaurant that thousands share = "},{"text":"earned","bold":true},{"text":" for the restaurant. If money changes hands for the exposure, it is paid; if the brand runs the channel, it is owned; if others give it freely, it is earned."}]},{"text":[{"text":"Hashtag challenges:","bold":true},{"text":" a Nigerian telecoms brand that creates a branded hashtag and invites customers to post short dance videos, with data bundles as prizes, is aiming to "},{"text":"generate engagement and user-generated content that spreads the brand message","bold":true},{"text":". It does not replace distribution channels or set sales quotas."}]},{"text":[{"text":"Why UGC and eWOM matter:","bold":true},{"text":" buyers trust fellow customers more than the firm's adverts, so reviews and posts shape the information-search stage of buying."}]},{"text":[{"text":"Social commerce is huge in Nigeria:","bold":true},{"text":" many small vendors run their whole business through Instagram and WhatsApp, taking payment by bank transfer or through Paystack or Flutterwave links and delivering by dispatch rider."}]},{"text":[{"text":"E-commerce","bold":true},{"text":" is all online buying and selling (Jumia, Konga, a brand's own store); social commerce is the part that happens "},{"text":"inside","bold":true},{"text":" social platforms."}]}]}]},{"number":"10.4","title":"Advantages and challenges of digital marketing in Nigeria","mustKnow":[{"type":"paragraph","text":[{"text":"Advantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Wide reach at relatively low cost;","bold":true},{"text":" a small business can start with a small budget."}]},{"text":[{"text":"Precise targeting","bold":true},{"text":" by location, age, interests and behaviour."}]},{"text":[{"text":"Measurable results:","bold":true},{"text":" clicks, views and sales can be measured precisely and quickly (real time)."}]},{"text":[{"text":"Two-way interaction:","bold":true},{"text":" quick conversation with customers; feedback and complaints are heard fast."}]},{"text":[{"text":"Always on:","bold":true},{"text":" customers can see offers and buy 24 hours a day, from anywhere."}]},{"text":[{"text":"Flexibility:","bold":true},{"text":" campaigns can be changed or stopped quickly based on results."}]},{"text":[{"text":"Relationship building:","bold":true},{"text":" regular contact through email, social media and content builds loyalty."}]}]},{"type":"paragraph","text":[{"text":"Challenges:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cost of mobile data and unreliable power supply","bold":true},{"text":" limit how often some customers go online."}]},{"text":[{"text":"Online fraud and lack of trust:","bold":true},{"text":" some consumers fear being scammed and hesitate to pay online or share personal details, which slows online sales."}]},{"text":[{"text":"Negative messages spread fast","bold":true},{"text":" and are difficult for the firm to control."}]},{"text":[{"text":"Ad clutter and ad avoidance:","bold":true},{"text":" too many ads lead people to install ad blockers or ignore banner ads."}]},{"text":[{"text":"Uneven internet access and digital literacy,","bold":true},{"text":" especially in rural areas."}]},{"te$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 47, $study_guide$xt":[{"text":"Privacy and data protection concerns,","bold":true},{"text":" and spam annoying customers."}]},{"text":[{"text":"Fast-changing platforms and algorithms,","bold":true},{"text":" which demand constant skills and effort; delivery and logistics problems for online orders."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NOT an advantage trap:","bold":true},{"text":" \"it guarantees that no customer will ever post a negative comment\" is false. Social media gives customers a public voice, so firms must manage complaints. Reach, targeting and two-way interaction are real advantages."}]},{"text":[{"text":"Spread of bad news:","bold":true},{"text":" a customer posts a video complaint about a Lagos bakery's spoiled cake and within hours it is shared thousands of times. This shows that negative messages spread quickly and are hard to control. The right response is fast, polite, public handling of the complaint."}]},{"text":[{"text":"Trust and payment:","bold":true},{"text":" cash on delivery is common on Jumia and in social commerce because many buyers fear online fraud; trusted payment gateways and clear return policies build confidence."}]},{"text":[{"text":"Ad avoidance","bold":true},{"text":" is not price discrimination or segmentation; it is consumers tuning out because of too many ads."}]},{"text":[{"text":"Options such as \"online results can never be measured\" or \"no Nigerians use mobile phones\" are false challenges."}]}]}]},{"number":"10.5","title":"Digital marketing metrics and computations","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Click-through rate (CTR)","bold":true},{"text":" = clicks / impressions x 100"}]},{"text":[{"text":"Cost per thousand impressions (CPM)","bold":true},{"text":" = total cost / impressions x 1,000"}]},{"text":[{"text":"Cost per click (CPC)","bold":true},{"text":" = total ad spend / number of clicks"}]},{"text":[{"text":"Conversion rate","bold":true},{"text":" = orders (conversions) / visitors (or clicks) x 100"}]},{"text":[{"text":"Engagement rate","bold":true},{"text":" = (likes + comments + shares) / followers x 100"}]},{"text":[{"text":"Return on ad spend (ROAS)","bold":true},{"text":" = revenue from ads / ad spend"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Impression:","bold":true},{"text":" one showing of an ad on a screen. "},{"text":"Click:","bold":true},{"text":" one tap or click on it. "},{"text":"Conversion:","bold":true},{"text":" the visitor does what you want (buys, signs up)."}]},{"text":[{"text":"Cost per acquisition (CPA)","bold":true},{"text":" = ad spend / number of orders: the cost of winning one customer."}]},{"text":[{"text":"Other things firms track: reach, website traffic, followers, likes, shares, comments."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example (one campaign, every metric).","bold":true},{"text":" A Lagos shoe store spends ₦60,000 on Instagram ads. The ads get 200,000 impressions and 1,500 clicks. 45 of the people who clicked place an order, at an average of ₦8,000 each."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CPM = 60,000 / 200,000 x 1,000 = 0.3 x 1,000 = "},{"text":"₦300","bold":true},{"text":" per thousand impressions."}]},{"text":[{"text":"CTR = 1,500 / 200,000 x 100 = 0.0075 x 100 = "},{"text":"0.75%","bold":true},{"text":"."}]},{"text":[{"text":"CPC = 60,000 / 1,500 = "},{"text":"₦40","bold":true},{"text":" per click."}]},{"text":[{"text":"Conversion rate = 45 / 1,500 x 100 = 0.03 x 100 = "},{"text":"3%","bold":true},{"text":"."}]},{"text":[{"text":"CPA = 60,000 / 45 = "},{"text":"₦1,333.33","bold":true},{"text":" per order (rounded to the nearest kobo)."}]},{"text":[{"text":"Revenue = 45 x 8,000 = ₦360,000. ROAS = 360,000 / 60,000 = "},{"text":"6","bold":true},{"text":" (₦6 of sales for every ₦1 of ads)."}]}]},{"type":"paragraph","text":[{"text":"Engagement rate example.","bold":true},{"text":" A Nigerian creator with 40,000 followers gets 1,200 likes, 300 comments and 100 shares on a sponsored post. Total engagements = 1,200 + 300 + 100 = 1,600. Engagement rate = 1,600 / 40,000 x 100 = 0.04 x 100 = "},{"text":"4%","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Traps to avoid:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CTR","bold":true},{"text":" divides clicks by "},{"text":"impressions","bold":true},{"text":", never impressions by clicks. With 1,200 clicks from 80,000 impressions, CTR = 1,200 / 80,000 x 100 = "},{"text":"1.5%","bold":true},{"text":"; 66.67 is the upside-down answer and 0.015 forgets to multiply by 100."}]},{"text":[{"text":"CPM","bold":true},{"text":" must be multiplied by "},{"text":"1,000","bold":true},{"text":". ₦90,000 for 600,000 impressions: 90,000 / 600,000 = ₦0.15 per impression, x 1,000 = "},{"text":"₦150","bold":true},{"text":". ₦0.15 is the cost of one impression, not a thousand."}]},{"text":[{"text":"CPC","bold":true},{"text":" divides spend by clicks: ₦75,000 / 2,500 = "},{"text":"₦30","bold":true},{"text":". Clicks / spend gives 0.033, which is meaningless."}]},{"text":[{"text":"Conversion rate:","bold":true},{"text":" 120 orders from 4,000 visitors = 120 / 4,000 x 100 = "},{"text":"3%","bold":true},{"text":" (not 30% or 0.03%)."}]},{"text":[{"text":"Engagement rate","bold":true},{"text":" adds all three actions before dividing: (900 + 250 + 350) / 25,000 x 100 = 1,500 / 25,000 x 100 = "},{"text":"6%","bold":true},{"text":". Using likes alone (3.6%) is wrong."}]},{"text":[{"text":"ROAS","bold":true},{"text":" is a ratio, not a percentage: ₦1,800,000 / ₦400,000 = "},{"text":"4.5","bold":true},{"text":", meaning ₦4.50 of sales per ₦1 spent. The upside-down 0.22 is wrong, and 450 is not the ratio."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Digital marketing = digital channels and technologies (websites, search, social media, email, mobile apps) to promote and $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 48, $study_guide$engage; e-marketing = marketing over the internet."}]},{"text":[{"text":"Digital beats traditional on targeting, real-time measurement and two-way interaction; a painted wall, billboard or handbill is not digital."}]},{"text":[{"text":"SEO = free organic ranking; PPC = sponsored listing, pay per click; SEO + paid search = SEM."}]},{"text":[{"text":"Content (value, not hard sell), email (permission, not spam), mobile (SMS, geo-targeted), affiliate (commission per sale), influencer (micro = higher engagement), viral (digital word-of-mouth), retargeting (follows people who left)."}]},{"text":[{"text":"Social commerce = selling inside social platforms (WhatsApp Business catalogue); UGC = customer-made content; eWOM = consumers sharing opinions online."}]},{"text":[{"text":"Paid (boosted post), owned (own website, page, blog), earned (unpaid review, shares)."}]},{"text":[{"text":"Advantages: low cost, targeting, measurement, interaction. Challenges: data cost and power, fraud and trust, fast-spreading complaints, ad clutter and avoidance."}]},{"text":[{"text":"CTR = clicks / impressions x 100; CPM = cost / impressions x 1,000; CPC = spend / clicks; conversion = orders / visitors x 100; engagement = (likes + comments + shares) / followers x 100; ROAS = revenue / ad spend."}]}]}],"theory":{"itemId":"8c974dc1-db1b-54a4-b759-12161523332f","question":[{"type":"paragraph","text":[{"text":"An online store in Abuja spends ₦150,000 on a display campaign that delivers 500,000 impressions and 2,000 clicks. 80 of those visitors buy, producing ₦600,000 in sales. Calculate the CPM, CTR, CPC, conversion rate and ROAS."}]}]},"practice":[{"topic":"Marketing in the Digital and Social Media Era","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"332e0367-626a-5b48-8fc3-ecc4d2116468","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"Classify each activity into its marketing function and group: (i) a warehouse holds yam until the lean season; (ii) a bank gives a distributor a 60-day trade loan; (iii) a trader negotiates and hands over goods to a buyer; (iv) eggs are sorted by size into crates."},"answer":{"kind":"model_answer","itemId":"af141f6b-ed23-57e2-a149-5b3f3a6c98d8","sourceKey":"guide-answer:1","payload":{"body":"(i) Storage, a physical supply function (time utility). (ii) Financing, a facilitating function. (iii) Selling, an exchange function (possession utility). (iv) Standardisation and grading, a facilitating function."}}},{"kind":"theory_question","itemId":"66f699b8-e513-5bcb-ac28-6a033edfb3ae","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"A Lagos ferry operator's target for the first quarter was ₦12,000,000 in fares, but actual fares were ₦9,600,000. Boats are full at rush hours but nearly empty at midday. (a) Compute the shortfall and the achievement rate. (b) Name the demand state and the matching marketing task, and say which stage of the marketing management process the computation belongs to."},"answer":{"kind":"model_answer","itemId":"ad3e1a62-158c-5439-975b-6594ab0e3851","sourceKey":"guide-answer:2","payload":{"body":"• (a) Shortfall = ₦12,000,000 - ₦9,600,000 = ₦2,400,000. Shortfall % = 2,400,000 / 12,000,000 x 100 = 20%. Achievement = 9,600,000 / 12,000,000 x 100 = 80%.\n• (b) Demand that swings by hour is irregular demand; the task is synchromarketing, e.g. cheaper midday fares. Comparing actual results with a target and correcting the gap is marketing control."}}},{"kind":"theory_question","itemId":"fb555ddc-45af-569f-a0c9-b63d7a28d44a","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"Distinguish the selling concept from the marketing concept, and state the three behavioural components of market orientation."},"answer":{"kind":"model_answer","itemId":"2b37878f-2fb6-5492-b6c9-32f9ae9d439a","sourceKey":"guide-answer:3","payload":{"body":"The selling concept holds that consumers will not buy enough unless the firm sells and promotes aggressively: it starts at the factory, focuses on existing products, uses selling and promoting, and seeks profit through sales volume (seller's needs, inside-out). The marketing concept holds that goals are reached by knowing target customers' needs and satisfying them better than competitors: it starts with the market, focuses on customer needs, uses integrated marketing, and seeks profit through customer satisfaction (buyer's needs, outside-in). Market orientation puts the marketing concept into practice through (1) customer orientation, (2) competitor orientation and (3) inter-functional coordination, guided by long-term focus and profitability."}}},{"kind":"theory_question","itemId":"5b9e7ccf-c51f-5566-a2aa-618ec4cf7099","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"Distinguish the micro environment from the macro environment and give three forces in each."},"answer":{"kind":"model_answer","itemId":"0d9f0aca-a262-5f62-ba8f-97e1d580333c","sourceKey":"guide-answer:4","payload":{"body":"The micro (task) environment is closely linked to the firm and directly affects its activities: suppliers (provide inputs), marketing intermediaries (promote, sell, distribute), customers (buy for final consumption) and also competitors and publics. The macro (broad) environment is the larger set of societal forces beyond the firm's control that change constantly and bring opportunities and threats: demographic (population variables), economic (cost structure and purchasing power), technological (pace of change, R&D, regulation), plus natural, political-legal and socio-cultural."}}},{"kind":"theory_question","itemId":"72cecbbf-ccbc-54ba-b26e-59ad73fff229","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"A Lagos bakery that has always bought flour from one miller decides to test a new flour blend and asks two other millers to quote. Name the buy class, and explain how it differs from the other two buy classes."},"answer":{"kind":"model_answer","itemId":"757fa62c-53e4-5ffe-b343-b9598f34bbfb",$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua111', 49, $study_guide$"sourceKey":"guide-answer:5","payload":{"body":"This is a modified rebuy: a recurring purchase made less routine because the bakery is changing the specification and considering new suppliers. A straight rebuy would be a routine reorder of the same flour from the same miller with no changes, because the bakery has extensive experience. A new task would be a first-ever purchase (e.g. its first industrial oven), needing the most information search and the largest buying centre. There are three buy classes in all."}}},{"kind":"theory_question","itemId":"e1dcb7c5-e773-5f9c-9c3d-921f683a9199","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"Industry sales of packaged juice in Lagos were ₦2,500 million last year and ₦2,600 million this year. Brand A sold ₦400 million last year and ₦390 million this year. Find Brand A's market share each year, the industry growth rate, and the likely PLC stage of the category. Suggest two strategies."},"answer":{"kind":"model_answer","itemId":"6d95bb6d-0e43-5317-b1b3-d39757cadeb4","sourceKey":"guide-answer:6","payload":{"body":"• Last year share = (400 ÷ 2,500) × 100 = 16%. This year share = (390 ÷ 2,600) × 100 = 15%.\n• Industry growth = (2,600 − 2,500) ÷ 2,500 × 100 = 4%. Brand A's own sales fell by (390 − 400) ÷ 400 × 100 = −2.5%.\n• Sales are near their peak with only slow growth and competitors taking share, so the category is in maturity.\n• Strategies: modify the market (new users or uses, e.g. juice for school lunches) and modify the product or mix (new flavours, smaller packs, promotions that encourage brand switching while stressing brand differences)."}}},{"kind":"theory_question","itemId":"be825d80-15e4-575d-ba66-de4e51851e7b","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"A noodle maker finds 480,000 noodle buyers in Ibadan, of whom 25% are students. It sells to 18,000 students. (a) How large is the student segment? (b) What share of that segment does the firm hold? (c) Which segmentation base is \"students\" and which targeting strategy would the firm use if it served only this group?"},"answer":{"kind":"model_answer","itemId":"f490997f-4137-515d-beb7-98de620a5c9b","sourceKey":"guide-answer:7","payload":{"body":"• (a) Segment size = 480,000 x 0.25 = 120,000 students.\n• (b) Share of segment = 18,000 / 120,000 x 100 = 15%.\n• (c) Students is a demographic base (occupation and age or life stage). Serving only this one segment is concentrated (niche) marketing."}}},{"kind":"theory_question","itemId":"b054ce88-2258-5fe6-ad23-e532ea5087ed","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"Three paint manufacturers sell to ten hardware shops. Each sales contact costs ₦1,500. How much does the industry save if all trade passes through one wholesaler?"},"answer":{"kind":"model_answer","itemId":"f413f0fc-251b-5b98-b739-82f4ad6519d6","sourceKey":"guide-answer:8","payload":{"body":"• Direct contacts = 3 × 10 = 30; cost = 30 × ₦1,500 = ₦45,000.\n• Contacts through one wholesaler = 3 + 10 = 13; cost = 13 × ₦1,500 = ₦19,500.\n• Saving = ₦45,000 − ₦19,500 = ₦25,500 (17 fewer contacts)."}}},{"kind":"theory_question","itemId":"d53c397c-38d8-5169-9abf-0ee638ad1991","sourceKey":"guide-theory:9","position":9,"payload":{"prompt":"In a city of 800,000 adults, 25% drink yoghurt and each drinker buys 40 cups a year at ₦500. (a) What is the annual market potential in naira? (b) If a firm expects a 15% share, what is its sales forecast?"},"answer":{"kind":"model_answer","itemId":"99ab9a59-0b83-5f8a-a24f-87c86604c9eb","sourceKey":"guide-answer:9","payload":{"body":"• (a) Drinkers = 800,000 x 0.25 = 200,000. Cups = 200,000 x 40 = 8,000,000. Value = 8,000,000 x ₦500 = ₦4,000,000,000 (₦4 billion). This is the chain-ratio method combined with Q = n x q x p.\n• (b) Sales forecast = 0.15 x ₦4bn = ₦600 million."}}},{"kind":"theory_question","itemId":"8c974dc1-db1b-54a4-b759-12161523332f","sourceKey":"guide-theory:10","position":10,"payload":{"prompt":"An online store in Abuja spends ₦150,000 on a display campaign that delivers 500,000 impressions and 2,000 clicks. 80 of those visitors buy, producing ₦600,000 in sales. Calculate the CPM, CTR, CPC, conversion rate and ROAS."},"answer":{"kind":"model_answer","itemId":"7e0e79bb-aed4-5dcd-adbc-9cf5177e8e4b","sourceKey":"guide-answer:10","payload":{"body":"• CPM = 150,000 / 500,000 x 1,000 = 0.3 x 1,000 = ₦300.\n• CTR = 2,000 / 500,000 x 100 = 0.004 x 100 = 0.4%.\n• CPC = 150,000 / 2,000 = ₦75.\n• Conversion rate = 80 / 2,000 x 100 = 0.04 x 100 = 4%.\n• ROAS = 600,000 / 150,000 = 4 (₦4 of sales per ₦1 of advertising)."}}}]}$study_guide$);
